insert into clubs (titanlink_id, name, summary, description, website_key, status, categories, tags) values
  ('430388', 'Able Business Association', 'ABLE shall exist to build a tight-knit community of Christian undergraduate business students and professionals committed to living out Gospel-centered fellowship. Through mentorship, and professional development opportunities we seek to grow faithfully.', 'ABLE shall exist to build a tight-knit community of Christian undergraduate business students and professionals committed to living out Gospel-centered fellowship. Through experiential activities, mentorship, and professional development opportunities, we seek to integrate faith with business excellence.', 'ablecsuf', 'Active', '{"College of Business and Economics"}', '{"business","career","faith","mentorship"}'),
  ('132845', 'Acacia Group', 'A club for CSUF graduate students pursuing an M.A. in English, emphasizing their professional development as educators and scholars.', 'The Acacia Group is a club for CSUF graduate students pursuing a Master of Arts in English, emphasizing their professional development as educators and scholars. We offer workshops on pedagogy, particularly first-year composition pedagogy to assist Teaching Associates in the graduate program, and on professional academic activities such as presenting at conferences and writing a CV. We also sponsor an annual conference in the early spring. A call for papers is distributed throughout the CSU system and the country, and both graduate and undergraduate students are encouraged to submit their critical essays.', 'theacaciagroup', 'Active', '{"Special Interest","College of Humanities & Social Sciences","Social"}', '{"career","social"}'),
  ('132690', 'Accounting Society', 'The Accounting Society is a professional student organization committed to exposing students to opportunities for networking and career development that prepares them for the financial and accounting world.', 'Throughout each semester, the Accounting Society organizes a variety of networking events that help facilitate interactions between members and employers. Simply put, we bring the employers to you. If you are considering a career in public accounting or want to strengthen your professional image, joining the Accounting Society is a must. We have various training programs and workshops to better prepare members for networking and recruiting with professionals. This ensures that members are able to maximize their recruiting experiences, increasing the chances they will graduate from CSUF with a full-time offer. There is a reason why we are the largest club on campus. Come find out today!', 'csufas', 'Active', '{"Career Planning","College of Business and Economics"}', '{"business","career"}'),
  ('348878', 'ACM SIGGRAPH', 'ACM SIGGRAPH is a student chapter focused on fostering a diverse community for students interested in the future of computer graphics, interactive techniques, and emerging technologies associated with ACM SIGGRAPH.', 'ACM SIGGRAPH is a student chapter focused on fostering a diverse membership community for students at CSU Fullerton that promotes and inspires researchers, artists, developers, filmmakers, and scientists whose core values help to shape the future of computer graphics, interactive techniques, and emerging technologies in the specialized fields associated with ACM SIGGRAPH. Chapter members may be interested in careers in animation, games, VR/AR, scientific research, software development, visual effects, computer science, engineering, and more. Each semester, we host various events, including our professional speaker events, workshops, demonstrations, networking events, portfolio-building projects, studio visits, and more. Members are encouraged to attend the annual SIGGRAPH conference to see the latest technological advancements and network with other like-minded professionals in the computer graphics and interactive technologies fields. To stay up to date with future events, please follow our Linktree to check our social media and join us on our Discord server. If you have any questions or inquiries about the chapter, please email us at fullerton-chapter@acmsiggraph.org', 'csufacmsiggraph', 'Active', '{"Special Interest","College of Engineering and Computer Science","College of the Arts","Technology"}', '{"arts","technology"}'),
  ('382503', 'Adobe @ Fullerton', 'This club is to have a creative space for students to express themselves through art using Adobe''s programs from the Creative Cloud. Students can socialize with fellow peers in the club while doing recreational activities.', 'The purpose of this organization is to have a creative space for students to express themselves through Adobe''s programs within the Creative Cloud. Students can do this by participating in workshops to help develop their skills using available applications in the Creative Suite that are free for all CSUF students. Students can socialize with fellow peers in the club while doing recreational activities.', 'adobe_fullerton', 'Active', '{"Special Interest","Recreation","College of the Arts","College of Business and Economics","Social","Technology"}', '{"arts","recreation","social","technology"}'),
  ('132852', 'Adventure Club', 'The purpose of Adventure Club is to create a platform for students interested in various outdoor activities like hiking, camping, and kayaking.', '​The purpose of the Adventure Club is to create a social platform for students of California State University Fullerton who are interested in outdoor activities such as hiking, camping, and kayaking . This club aims to help like-minded students with passion and enthusiasm for the outdoors find others with similar interests . It will also encourage students to explore California''s beautiful nature and preserve the public lands we utilize. Follow us on Instagram @AdventureCSUF', 'csufadventureclub', 'Active', '{"Recreation","Outdoors","Social"}', '{"outdoors","recreation","social"}'),
  ('132962', 'Advertising Club', 'We are a premiere organization offering members at CSUF a forum for creative growth and a bridge between campus and career in the advertising industry.', 'We are a premier organization for students passionate about advertising, branding, and creative strategy. We provide a space for members to grow creatively, build professional skills, and connect with industry leaders. Through workshops, guest speakers, portfolio reviews, and hands-on projects, we serve as a bridge between campus life and a future career in the advertising world. Whether you''re an aspiring copywriter, strategist, designer, or account executive, Advertising Club offers the tools and network to help you thrive. Interested in joining? Follow us on social media for more info! @csufadclub', 'adclub', 'Active', '{"Special Interest","Career Planning","College of Communications","Social"}', '{"career","social"}'),
  ('331141', 'Afghan Student Association', 'The purpose of this organization is to create an engaging place for Afghan/Non-Afghan students to connect, network, and celebrate Afghan culture.', 'The Afghan Student Association at California State University, Fullerton is a student run organization with intentions to celebrate and promote Afghan culture. Specifically, this club is aimed at creating a safe space in which Afghan/non-Afghan students can come together to unify, have fun, and connect with Afghan culture. The unification of students will be accomplished through social events and cultural outings.', 'csuf_asa', 'Active', '{"Cultural","Social"}', '{"cultural","social"}'),
  ('132777', 'Afro-ethnic Student Association', 'The Afro-ethnic Student Association at CSUF is devoted to highlighting the Black experience, cultivating leadership, and advancing social justice.', 'The Afro-ethnic Student Association at CSUF is devoted to highlighting the Black experience, cultivating leadership, and advancing social justice. We have multiple events throughout the year, with a special event named fusion that offers a unique experience to share talents and skill with fellow peers. We also host discussion based seminars where we can be both vulnerable and productive while handing out and having fun.', 'aesa', 'Active', '{"Umbrella (Council)","Political/Social Action","Service","Special Interest","Health & Wellness","Social"}', '{"cultural","health-wellness","leadership","political-social-action","service","social"}'),
  ('432799', 'Ahlul-Bayt Student Association', 'ABSA aims to create a welcoming space for students to learn about and connect with the teachings and values of the Ahlul Beyt.', 'The Ahlul Beyt Student Association aims to create a welcoming space for students to learn about and connect with the teachings and values of the Ahlul Beyt. We strive to support spiritual growth, build a strong sense of community, and promote understanding and respect among students of all backgrounds. Through educational events, discussions, and service, we encourage members to grow in faith, character, and leadership while making a positive impact on campus.', 'absa', 'Active', '{"Faith"}', '{"faith"}'),
  ('136109', 'Alpha Chi Omega', 'Alpha Chi Omega is a national women''s organization that enriches the lives of our members through lifetime opportunities of friendship, leadership, learning, and service within our community and nationally.', 'Alpha Chi Omega (AXO) – Epsilon Kappa chapter Nationally Founded: October 15, 1885 Symbol: Golden Lyre Colors: Scarlet Red and Olive Green National Flower: The Red Carnation Philanthropy: AXO supports Domestic Violence Awareness, Mothers Against Drunk Driving (MADD), CSUF’s Women Center, and The Alpha Chi Omega Foundation Motto: “Together let us seek the heights.” Mission: Alpha Chi Omega is dedicated to enriching members'' lives through friendship, leadership, learning, and service. Values: Comprising unique and genuine women, Alpha Chi Omega seeks to redefine sorority life with a focus on real conversations and living as Real, Strong Women . We foster a supportive community with leadership, scholastic goals, and empowerment for women''s issues. The chapter, proud of over 50 years at CSUF, encourages academic success, campus involvement, and social excellence. Follow @axocsuf on Instagram for updates!', 'axocsuf', 'Active', '{"Fraternity & Sorority","Service"}', '{"greek-life","leadership","service","social"}'),
  ('135390', 'Alpha Delta Pi', 'Alpha Delta Pi is committed to sisterhood, values and ethics, high academic standards and social responsibility.', 'About Us Alpha Delta Pi was the first secret society for women and forged the way for the creation of sororities. Our founding took place on May 15, 1851 at Wesleyan Female College in Macon, Georgia—the first college in the world chartered to grant degrees to women. We were founded at CSUF on February 28, 1970 and continue to live out our values. Our international philanthropy, The Ronald McDonald House Charities, holds a special place in our hearts. We are gracious to be able to prepare meals for and socialize with the families living in the house throughout the year. With the support of our community, we are able to fundraise thousands of dollars each year to give back to the RMHC. Our color, azure blue, represents the friendships we hold with one another. Our unbreakable sisterhood extends through all aspects of life. No matter what we have going on in our lives, we are always there to lift each other up as strong and empowered women. We not only live for each other, but we strive every day to continue breaking stereotypes. We are more than just pictures and hashtags, we wear our letters proudly as brave, bold, and inspiring leaders. For more information follow us on Instagram @adpicsuf! Alpha Delta Pi Sisters: Initiated Members: 260,000+ Active Collegiate Chapters: 161 Awards 2026 FSL Honors Academic Achievement 2026 FSL Honors Harm Reduction and Risk Management 2025 Greek Week Champions (Sorority Participation) 2025 FSL Honors Panhellenic Chapter President of the Year 2025 FSL Honors Panhellenic Excellence in Academic Achievement 2025 FSL Honors Panhellenic Individual Member Involvement 2024 Greek Week Champions (Sorority Fundraising and Overall Winner) 2023 Greek Week Champions (Sorority Fundraising, Competition, Overall, and Overall Fundraising, Championship) 2023 FSL Honors Panhellenic Chapter President of the Year 2023 FSL Honors Panhellenic Member of the Year 2023 FSL Honors Panhellenic Emerging Leader 2022 Greek Week Champions (Overall, Fundraising, Competition) 2021 Pursuit of Excellence, Most Improved Chapter 2021 Pursuit of Excellence, Philanthropy Award 2020 Greek Week Champions (Overall, Fundraising) 2019 Pursuit of Excellence, Leadership Award 2019 Pursuit of Excellence, Most Unique Program ( Behind Happy Faces -a program designed to give members the tools they need to address mental health proactively.) 2019 Greek Week Champions (Overall, Fundraising, Lip Sync Competition) 2019 Top Fundraisers in the Panhellenic Donation Drive for CSUF''s Tuffy''s Basic Needs 2018 Pursuit of Excellence, Panhellenic Sisterhood Event 2018 Pursuit of Excellence, Panhellenic Scholarship Award 2018 Greek Week Champions (Lip Sync) How to Get Involved: Message or fill out our Interest Survey on Instagram @adpicsuf!', 'adpicsuf', 'Active', '{"Fraternity & Sorority","Service"}', '{"greek-life","service","social"}'),
  ('138285', 'Alpha Kappa Alpha Sorority Incorporated', 'Alpha Kappa Alpha Sorority, Incorporated, founded in 1908 at Howard University, is a pioneering sisterhood committed to "Service to All Mankind". With over 300,000 members globally, AKA is the first African American Greek-letter sorority.', 'Alpha Kappa Alpha Sorority Inc.'' mission is to cultivate and encourage high scholastic and ethical standards, to promote unity and friendship among college women, to study and help alleviate problems concerning girls and women in order to improve their social stature, to maintain a progressive interest in college life, and to be of “Service to All Mankind". The sorority is renowned for its dedication to community service and philanthropy. AKA''s mission is encapsulated in its motto, "Service to All Mankind," which reflects a deep commitment to uplifting communities through various initiatives. The organization has been a trailblazer in addressing social issues, advocating for civil rights, and promoting education. AKA is distinguished by its iconic colors, salmon pink and apple green, as well as its symbolic ivy leaf. The sorority''s legacy includes notable members who have made significant contributions to various fields, including arts, politics, and science. The sorority''s impact extends beyond college campuses, reaching into diverse communities through programs that focus on education, health, economic empowerment, and social justice. AKA also places a strong emphasis on supporting and mentoring young women, nurturing leaders who will contribute positively to society.', 'akasigmarho', 'Active', '{"Fraternity & Sorority"}', '{"greek-life","service","social"}'),
  ('181469', 'Alpha Kappa Psi', 'Alpha Kappa Psi is a professional co-ed business fraternity with the purpose of developing its members into principled business leaders. As one of the greatest co-ed business fraternities, we are truly preparing our brothers for a life of success.', 'Founded in 1904 by 4 men at New York University, the professional organization now has over 240,000 initiated members at 265 universities in 3 countries. Alpha Kappa Psi is open to all majors and has grown to be the oldest and largest co-ed business fraternity in the world! With an extensive network of alumni, members are able to land opportunities at some of the most profitable companies in the world.', 'akpsi', 'Active', '{"Fraternity & Sorority","College of Business and Economics"}', '{"business","greek-life","leadership"}'),
  ('134231', 'Alpha Omega', 'We welcome you to our campus ministry where you can connect with others and seek out a deeper relationship with God. “I am the Alpha and the Omega, the First and the Last, the Beginning and the End.” Revelation 22:13', 'Welcome to Alpha Omega Christian Movement! We are a group of college students who are devoted to loving God and loving his people. We strive to live in obedience to the Bible and teach others about Jesus and his word. We are here to provide spiritual and relational support for any and all students as they navigate college. We have a number of fun events, Bible studies, and Bible Discussions on and off campus all around Orange County. You can get a glimpse of us on our Instagram @alphaomegaoc, or reach out to us to find out more information! Click on the world link to check out our events for the year!', 'alphaomega', 'Active', '{"Faith","Service","Social"}', '{"faith","service","social"}'),
  ('137483', 'Alpha Phi Sigma', 'Alpha Phi Sigma offers opportunities to network with criminal justice and related majors/minors, faculty, and professionals in the field of criminal justice. We are guided by our pillars: Academic Excellence, Leadership, Service, and Unity.', 'Alpha Phi Sigma recognizes the academic excellence of undergraduate and graduate criminal justice students and juris doctorate candidates. The goals of Alpha Phi Sigma are to honor and promote academic excellence, leadership, service, and unity. Alpha Phi Sigma is the only Criminal Justice Honor Society that is a certified member of the Association of College Honor Societies and affiliated with the Academy of Criminal Justice Sciences. Students become involved through leadership development opportunities and experiences, local community service work, fundraising/crowdfunding, and building relationships with peers, faculty, and professionals in the criminal justice field. It provides an atmosphere that encourages members to engage in healthy and productive social interactions through social events on and off campus, guest speakers, facility and program tours, and more. We are the Alpha Phi Sigma, Gamma Rho chapter. You can learn more about our chapter by', 'alphaphisigma', 'Active', '{"Honor Society","Service","Special Interest","College of Humanities & Social Sciences"}', '{"career","leadership","service"}'),
  ('132788', 'Alpha Sigma Lambda', 'Alpha Sigma Lambda''s aim is to recognize the special achievements of adults who accomplish academic excellence while facing competing interests of home and work. Our motto is "First in Scholarship and Leadership".', 'At Cal State Fullerton, the Nu Pi chapter of Alpha Sigma Lambda Honor Society aims to recognize and celebrate the exemplary achievements of adult learners who accomplish academic excellence while facing competing interests of home and work. Our members are non-traditional undergraduate students age 25+ who have completed 24 units at CSUF while maintaining a 3.2 GPA. All Majors Welcome! For more information: ASLHS LinkTree ASLHS on Instagram', 'alphasigmalambda', 'Active', '{"Honor Society"}', '{"career","leadership"}'),
  ('431134', 'Alzheimer''s Awareness Club', 'The AAC is dedicated to supporting adults living with Alzheimer’s disease through efforts to understand, support, and provide care for those affected. Student involvement includes fundraising, volunteering, and encouraging positive aging habits.', 'Welcome to the Alzheimer''s Awareness Club (AAC)! We are a student organization at CSUF dedicated to supporting individuals living with Alzheimer''s disease through education, advocacy, and direct community engagement. Our goal is to foster a campus community built on an understanding of Alzheimer''s disease and related dementias and to raise awareness of how students can directly help. The AAC welcomes students of all majors, interests, and experience levels who are passionate about supporting individuals and families affected by dementia and want to give back to their community. Through volunteer efforts, fundraising, and education, we can help raise awareness, build community connections, and make a positive impact on the lives of those affected by Alzheimer''s disease and related dementias.', 'alz_awareness', 'Active', '{"Service","Health & Wellness","Social"}', '{"health-wellness","service","social"}'),
  ('135974', 'American Choral Directors Association', 'American Choral Directors Association prides itself on the advancement of choral music education in young people and teachers around the world. Our student chapter fosters the growth of aspiring music teachers in a supportive learn-by-doing atmosphere.', 'American Choral Directors Association (ACDA) is a non-profit, national organization that promotes the advancement of choral music education through a passion to incorporate music in schools, to teach and learn effectively, and to develop professional and organizational skills. Part of the organization’s purpose is to foster and promote artistic, cultural, and spiritual experiences, and to encourage excellent musicianship, musical composition, rehearsal technique, and the overall development of musical culture in America. As a student chapter affiliated with our larger national chapter, we assume responsibility as growing musicians and future educators to learn ahead of the curve with hands-on activities and masterclasses. We aim to provide valuable learning experiences and teaching opportunities for members of our chapter as they prepare to enter the dynamic field of education. Above all, we work to create a safe environment for friendly and passionate musicians to rely on for community and growth.', 'acda', 'Active', '{"Service","Special Interest","Career Planning","College of Education","College of the Arts","Music"}', '{"career","music","service"}'),
  ('158440', 'American Institute for Aeronautics and Astronautics', 'The American Institute for Aeronautics and Astronautics (AIAA) aims to inspire the passion for aerospace ingenuity through collaborative effort.', 'Established in 1963, The American Institute for Aeronautics and Astronautics (AIAA) aims to inspire the passion for aerospace ingenuity through collaborative effort. Our plan is to move forward with the aerospace industry and connect the members with the aerospace community inside and outside of campus. Students will be given the opportunity to cultivate relationships with key individuals in the industry, advance industry standards, and lead the momentum of aerospace innovation. Furthermore, this organization aims to provide students with exposure to aerospace related collegiate competitions, research, and professional development. Current Projects: SAE AERO WEST COMPETITION 2020 A worldwide organization with recognition in 85 countries, the AIAA plans to launch the love for aerospace to new, unexplored heights.', 'aiaacsuf', 'Active', '{"Special Interest","College of Engineering and Computer Science"}', '{"social"}'),
  ('404029', 'American Lung Cancer Screening Initiative', 'The American Lung Cancer Screening Initiative (ALCSI) is dedicated to promoting lung cancer screening for individuals at high risk of developing the disease.', 'The American Lung Cancer Screening Initiative (ALCSI) is a 501(c)(3) nonprofit organization focused on raising awareness about lung cancer and advocating for early detection through comprehensive screening efforts. ALCSI collaborates closely with healthcare providers, policymakers, and community members to increase access to lung cancer screening services, aiming to save lives through early diagnosis. The organization supports and conducts impactful research, such as the INSPIRE Lung Cancer Screening Study, which addresses screening equity among high-risk groups. ALCSI also fosters educational outreach by establishing university chapters across the U.S., encouraging students to engage in lung cancer advocacy and awareness activities.', 'alcsi', 'Active', '{"College of Health and Human Development","College of Natural Science and Mathematics"}', '{"political-social-action"}'),
  ('132818', 'American Marketing Association', 'AMA at CSUF is a community of like-minded individuals who plan to develop their personal skills, as well as network with professionals. We strive to develop the marketing leaders of tomorrow by creating a valuable experience for our members.', 'We have meetings every other Wednesday at 6:00 pm. (please look at our Google Calendar and Instagram for accurate meeting dates) Purchase a Membership on AMA.org Our Mission: Develop marketing leaders by creating opportunities for students to immerse themselves with the knowledge, skills, and tools before and after graduation. In AMA, we are a community of like-minded individuals trying to advance our own personal skills, as well as network with professionals to gain valuable insights. General meetings consist of professional guest speakers who present and share advice that has helped them progress into their careers, workshops, socials, and more! Guest speakers may have internship opportunities to offer AMA members. We also have group activities, Q&A''s with the speaker, prizes, and lots of fun during our meetings! We do our best to make AMA feel as beneficial as possible for our members. During the semester, we also have other things going on for our members to network and be as involved as possible. Committees & Assistants: Our VPs will have committees or assistants that help contribute value to AMA. Members who join will be able to learn about the VP''s position and what they do for AMA (such as Social Media, Communications, Sponsorship, etc.) and even partake in projects that members can add to their portfolios. Socials: Throughout the semester, we have socials planned so that AMA executive board and general members can get to know each other better and network. Development Events: We normally have around 3 significant events for our members to attend. These events are made to further develop our members'' skills through workshops, marketing competitions, and more professional guest speakers. Discord: We have implemented an AMA discord as an important form of contact for our members. Community Service: We believe that helping out in the community is important so we''ve implemented community service events throughout the year! Our first Social Meeting and Kick-Off Meeting of every semester is FREE ! Be sure to come out and see if AMA is a good fit for you and your professional career goals.', 'csufama', 'Active', '{"Umbrella (Council)","Service","Special Interest","Recreation","College of Business and Economics"}', '{"business","leadership","recreation","service"}'),
  ('132977', 'American Medical Student Association', 'The American Medical Student Association (AMSA) at CSUF is a community for pre-med students. By offering guest speakers, service opportunities, conferences, and mentorship, AMSA helps you become a strong medical school applicant.', 'Welcome to AMSA! The American Medical Student Association (AMSA) is a student-governed, national organization committed to representing the concerns of physicians-in-training. AMSA members are medical students, premedical students, interns, residents and practicing physicians. Founded in 1950, AMSA continues its commitment to improving medical training and the nation’s health. We are here to provide support to fellow pre-med students with guest speakers, service opportunities, conferences, and mentorship to build a strong community on campus. For Fall 2024, our values are: Teamwork Dedication Support Advocacy Everyone is welcome to our in person meetings will be TBD location is TBA . More information will be added on the location of our first meeting. Our first general meeting will be soon! We look forward to meeting you all! Stay up to date with our Instagram (@csufamsa)! Information about how to become a member will be given at our meetings! We are here for you! Contact us: Email: amsacsuf@gmail.com Instagram:@csufamsa', 'csufamsa', 'Active', '{"Service","College of Natural Science and Mathematics"}', '{"health-wellness","mentorship","service"}'),
  ('134228', 'American Society of Civil Engineers', 'ASCE is the nation''s oldest engineering society, and promotes success within the civil engineering field. Networking, educational tours, internships and social events are just a few things ASCE has to offer civil engineering students at CSUF.', 'ASCE is the nation''s oldest engineering society, and promotes success within the civil engineering field. CSUF ASCE has about 180 members and is a great opportunity not only to meet other students in your major but also to network with professionals within the field and advance your career. ASCE provides members with internship and job opportunites, networking events, educational seminars and tours, social events, and we work on a variety of projects. Our club is well known for our concrete canoe and steel bridge, which compete along with many other projects in our yearly conference called the Pacific Southwest Conference. Joining ASCE is not only a lot of fun, but a great career move!', 'asce', 'Active', '{"Honor Society","Service","Special Interest","College of Engineering and Computer Science"}', '{"career","engineering","service"}'),
  ('136381', 'American Society of Mechanical Engineers', 'ASME is an organization that enables collaboration, knowledge sharing, career enrichment, and skills development across all engineering disciplines. This organization is represented explicitly by California State University Fullerton students.', 'The purpose of this organization is to provide its members opportunities to gain broader insight into the mechanical engineering profession by sponsoring meetings which will bring practicing engineers to the campus, arranging field trips to research and engineering establishments, sponsoring student projects of engineering interest, and participating in local ASME Section activities. It shall also be the purpose of this organization to encourage good fellowship among engineering students and their professors.', 'asme', 'Active', '{"Special Interest","College of Engineering and Computer Science","Social","Technology"}', '{"career","engineering","social","technology"}'),
  ('137433', 'American Society of Safety Professionals', 'Our mission is to promote professional development of members and students through advanced education, training, social service and networking events with professionals of Environmental Health and Occupational Safety related fields.', 'As members of the California State University, Fullerton Student Section of the Orange County ASSP, our mission is to promote professional development of members and students through advanced education, training, social service and networking events with professionals of Environmental Health and Safety related fields.', 'csufasse', 'Active', '{"Service","Special Interest","College of Health and Human Development"}', '{"career","health-wellness","service","sustainability"}'),
  ('429252', 'Appellate Law Student Association', 'The Appellate Law Student Association (ALSA) aims to promote legal-issue discussions, encourage development of legal reading and writing skills, and support those interested in legal issues or future legal education.', 'Appellate Law Appellate law refers to the legal practice of asking higher courts to review and reverse decisions made by lower courts due to legal, procedural, or factual errors. It mainly focuses on written briefs and oral arguments regarding legal interpretation, rather than by retrying laws, presenting new evidence, or questioning witnesses. Key fields include civil and criminal appeals, administrative law, administrative law, family law, and constitutional law. Appellate Law Student Association The Appellate Law Student Association (ALSA) aims to promote discussions regarding contemporary legal issues, encourage development of legal reading and writing skills, and engage in other activities that further such purposes for those interested in legal issues or future legal education. Connect with us on Instagram or reach out to us via email for more information on how to be a member and our upcoming schedule of events!', 'appellatelawstudentassociation', 'Active', '{"Political/Social Action","Special Interest","College of Humanities & Social Sciences"}', '{"political-social-action"}'),
  ('429529', 'Applied Researchers of Biology', 'The purpose of this organization is a student-led community for anyone curious about how biology can be turned into real-world discovery. Whether you’re pursuing research as a career or exploring it as a special interest.', 'The purpose of this organization is a student-led community for anyone curious about how biology can be turned into real-world discovery. Whether you’re pursuing research as a career or exploring it as a special interest, ARB offers a welcoming space to learn, connect, and build skills. From workshopping posters and practicing presentations to bringing professors to speak about research lab opportunities. We aim to make research approachable by helping students gain confidence, ask questions, and understand the impacts of research in medicine, public health, and the environment.', 'appliedresearchersofbiology', 'Active', '{"Special Interest","College of Natural Science and Mathematics"}', '{"career"}'),
  ('136212', 'Archers of CSUF', 'The purpose of the Archers of Cal State Fullerton is to further expand of the sport of Archery and form a team to represent California State University, Fullerton in Collegiate and Olympic level competition, as well as for recreation.', 'We are a club sports team at CSUF that provides the opportunity to learn Archery. We provide training, equipment for you to use, and a friendly space to practice. There are even opportunities to compete with other collegiate teams! Most importantly, we are a student-run group, with opportunities to become involved "behind the scenes" to build skills in leadership and academic development. Meeting times For Spring 2026 are Monday, Wednesday 6pm-9pm @ East Intramural Fields. See you there!', 'archery', 'Active', '{"Sport","Outdoors"}', '{"outdoors","recreation","sport"}'),
  ('332584', 'Armenian Student Association', 'Our goal is to connect the Armenians at California State University, Fullerton. As well as to connect Armenians from other universities and promote their culture. A lot of fun activities and events are yet to come.', '', 'armenianstudentassociation', 'Active', '{"Cultural"}', '{"cultural"}'),
  ('135445', 'Army ROTC at CSUF', 'Army ROTC Alpha Lambda (Titan Battalion) serves northern Orange County in order to train students to become future officers in our armed forces as well as leaders in the professional business world.', 'Army ROTC is one of the most demanding and successful leadership programs in the country. The training a student receives in Army ROTC provides leadership development, military skills and career training. Courses take place both in the classroom and in the field, and are mixed with normal academic studies. Additional summer programs, such as Air Assault School, may also be attended. Upon completion, an Army ROTC graduate is commissioned as an officer in the Army.', 'csufarmyrotc', 'Active', '{"Service","Special Interest"}', '{"business","leadership","service"}'),
  ('132789', 'Arts Inter-Club Council', 'The AICC is a liaison for all arts organizations designed to increase communication within the College of the Arts and promote the growth of a unique artistic community by providing funding for events, as well as for students traveling to conferences.', 'The AICC is a liaison for all arts organizations designed to increase communication within the College of the Arts and promote growth of a unique artistic community by providing funding for events, as well as for students traveling to conferences. General Council Meetings Weekly meetings will be held in the TSU on Mondays from 12:00 - 12:50 pm. To register into the AICC as an organization, please fill out the registration form provided in this link: AICC New Club Registration Form To re-register into the AICC as an organization, please fill out this registration form provided in this link: AICC Re-Registration Form Current AICC Student Organizations: - American Choral Directors Association - ACM Siggraph - Cello Council - Fullertones Acapella - Fullerton Fashion Association - Graphic Design Club - Mariachi Titans - Mu Phi Epsilon - Pencil Mileage Club - Phi Mu Alpha Sinfonia - SAI - Student Productions Organized by Titans - Subculture Music Club - Women in Animation', 'aicc', 'Active', '{"Umbrella (Council)","College of the Arts"}', '{"arts","leadership"}'),
  ('295451', 'Ascend Leadership at CSUF', 'Empowering the Next Generation of AAPI Business Leaders at CSUF', 'Since 2025, Ascend CSUF has helped students turn ambition into opportunity. As the Cal State Fullerton chapter of Ascend, the largest nonprofit organization for Pan-Asian business professionals and students in North America, the club connects members to a network of more than 100,000 individuals across 65 chapters. Through its partnership with Ascend OC, students gain direct access to professionals and executives from leading firms across a wide range of industries. Members develop the confidence and skills needed to succeed beyond the classroom through mentorship programs such as career workshops, networking events, scholarship opportunities, and meaningful leadership experiences. Supported by a national foundation that has awarded more than $1 million to students, Ascend CSUF offers more than professional development. It provides a community where students build lasting relationships, strengthen their voice, and prepare to become the next generation of business leaders. Rooted in the advancement of Pan-Asian professionals, Ascend CSUF welcomes students of every background.', 'ascendcsuf', 'Active', '{"Cultural","Career Planning","College of Business and Economics"}', '{"business","career","cultural","leadership"}'),
  ('429553', 'Asian Pacific Islander Business Association', 'APIBA aims to aid AAPI students in their professional development by providing career-related support, community, and professional connections.', 'APIBA supports Asian American and Pacific Islander students and others interested in professional development opportunities. To achieve our goal, APIBA will provide career-related support, community-building activities, and opportunities to hear from AAPI professionals from different backgrounds and industries to better represent our student population.', 'apiba', 'Active', '{"Cultural","Career Planning","College of Business and Economics","Social"}', '{"business","career","cultural","social"}'),
  ('135861', 'Asociación de Alumnos y Ex-Alumnos de Español', 'The Asociación de Alumnos y Ex-Alumnos de Español (Spanish Major Students/Alumni Association) was founded on April 29, 2000. Students interested and majoring in Modern Language Spanish will benefit from the enriching academic and cultural activities.', 'The Asociación de Alumnos y Ex- Alumnos de Español (Spanish Major Students/ Alumni Association) was founded on April 29, 2000. Students majoring in Modern Languages (mainly Spanish), and students from all majors as well will benefit from the enriching academic support and cultural activities AAEE hosts each semester. The purpose of this association is to create an entity at CSUF for all students with an interest in Spanish. AAEE provides leadership skills by being part of the club committee as well as representing the club in sub-committees and board meetings. Studying is not everything, we also have to dedicate time to socialize with our peers and learn from one another. Organizations like AAEE give you the opportunity to socialize in a fun and educational way.', 'associacionalumnosexalumnosespanol', 'Active', '{"Cultural","Special Interest","Recreation"}', '{"cultural","recreation"}'),
  ('137313', 'Association for Computing Machinery', 'We are the largest Computer Science community at CSUF. Our chapter provides workshops, career resources, and a social community that''s open to all majors. Join us on Discord at acmcsuf.com/discord', 'General ACM events are every Thursday at 5:30pm! acmCSUF is a student chapter of the Association for Computing Machinery, an international organization dedicated to advancing computing as a science and profession. Our chapter brings together students at California State University, Fullerton who are passionate about tech through hands-on workshops, industry info sessions, socials, and more. Our chapter is open to anyone interested, regardless of major or background experience. Join our community on Discord: !', 'acm', 'Active', '{"Career Planning","College of Engineering and Computer Science","Social","Technology"}', '{"career","social","software-engineering","technology"}'),
  ('137065', 'Association for Computing Machinery - Women', 'ACM-W celebrates & advocates for the full engagement, education, & opportunities of women in all aspects of the computing field. We endeavor to provide a wide range of programs/services to students & advance the contributions of technical women students.', 'Association for Computing Machinery - Women supports, celebrates, and advocates for the full engagement, education, and opportunities of women in all aspects of the computing field. We endeavor to provide a wide range of programs and services to students and advance, in the larger community, the contributions of technical women students. Join our Discord server to check out when our next event is! Join our Discord here! Check us out on Instagram Here! Visit Our Website! Here!', 'acmw', 'Active', '{"College of Engineering and Computer Science","College of Natural Science and Mathematics"}', '{"political-social-action","software-engineering","technology"}'),
  ('430882', 'Association for Inter Cultural Awareness', 'AICA shall serve as the ASI''s multicultural programming board. AICA encourages and supports the multicultural programming of Council Members by controlling the channeling of ASI funds. AICA serves as an instrument of student opinion and advocacy.', '', 'asi-fullerton', 'Active', '{"Umbrella (Council)","Cultural"}', '{"cultural","leadership","political-social-action"}'),
  ('132397', 'Association for Operations & Supply Chain Management', 'We create an environment for professional development, networking, and exploring career opportunities. We bridge the gap between the classroom and the working world through student-industry connections.', 'Our Mission Building the bridge to a successful career in supply chain management through student-industry connections. The Association for Operations & Supply Chain Management ( AOSCM ) is a student-led organization at College of Business and Economics of CSUF where we work to create future business leaders, through professional and social networking. Our events consist of: - Internship Opportunities - Company Visits and Facility Tours - Networking Events - Career Workshops - Guest Speaker Presentations - Career Fair VISIT OUR WEBSITE: For more information do not hesitate to reach out to us through email or social media! Haven''t paid your membership fee? Contact our Treasurer: aoscm.treasurer@gmail.com', 'aoscm', 'Active', '{"College of Engineering and Computer Science","College of Business and Economics"}', '{"business","career"}'),
  ('135662', 'Association of Chinese Students', 'ACS (est. 2008) is a social and cultural organization that strives to provide a community for Chinese students and others interested in Chinese culture. We aim to increase cultural awareness, as well as foster inclusivity and belonging among our members.', 'The Association of Chinese Students (ACS) is a social-cultural organization for students interested in Chinese culture. Members of ACS are given opportunities to learn about and be immersed in Chinese culture, history, and values. ACS hosts various events, meetings, and activities where members can gather and bond through their interest in Chinese culture. All CSUF students are welcome to join! For more information, follow and contact us on Instagram (@csufacs)', 'acs', 'Active', '{"Cultural","Social"}', '{"cultural","social"}'),
  ('132503', 'Association of Latino Professionals For America at California State University, Fullerton', 'ALPFA CSUF aims to empower and develop leaders in every sector of the global economy. ALPFA provides networking and professional development opportunities for our members.', 'ALPFA (Association of Latino Professionals For America) was the first national Latino professional association in the United States, established in Los Angeles in 1972. ALFPA CSUF chapter is dedicated to create opportunities, add value, and build relationships for its members, the community, and its business partners. We value leadership through diversity in the global workforce and academia. We strive for our members to achieve professional growth, relationship building, service to the community, integrity, inclusiveness, and culture. Become Part of the ALPFAmilia Join ALPFA and invest in educational and career readiness tools, scholarships, and job opportunities. Become an ALPFA member today and take advantage of some of the benefits of our network: Networking Events Internship Opportunities Scholarship and Fellowship Opportunities Skill-Building Workshops Insights in Various Fields (e.g. Accounting, Finance, Business, Healthcare, Technology, and more) Whether you are a rising freshman or college senior, ALPFA CSUF offers a supportive community dedicated to your growth and success. Join us and discover how you can contribute to and benefit from our dynamic network of leaders. Embrace leadership, diversity, and excellence with ALPFA CSUF today.', 'alpfa', 'Active', '{"Career Planning","College of Education","College of Engineering and Computer Science","College of Health and Human Development","College of Business and Economics"}', '{"career","leadership"}'),
  ('332118', 'Augmentative & Alternative Communication Club', 'Not everyone can communicate through speech. Our mission is to educate others on augmentative and alternative communication (AAC), the form of communication used by those who cannot solely rely on speech for effective communication.', 'Our Mission: To serve as an avenue for students to learn about aided augmentative and alternative communication (AAC) and to serve as a general information resource on AAC for the university and the local community. As the AAC Club, our goal is to educate future professionals and the community about augmentative and alternative communication (AAC). Complex communicators, those who cannot rely solely on speech for effective communication, use AAC to communicate effectively. If you are interested in serving individuals with severe and/or multiple disabilities, are pursuing a career in speech-language pathology, special education, audiology, or related fields, this club is for you!', 'aac', 'Active', '{"College of Communications","College of Education","College of Health and Human Development","Health & Wellness","Technology"}', '{"health-wellness","technology"}'),
  ('365843', 'Backcountry Hunters and Anglers Chapter at Cal State University, Fullerton', 'BHA is an organization of sportsmen and women dedicated to work on behalf of public lands and waters. They achieve this through their focus on three areas: access & opportunity, public lands and waters, and fair chase.', 'BHA''s Collegiate Program is built upon 5 pillars: Community: Our public lands and waters are best shared with friends We are committed to building a community of conservation minded young adults who value our public lands, waters, wildlife, and hunting and angling heritage. Within each university, our clubs strive to create a group of friends and acquaintances who share their passions for the outdoors through hunting, angling, or any other activity enjoyed on our public lands and waters. People are more likely to spend time outdoors and give back through conservation when they have a community to share it with. Stewardship: Protecting public lands for future generations We are all collective owners of millions of acres of public land throughout North America that were set aside as a part of the public trust. As public land owners, it is our duty to protect and manage these lands in a sustainable way and to advocate for their continued existence for future generations to enjoy. Our clubs are dedicated to giving back to their public lands and waters through local stewardship projects that benefit our wild places. Education and Advocacy: Empowering tomorrows conservation leaders We strive to cultivate future leaders in conservation by providing strong foundational education in hunting, angling, and the North American Model of Wildlife Conservation through workshops and mentorship opportunities. In addition, we provide opportunities for college leaders to engage in administrative and legislative public lands advocacy efforts at a local, state/provincial, and federal level. To motivate students to continue their work on behalf of wild places, we are dedicated to providing educational, professional development, and networking opportunities. Inclusivity: Public lands and waters are for everyone Public lands were set aside for the enjoyment of all regardless of ethnicity, religion, socioeconomic status, age, etc. In our collegiate clubs, everyone is welcome. Adventure: Find your backcountry Backcountry means different things to different people. At BHA we think of it more as a mindset rather than a place. It’s the places we retreat to, to find a connection with nature, challenge the body, clear the mind, and reset the soul. We are dedicated to helping our student members find the adventure, challenge, and solace they seek. If you''re interested, complete the free BHA application form found below, and join us on discord; BHA-CSUF Discord', 'backcountry-hunters-anglers-csuf', 'Active', '{"Political/Social Action","Service","Special Interest","Sport","Recreation","Health & Wellness","Outdoors","Social","Sustainability"}', '{"outdoors","recreation"}'),
  ('132721', 'Ballet Folklorico de Cal State Fullerton', 'We, Ballet Folklorico de CSUF, exist to educate, preserve and promote cultural awareness of the Mexican Heritage by celebrating the diversity and beauty of Mexico''s folk dance. BF de CSUF is all about Cultura, Sabor, Unidad, y Fuerza!', 'Ballet Folklorico de Cal State University Fullerton was founded in Spring of 2007. Found under the driven passion of two CSUF students: Christopher Sandoval and Michaela Kimball, the vision was to form an organization of CSUF students willing to learn and share their knowledge of Ballet Folklorico in a campus setting. Since 2007, the group has been home to hundreds of dancers! Every member comes with a different level of experience and background, which is why we are open to all. Don''t be afraid to join and dance your heart with your BF de CSUF familia.', 'bfdecsuf', 'Active', '{"Cultural","Special Interest","Recreation","Dance","Social"}', '{"cultural","dance","recreation","social"}'),
  ('426275', 'Beauty & Lifestyle Marketing Society', 'A club focused on exploring career paths within the beauty and lifestyle industry. We discuss roles like brand marketing, PR, influencer marketing, social media, and product development through conversations, workshops, and guest insights.', 'This organization is focused on helping students explore and prepare for careers within the beauty and lifestyle industries from a marketing and business perspective. We plan to highlight different roles within the industry such as brand marketing, public relations, influencer marketing, social media management, product marketing, creative direction, and content strategy. The goal is to connect students with industry insights, networking opportunities, and career resources related to beauty fashion and lifestyle brands. To fill out our interest form: [Click Here] Follow us on Instagram at @beautymarketingcsuf', 'beautymarketing', 'Active', '{"Special Interest","Career Planning","College of Communications","College of Education","College of Business and Economics","Social"}', '{"business","career","social"}'),
  ('132719', 'Behind The Scenes', 'BTS provides students in the Entertainment & Hospitality Management program with opportunities to interact with fellow students, professors, as well as with members of the Entertainment and Hospitality industries through VIP tours, panels, workshops.', 'This student-led organization provides students in the Entertainment & Hospitality Management concentration with opportunities for association and interaction with fellow peers, professors, as well as with members of the Entertainment and Hospitality Industries. Furthermore, the purpose of the club is to foster leadership and create a competitive advantage for members. Interests include music, film, TV, video games, live events, hospitality, casinos, etc.', 'behindthescenes', 'Active', '{"Service","Special Interest","Sport","College of Business and Economics","Music","Social"}', '{"music","service","social","sport"}'),
  ('135279', 'Beta Alpha Psi', 'The Beta Alpha Psi Chapter Delta Beta at Cal State Fullerton is a student-run organization that caters to Accounting, ISDS, and Finance majors.', 'Beta Alpha Psi is a nonprofit international honor and service organization for accounting, finance, and information systems students at AACSB or EFMD/EQUIS-accredited universities. Beta Alpha Psi provides opportunities for the development of technical and professional skills to complement university education, participation in community service, and interaction among students, faculty, and professionals. The Delta-Beta Chapter of BAP at Cal State Fullerton was established in 1969. By partnering with the CSUF Accounting Department, we have successfully expanded our network and provided our members with more exposure to different local, regional, national, and international companies and firms. For the most updated information, please visit our website , follow us on Instagram , or contact us at president@csufbap.org.', 'csufbap', 'Active', '{"Honor Society","College of Business and Economics"}', '{"business","career","leadership"}'),
  ('135174', 'Beta Psi Omega', 'We are a co-ed fraternity with the focus of helping students in their academic as well as professional lives. Following the five pillars of excellence, we build on connections and collaborations with both students and the community.', 'The primary purpose of this organization is to provide a supportive, diverse community for students pursuing careers in the biological sciences and to further the advancement of biology as a science and as a profession. The fraternity is committed to serving the needs of the students and, thereby the community. Beta Psi Omega aims to provide passionate students with opportunities, insights, and guidance for their ambitions. Our Philanthropy: CSUF Cardz For Kidz Cardz For Kidz at California State University Fullerton is the first student-led college chapter branched from the original CardzforKidz non-profit organization based in Chicago. Cardz For Kidz is dedicated towards bringing students together in order to create handmade, motivating, and uplifting affirmation cards. Students will be able to attend and collaborate with other CSUF organizations for card-making events where students are able to volunteer their time to create personalized cards. These cards provide support, smiles, and encouragement to children, families, seniors, and veterans in hospitals, schools, senior living, and rehabilitation centers, as they are donated to the official CardzforKidz organization that hand delivers every card, room by room.', 'betapsiomega', 'Active', '{"Fraternity & Sorority","Service","Career Planning","College of Natural Science and Mathematics","Social"}', '{"career","greek-life","service","social"}'),
  ('365834', 'Bhangra @ CSUF', 'Bhangra at CSUF is an organization that will be a dance organization. Bhangra is known to be a cultural and traditional dance for people from India. It is a high-energy dance and many people enjoy it.', 'Bhangra at CSUF aims to preserve the folk culture of Punjab and share that culture with our greater campus. Bhangra''s origin traces back to Sialkot, Punjab where farmers danced amidst cultivating their crops, propagating a culture for future generations. After the partition of Punjab, different regions of Punjab began interacting which sparked the integration of different forms of Bhangra. These forms included Jhumar, Luddi, Giddha, Julli, Daankara, Dhamal, Saami, Kikli, and Gatka. With a goal to connect Punjabis back to their roots, Bhangra at CSUF provides practices, workshops, and performances to exemplify our unique identity. Please follow us on Instagram @titanbhangra to stay connected.', 'bhangracsuf', 'Active', '{"Umbrella (Council)","Fraternity & Sorority","Honor Society","Political/Social Action","Faith","Service","Special Interest","Sport","Career Planning","College of Communications","College of Education","College of Engineering and Computer Science","College of Health and Human Development","College of Humanities & Social Sciences","College of Natural Science and Mathematics","College of the Arts","Health & Wellness","LGBTQ+","College of Business and Economics","Music","Outdoors","Sustainability","Technology"}', '{"cultural","dance"}'),
  ('132963', 'Biology Graduate Students Club', 'This club provides Biological Science graduates and undergraduates the ability to learn about advancements in the field of biology, offers volunteer and mentorship opportunities, and social activities to develop comradery among students and faculty.', 'The Biology Graduate Students Club was established to provide Biological Science graduate and undergraduate students with: *A resource to learn about advancements in biology *Volunteer and mentorship opportunities for students to give back to the community *Social activities to develop comradery among students and faculty *A venue for students to practice conference presentations and receive feedback from their peers **Eligibility to receive funding to attend and present at research conferences', 'bgsc', 'Active', '{"College of Natural Science and Mathematics"}', '{"mentorship","service"}'),
  ('132811', 'Black Business Student Association', 'BBSA is a student ran organization that will provide underrepresented students with a space to outreach, connect, and be provided a supportive environment for academic and career success within the Business enterprise.', 'BBSA is a student ran organization that will provide underrepresented students with a space to outreach, connect, and be provided a supportive environment for academic and career success within the Business enterprise.', 'bbsa', 'Active', '{"Cultural","College of Business and Economics","Social"}', '{"business","career","cultural","social"}'),
  ('132810', 'Black Student Union', 'The BSU fosters student growth and development through diversity, academics, and community services and outreach. We serve 11 clubs: AESA, APAC, BBSA, Divine Servants, EASA, Into the Roots, The Movement, NABJ, NSA, NSBE, and Sistertalk.', 'We the member organizations of the Black Student Union of Californi a State University, Fullerton, recognize the need for the united front among Black/African American student organizations. Formed on a voluntary basis, the purpose of this council is to unite us not only in words, but in action as well. The Black Student Union fosters student growth and development through diversity, academics, and community services and outreach. We provide an opportunity for students of all races to celebrate black culture, lifestyle, and history. We hope to accomplish goals no single organization could on its own-goals that will benefit us all. In the spirit of cooperation, we will enrich the lives of students, faculty, staff and the community at large. Through communication, we will all learn more about the world around us and ourselves. United, we will be a power unto ourselves.', 'bsu', 'Active', '{"Umbrella (Council)","Cultural","Political/Social Action","Faith","Service","Special Interest","Recreation","Dance","Music","Social"}', '{"leadership"}'),
  ('421949', 'Blacks In the Arts', 'Blacks in the Arts is an initiative of the Cal State Fullerton College of the Arts, dedicated to fostering support, visibility, and community among Black artists and Titan arts enthusiasts on campus.', 'Blacks in the Arts is an initiative of the Cal State Fullerton College of the Arts, dedicated to fostering support, visibility, and community among Black artists and Titan arts enthusiasts on campus. The program aims to create meaningful performance and production opportunities for students who may not otherwise have access to mainstage productions. In addition, it seeks to provide a platform for students of color, especially Black students, to engage with and perform works by Black playwrights and artists, as well as to showcase their own original creative work.', 'csufbsu_weebly_com', 'Active', '{"Cultural","College of the Arts"}', '{"arts","cultural"}'),
  ('134901', 'Bridges International Cal State Fullerton', 'The club will hold meetings and activities that focus on introducing international students to American culture. This will give international students a chance to network and practice conversational english.', 'Bridges International is a caring community of Christ-followers committed to serve, promote social connections and engage in spiritual conversations with international students so that students become leaders internationally.', 'bridgesinternational', 'Active', '{"Cultural","Faith","Recreation"}', '{"cultural","faith","recreation"}'),
  ('135930', 'Business and Data Analytics Club', 'BDAC is a pan-university student organization that targets mainly on the technologies and innovations in the field of data sciences and business analytics.', 'The Business and Data Analytics Club (BDAC) at California State University, Fullerton is dedicated to providing ISDS students with opportunities to learn about tools and applications of data analysis and statistical methods to solve real-world business problems. BDAC is open to all CSUF students who are interested in data-oriented careers. We welcome undergraduates, graduate, and MBA students who are interested in data science, data analytics, business analytics, informational systems, and decisions sciences.', 'bdac', 'Active', '{"Special Interest","College of Business and Economics","Technology"}', '{"business","data-science","startups","technology"}'),
  ('135934', 'Business Inter-Club Council', 'Business Inter-Club Council at CSUF is the governing and funding council for clubs and organizations at Mihaylo College of Business & Economics. BICC facilitates the distribution of student fees from Associated Students, Inc. (ASI) for student benefit.', 'The BICC is a funding council that receives student fees from Associated Students, Inc. (ASI) to be used for student benefit. All recognized business clubs report to the BICC and are allowed to propose funding plans to aid their organization. Typical proposals include funding for professional events, guest speakers, and student travel. The council itself also coordinates, funds, and hosts college-wide events such as Business Madness. The BICC aims to facilitate greater and improved degrees of communication and cooperation between the student business-related clubs, organizations, associations, societies, and fraternities affiliated with the CBE. In addition, the BICC shall strive to foster and promote school unity within the entire student body of the CBE, to facilitate and aid in the continual existence and success of all registered business organizations at CSUF, and to enhance the reputation of this body at CSUF and within the community at large. The business clubs/organizations associated with BICC include: AS (Accounting Society) - @csufas ADOBE (Adobe) - @csuf_adobefullerton AKPSI (Alpha Kappa Psi) - @akpsicsuf AMA (American Marketing Association) - @csufama ASCEND (Ascend Leadership) - @csufascend AOSCM (Association of Supply Chain Management) - @csufaoscm ALPFA (Association of Latino Professionals for America) - @alpfa_csuf BTS (Behind the Scenes) - @csufbts BAP (Beta Alpha Psi) - @csufbap BBSA (Black Business Student Association) - @bbsa.csuf BDAC (Business Data Analytics Club) - @csuf_bdac BLSA (Business Legal Studies Association) - @csuf.blsa DSP (Delta Sigma Pi) - @csufdsp EA (Economics Association) - @csufeconomics ETC (Entertainment & Tourism Club) - @etc_csuf FA (Finance Association) - @csuffinance FPA (Financial Planners Association) - @csuf.fpa GIS (Gamma Iota Sigma) - @csufgis HERD (The Herd) - @csuftheherd LBSA (Latino Business Student Association) - @lbsacsuf MTC (Muslim Tech Collaborative) - @mtccsuf REA (Real Estate Association) - @rea.csuf SUM (Sigma Upsilon Mu) - @sigmaupsilonmu SEHR (Society of Excellence in Human Resources) - @csufsehr TIBC (Titan Investment Banking Club) - @csuf.tibc WIBS (Women in Business & STEM) - @wibsfullerton WBA (Women’s Business Association) - @wbacsuf', 'bicc', 'Active', '{"Umbrella (Council)","College of Business and Economics"}', '{"business","leadership"}'),
  ('404888', 'Business Legal Studies Association', 'The Business Legal Studies Association at CSUF fosters student interest in the intersection of law and business. We offer workshops, networking events, and resources to explore careers in business law and build a strong professional foundation.', 'The Business Legal Studies Association (BLSA) at California State University, Fullerton, is dedicated to exploring the dynamic relationship between business and law. Our mission is to educate and empower students interested in the legal aspects of business through engaging workshops, speaker panels, and networking events with professionals in the field. BLSA provides resources and guidance for students considering careers in business law, corporate compliance, legal consulting, or pursuing law school. Join us to connect with like-minded peers, build a competitive edge, and gain valuable insights into this exciting area of study and practice.', 'businesslegalstudiesassociation', 'Active', '{"Special Interest","Career Planning","College of Business and Economics","Social"}', '{"business","career","social"}'),
  ('403643', 'Cal State Furryton', 'A space for furries to connect and enjoy this shared interest we have, and to educate those interested in our community.', 'Cal State Furryton is a club intended to bring together furries, which are fans of anthropomorphic (human-like) animals in media. This includes movies, TV, gaming, cosplay, and other various types of artistic expression within the furry fandom. This club aims to be a safe place for furries to connect at CSUF and educate those interested in what we''re all about as a community!', 'furryton', 'Active', '{"Special Interest","College of the Arts","LGBTQ+","Social"}', '{"lgbtq","social"}'),
  ('134874', 'California Geotechnical Engineering Association', 'The purpose of this organization is to support initiative of the Geo-Institute to increase student membership and participation. Increase awareness among civil engineering undergraduates of the Geotechnical field and graduate school opportunities.', 'The purpose of this organization is to (a) provide opportunities for association and interaction with the faculty and administration of at CSU Fullerton. (b) Support initiative of the Geo-Institute to increase student membership and participation. (c) Increase awareness among civil engineering undergraduates of the geotechnical field and graduate school opportunities. (d) Facilitate planning of annual events within the department.', 'calgeo', 'Active', '{"College of Engineering and Computer Science"}', '{"engineering"}'),
  ('384325', 'California State University, Fullerton Women''s Water Polo Club', 'This club is all about bringing together passionate and determined athletes who love the rush of the game. Whether you''re an experienced player or a beginner, this club is a place to learn and grow.', 'I am aiming for this club to be a vibrant and empowering women''s water polo team at Cal State Fullerton. This club will be all about bringing together fierce and determined athletes who are passionate about the game. I envision practices filled with energy and dedication, where we push ourselves to new heights in the water. But it''s not just about the sport- it''s about building a tight-knit community of supportive teammates. I believe in fostering strong bonds through team bonding activities, both in and out of the pool. From fun outings to heartwarming team dinners, I am all about creating memories that will last a lifetime. This club will strive for growth, unity, and fun in the water. Your Club President, Sofia Pinto', 'womensclubwaterpolo', 'Active', '{"Sport"}', '{"recreation","sport"}'),
  ('348939', 'Cardz For Kidz at CSUF', 'Cardz For Kidz at CSUF is dedicated towards bringing students together to create handmade, uplifting affirmation cards that are donated to children, families, seniors, and veterans in hospitals, schools, senior living, & rehabilitation centers worldwide!', 'Cardz For Kidz at California State University Fullerton is the first student-led college chapter branched from the original CardzforKidz non-profit organization based in Chicago. Cardz For Kidz is dedicated towards bringing students together in order to create handmade, motivating, and uplifting affirmation cards . Students will be able to attend and collaborate with other CSUF organizations for card-making events where students are able to volunteer their time to create personalized cards. These cards provide support, smiles, and encouragement to children, families, seniors, and veterans in hospitals, schools, senior living, and rehabilitation centers , as they are donated to the official CardzforKidz organization that hand delivers every card, room by room. Cardz for Kidz! Introduction', 'cardzforkidz', 'Active', '{"Service","Special Interest","College of Health and Human Development","College of Humanities & Social Sciences","College of Natural Science and Mathematics","College of the Arts","Health & Wellness","Social"}', '{"health-wellness","service","social"}'),
  ('137989', 'Ceramics Club', 'The Ceramics Club helps promote ceramic arts by disseminating information, supporting student exhibitions and participating in campus outreach programs.', 'The Ceramics Club comprises students pursuing a BFA in Ceramics, enrolled in a ceramics class, or who are just passionate about art! Sales are hosted every two weeks with the campus gallery receptions. Other sales that the club will have are posted to the instagram. Proceeds go towards artist lectures and studio supplies for club members.', 'theceramicsclub', 'Active', '{"College of the Arts"}', '{"arts"}'),
  ('429314', 'CHAARG', 'CHAARG is a wellness and fitness organization that empowers college women through fitness, friendship, and personal growth.', 'CHAARG is a national health and wellness organization dedicated to empowering college women to find joy in movement, build meaningful friendships, and prioritize their overall well-being. Our chapter provides an inclusive and supportive community where members can explore different styles of fitness, step outside of their comfort zones, and grow both personally and socially. Through weekly workouts, social events, collaborations, and leadership opportunities, we aim to create a positive environment that encourages confidence, balance, and connection. Our goal is to help students feel supported on campus while promoting a healthy lifestyle that focuses on both physical and mental wellness.', 'csufchaarg', 'Active', '{"Recreation","Health & Wellness","Social"}', '{"health-wellness","recreation","social"}'),
  ('134818', 'Chemistry and Biochemistry Club', 'The Chemistry and Biochemistry (CBC) club is an academic club designed to help CBC majors get into research and to succeed here at CSUF. We participate in many great events including Discoverfest, National Chemistry Week, and professor networking!', 'The purpose of this organization is to provide information about opportunities and careers within the field of Chemistry and Biochemistry while facilitating association and interaction between the students and the faculty of the department of Chemistry and Biochemistry. Furthermore, this organization is to assist in familiarizing students with research opportunities available within the department, as well as a sense of community outreach, which promotes a positive perception of scientific education. Application Form', 'chemistryandbiochemistryclub', 'Active', '{"Service","Special Interest","College of Natural Science and Mathematics","Social"}', '{"career","service","social"}'),
  ('432405', 'Chi Alpha Titan Christian Fellowship', 'Titan Christian Fellowship is a community of CSUF students following Jesus together through discipleship, prayer, worship, fellowship, and witness.', 'The purpose of the Organization is to provide a Christ-centered community in which CSUF students may explore, grow in, and live out the Christian faith. Chi Alpha seeks to reconcile students to Jesus Christ and equip them through Spirit-empowered community to serve the campus, the local community, and the world.', 'titanchristianfellowship', 'Active', '{"Faith"}', '{"faith"}'),
  ('138281', 'Chi Sigma Iota, Kappa Omega Chapter', 'Our chapter''s active members are current students, alumni, and faculty. We promote scholarship, professionalism, excellence in counseling, and recognize high attainment in the pursuit of academic and clinical excellence in the profession of counseling.', 'Chi Sigma Iota is an international counseling academic and honors society that promotes professionalism, leadership, advocacy, and excellence in the counseling profession. Our mission with the Kappa Omega chapter is to provide students with opportunities to develop leadership and professional skills while enriching the counseling student experience while engaging with social justice advocacy. CSI also provides opportunities to interact and network with fellow counseling students! Although membership is limited to invitation only, EVERYONE is welcome to join us at our events! ❀Check out our Instagram for more information @csuf_csi! Give us a follow to stay up to date on meetings, opportunities, and new events!❀ PLEASE NOTE** ROSTER IS NOT IN USE FOR THE ACADEMIC YEAR! Invitations for membership will be sent out in the spring to Dept. of Counseling students who have completed at least 9 units and have a GPA of 3.5 or better.', 'csikappaomega', 'Active', '{"Honor Society","Career Planning","College of Health and Human Development"}', '{"career","leadership"}'),
  ('134786', 'Child and Adolescent Studies Student Association', 'CASSA is the Child and Adolescent Studies Student Association for students who are interested in working with children, adolescents and/or families.', 'Our mission is to provide students with opportunities to develop leadership and professional skills when working with underprivileged children in the community. CASSA also provides opportunities to interact with fellow like-minded individuals; CAS majors and other students who enjoy working with kids are welcome! Check out our Instagram for more information @csufcassa! We send out a Sunday Update every week that has everything you need to know about CASSA activities. Signing up on our said Google Form allows access to it. General meetings every Thursday, 12:00 PM-12:45 PM, Location: TSU Legislative Chambers 1&2', 'cassa', 'Active', '{"Service","College of Health and Human Development"}', '{"service"}'),
  ('138171', 'Clarinet Consort', 'Our organization is to present opportunities in the development and success of clarinet pedagogy and musical development.', 'Clarinet Consort of CSUF is dedicated to the musical development and success of its members by providing opportunities for guest artist masterclasses, clarinet conferences, collaboration with other musical consorts, and performances.', 'csufcc', 'Active', '{"College of the Arts"}', '{"music"}'),
  ('368249', 'Climbing Club', 'A club for all climbing skill levels that offers opportunities for climbing hours at our wall and outside gyms. Fundamental training for top rope belaying and bouldering will be provided. Feel free to join today!', 'We will offer trips to outside locations, gyms, and frequently meet at the school wall to discuss trips and club information. Feel free to join if you want to learn about rock-climbing.', 'climbingclub', 'Active', '{"Special Interest","Health & Wellness","Outdoors"}', '{"health-wellness","outdoors","recreation"}'),
  ('135091', 'Club Baseball', 'Club Baseball''s main purpose is to provide a secondary source of baseball for players who do not have the opportunity to play for our NCAA team on campus, but still have the interest and urge to compete at an intercollegiate club level.', '', 'csufclubbaseball', 'Active', '{"Sport","Recreation"}', '{"recreation","sport"}'),
  ('403663', 'Club Golf', 'Club Golf provides an opportunity for students to practice, play, and compete in golf, while participating in occasional social and philanthropic events.', '"Follow our INSTA @csufclubgolf, the BEST way to stay connected, find club links, & join our discord! While CSUF already hosts competitive men’s and women’s golf teams, this club would cater to a different segment of the student population: those who are beginners, those seeking a sense of community, those looking to better their physical and mental health, or those who simply prefer a more casual approach to the game. Throughout my time at Cal State Fullerton, I have met many students who work multiple jobs and manage demanding schedules, often lacking the financial stability to introduce themselves to the sport. Our club aims to bridge that gap by building a constructive community and providing beginners with free rental equipment through our established connections. Even experienced players will find value in this organization. While they may already possess the skills and equipment, they can still benefit from the unique community and networking experiences that Club Golf offers. From developing mental discipline to improving physical health, the benefits of golf are extensive. We believe that the skills our members gain will serve them well into their professional futures—perhaps even helping them seal a deal on the course." Knowing that Cal State Fullerton serves students from diverse financial and social backgrounds, I am committed to providing others with the same opportunities I was fortunate enough to receive. While CSUF already hosts competitive men’s and women’s golf teams, this club would cater to a different segment of the student population: those who are beginners, those seeking a sense of community, those looking to better their physical and mental health, or those who simply prefer a more casual approach to the game. Throughout my time at Cal State Fullerton, I have met many students who work multiple jobs and manage demanding schedules, often lacking the financial stability to introduce themselves to the sport. Our club aims to bridge that gap by building a constructive community and providing beginners with free rental equipment through our established connections. Even experienced players will find value in this organization. While they may already possess the skills and equipment, they might still lack the unique community and networking experiences that Club Golf offers. From developing mental discipline to improving physical health, the benefits of golf are extensive. We believe that the skills our members gain will serve them well into their professional futures—perhaps even helping them seal a deal on the course.', 'clubgolf', 'Active', '{"Special Interest","Sport","Recreation","Outdoors","Social"}', '{"outdoors","recreation","service","social","sport"}'),
  ('135194', 'Club Softball', 'CSUF Club Softball is a secondary source for Cal State Fullerton students to compete at an intercollegiate competitive level.', '', 'csufclubsoftball', 'Active', '{"Sport"}', '{"recreation","sport"}'),
  ('135202', 'Club TEACH', 'We are pre-service teachers engaging in community outreach and philanthropy work in local school districts. We also create networking connections and opportunities for club members, teachers, faculty, and incoming students.', 'We are pre-service teachers engaging in community outreach and philanthropy work in local school districts. We also create networking connections and opportunities for club members, teachers, faculty, and incoming students.', 'clubteach', 'Active', '{"Service","Special Interest","Recreation","College of Education","Social"}', '{"career","recreation","service","social"}'),
  ('135737', 'College Republicans at California State University Fullerton', 'A strong community of open dialogue, leadership, and conservative values. Meetings : Tuesday at 5:30 pm - Internships, volunteering, public speaking , and networking IG : @csufrepublicans E-mail : titan.csufrepublicans@gmail.com', 'The College Republicans at Cal State Fullerton is a student-led organization that promotes free speech, respectful dialogue, and political engagement. We believe university communities should be places where diverse ideas are heard and discussed — not ignored or shut down. Our goal is to create a welcoming space for students to express their views, learn from others, and grow through meaningful conversations. Encouraging thoughtful and open conversation, even when opinions differ, is one of our core principles. Our values are rooted in self-determination, personal responsibility, and the belief that individuals, not government, drive real progress. We aim to show that the Republican Party stands for opportunity, hard work, and community improvement — ideals that are open to everyone. Beyond politics, our organization is committed to helping students grow both personally and professionally. Members gain access to real-world experiences such as volunteering, internships, and employment through our strong relationship with the Orange County GOP. Members will build leadership, communication, teamwork, and public speaking skills by attending political events, speaking at committee meetings, and participating in community outreach. As a member of the College Republicans at Cal State Fullerton, you will join a wide network that includes senators, mayors, attorneys, business owners, law enforcement, and other professionals who are passionate about mentoring and supporting students. Whether you are interested in law, public policy, politics, or simply becoming a more confident and informed individual, this organization provides the tools and connections to help you grow. Reach out! IG: @csufrepublicans Email: titan.csufrepublicans@gmail.com', 'csufrepublicans', 'Active', '{"Political/Social Action","Service","Special Interest","Career Planning","Social"}', '{"career","leadership","political-social-action","service","social"}'),
  ('383657', 'Comics at CSUF', 'We aim to make a comic community for all. We read and discuss different genres of comics. Create community events and enjoy playing games, and have fun discussions with others.', 'Focus on a monthly topic such as mental health, or breast cancer awareness—suicide prevention, Pride Month, black history month, Hispanic Heritage Month, etc We will focus on characters that revolve around these types of groups and other groups w/ action, comedy, different publishing companies, authors. We want to enjoy comic books for the messages that they speak along with the pages that catch our attention! Discord: Instagram: @comicsatcsuf', 'comics-at-csuf', 'Active', '{"Special Interest","College of Health and Human Development","College of the Arts"}', '{"social"}'),
  ('134498', 'Communications Inter-Club Council', 'As part of the Associated Students Inc. (ASI), the Communications Inter-Club Council (CICC) is the funding council for registered student organizations associated with the College of Communications.', 'The CICC is responsible for disbursing funds directly from ASI to students. The CICC meets on a weekly basis, where students and their clubs can submit proposals for funding to cover the cost of presenting at research conferences, guest speakers, or other club activities. All recognized communications clubs report to the CICC and are allowed to propose funding plans to aid their organization. The council itself also coordinates, funds, and hosts college-wide events. In addition to funding its member organizations, the CICC strives to aid its members in successful operations that benefit student members, the College of Communications, and the University. We strive to promote Cal State Fullerton and its students within the national and international academic community. Student clubs and organizations affiliated with the CICC include: Advertising Club, Entertainment & Tourism Club, Latino Journalists at CSUF, Lambda Pi Eta, Music Industry Club, Student for Smiles, Student Speech Therapists And Audiologists Nurturing Cultural Enrichment, Public Relations Student Society of America, National Student Speech-Language Hearing Association, Honors Student Advisory Council, and Augmentative and Alternative Communication. General Council Meetings will be on Fridays from 9:15 to 10:15 a.m. in College Park. Weekly general council meetings will be in person for the first week and on Zoom for the rest. Please reach out to CICC Chair Eve Dowdell (cicc.chair.csuf@gmail.com) for more information. To register or re-register into the CICC as an organization, please fill out the registration form provided in this link: CICC Club Registration Form, 2026-27', 'cicc', 'Active', '{"Umbrella (Council)","College of Communications"}', '{"leadership"}'),
  ('133036', 'Community Service Inter-Club Council', 'Check out the Community Service Inter-club Council where we serve as a resource and link for students interested in becoming a part of a community service-based organization on campus. We offer funding, support, and guidance to clubs/students on campus.', 'The Community Service ICC strives to advocate on behalf of our clubs and the populations they serve, foster the value of community service that unites our clubs, share their positive impacts, and develop service-minded student leaders. We aim to bridge the gap between service organizations and to offer support through networking, funding, and interaction. Member Organizations Cardz for Kidz Hopefull Lift-57 NMDP Student Veterans Association Titanthon Volunteer Income Tax Assistance', 'csicc', 'Active', '{"Umbrella (Council)","Service"}', '{"leadership","service"}'),
  ('223543', 'Construction Engineering Management Association', 'The Construction Engineering Management Association will strive to create invaluable opportunities for students to gain experience and exposure to industry professionals in the Construction and Civil Industries.', 'The Construction Engineering Management Association will strive to create invaluable opportunities for students to gain experience and exposure to industry professionals in the Construction and Civil Industries. CEMA will help advance student interests in both Heavy Civil Construction and Commercial Building by providing opportunities through professional development, industry exposure, social events, technical training, and encouragement to compete in National competitions. We help our members learn skills such as reading plans and scheduling so that they can become competitive in the marketplace.', 'cema', 'Active', '{"Special Interest","Career Planning","College of Engineering and Computer Science","Social"}', '{"career","engineering","social"}'),
  ('137489', 'Coptic Orthodox Christians Club', 'This club is designed for Coptic Orthodox Christians as well as other students to gather in fellowship for weekly meetings, activities and community service opportunities.', 'Coptic Club is a faith-based student organization dedicated to fostering spiritual growth, cultural understanding, and community among students of Coptic Orthodox Christian background and those interested in learning about the Coptic faith. The club provides a welcoming environment for prayer, fellowship, service, and educational events that reflect the teachings and traditions of the Coptic Orthodox Church. Through weekly meetings, guest speakers, and social gatherings, Coptic Club encourages members to deepen their faith, engage in meaningful dialogue, and build lasting friendships rooted in shared values of love, humility, and service.', 'httpswwwcopticclubsorg', 'Active', '{"Cultural","Faith","Service","Social"}', '{"cultural","faith","service","social"}'),
  ('132827', 'Creative Writing Club', 'Creative Writing Club provides opportunities for all students on campus interested in creative writing to improve upon their craft through interactive workshops and events planned throughout the year.', 'The purpose of this organization is to provide opportunities for all students on campus interested in creative writing (i.e. poetry, fiction, song writing, screenplays, spoken word etc.) to: improve upon their craft through interactive workshops; learn about the process of getting published and/or self-publishing; share their creative works with others in small and large public spaces; and meet creative writing professionals at events planned during the year. We have a discord, come join us!', 'creativewritingclub', 'Active', '{"Special Interest","College of Humanities & Social Sciences","Social"}', '{"social"}'),
  ('137632', 'Criminal Justice Students'' Association', 'CJSA recognizes the academic excellence of undergraduate and graduate students of criminal justice at California State University, Fullerton. CJSA provides opportunities to meet and network with other criminal justice majors, faculty, and professionals.', 'The Criminal Justice Students’ Association (CJSA) Organization Description 2025-2026 CJSA recognizes the academic excellence of undergraduate and graduate students interested in the criminal justice system at California State University, Fullerton. The goals of CJSA are to honor and promote academic excellence, community service, educational leadership, and unity. CJSA provides opportunities to meet and network with other criminal justice majors, faculty, and professionals in the field of criminal justice through seminars, facility and program tours, volunteer work, and internships. It also provides forums for discussing and debating current criminal justice issues that affect us in our chosen vocation, communities, school, and society. Students become involved in community outreach through fundraising and volunteer work while building relationships with peers, faculty, and criminal justice professionals and providing excellent leadership skills development and experience. Finally, it provides an atmosphere for members to socially interact in healthy and productive', 'cjsa', 'Active', '{"Service","Special Interest","Career Planning","College of Humanities & Social Sciences","Social"}', '{"career","service","social"}'),
  ('132867', 'Cru', 'At Cru at CSUF, we are a caring community passionate about connecting people to Jesus Christ and to each other! Our large group meetings are on Tuesdays at 5:30-7:00pm, with Bible studies, social events etc.', 'At Cru at CSUF, we’d love to invite you to join our community as you go along your spiritual journey. Whether you’re a Christian looking to grow and learn how to share your faith, or someone who is still figuring out what you believe about spiritual matters, you’ll find a place to make friends and learn about Jesus. Come hear a great speaker, worship with other Titans, and connect in community. See our Instagram for updates on locations for Spring 2026! We have several different kinds of small groups to get involved with at Cal State Fullerton. If you’re looking to serve, we have a variety of opportunities within the semester that exist to build community through serving the greater Cru or campus community. If you aren’t able to make it to a meeting, want to hear about other socials or small groups, we have plenty of other ways for you to get connected! We post updates about events, small group Bible studies, and retreats. Follow us on Instagram @csufcru , on GroupMe, or email our Staff member, Tiki, at V ictoria.gonzalez@cru.org with any questions!', 'cru', 'Active', '{"Faith"}', '{"faith"}'),
  ('383331', 'CSUF Asian Pacific Islander South Asian Psychological Association', 'CAPISAPA is a club that is dedicated towards providing a safe space for students interested in Asian American psychology. We hold regular in-person meetings on Wednesdays from 6:15-8 PM and hold socials and academic meetings.', 'First established in Fall 2023, CAPISAPA is a club dedicated towards creating a safe place for CSUF students interested in Asian American Psychology to network, connect, and build community. Club events include Bigs and Littles socials and informational sessions on grad school, psychology professions, and networking. There are NO GPA, ethnic, or major requirements to engage in this student organization, and everyone is welcome!', 'capisapa', 'Active', '{"Cultural","College of Humanities & Social Sciences","Social"}', '{"cultural","social"}'),
  ('382110', 'CSUF Chess Club', 'Play or learn to play chess with us! Join us at our weekly meeting or on Discord: We are friendly and open to both complete beginners and experienced players.', 'CSUF Chess Club is dedicated to playing and promoting the game of chess on CSUF campus and in the broader Fullerton community. We emphasize inclusion and equity as our core values and promote the participation of historically marginalized identities in the game of chess.', 'chess', 'Active', '{"Special Interest","Sport"}', '{"recreation","sport"}'),
  ('431101', 'CSUF Disability & Mental Wellness', 'The Disability & Mental Wellness Club is a welcoming space where students with disabilities and allies can connect, build friendships, support one another, and promote inclusion on campus.', 'The Disability & Mental Wellness Club is a welcoming space where students with disabilities and allies can connect, build friendships, support one another, and promote inclusion on campus.', 'csufdmw', 'Active', '{"Cultural","Special Interest","College of Health and Human Development","Social"}', '{"cultural","health-wellness","social"}'),
  ('429534', 'CSUF Fighting Game Community', 'The purpose of this organization is to help students of similar interests in the arcade culture and competitive nature of fighting games get together and welcome each other to a larger community in Southern California as a whole.', 'Welcome to the Cal State Fullerton Fighting Game Community! We are a club focused on enjoying fighting games on a competitive and social aspect, sharing our dedication across SoCal! Anyone is welcome to join, from first time players to active ranked warriors in ANY game, we are glad to have people interested in a booming revival for the social arcade life!', 'fullertonfgc', 'Active', '{"Special Interest","Recreation","Social"}', '{"recreation","social"}'),
  ('431831', 'CSUF Forensic Science Club', 'To connect interested students to professionals in the field and to further teach them in aspects of Forensic Science', '', 'csufforensicsc', 'Active', '{"Special Interest"}', '{"social"}'),
  ('138410', 'CSUF Gaming & Esports', 'Gaming Club & Esports hopes to foster and promote a welcoming environment to introduce students at California State University, Fullerton to gaming culture.', 'CSUF Gaming & Esports is a club that offers many opportunities for members to express their passion for video games both competitively and socially. We provide a welcoming environment for all types of gamers at Cal State Fullerton to socialize with one another', 'csufesports', 'Active', '{"Service","Special Interest","Sport","Recreation","Social","Technology"}', '{"recreation","service","social","sport","technology"}'),
  ('423930', 'CSUF Karaoke Club', 'Karaoke Club brings all people of all backgrounds through singing karaoke. We strive to build a community in which fosters connection and team-building.', 'Our Karaoke Club here at Cal State Fullerton brings together all people of all backgrounds through karaoke. We strive to build a community that fosters connection and team-building. We incorporate all types of music in karaoke form for our general members to enjoy their time at our club meetings! This club strives to CHANGE the WORLD through karaoke. This club is for everyone and anyone who loves to sing for fun and wants to make new friends through singing!', 'csufkaraokeclub', 'Active', '{"Cultural","Special Interest","College of the Arts","Music","Social"}', '{"cultural","music","social"}'),
  ('415886', 'CSUF Model United Nations', 'CSUF MUN explores global issues and international politics in an interactive team setting. Members will develop essential skills such as critical thinking, communication, teamwork, and conflict resolution, all while creating long-lasting connections.', 'The CSUF Model United Nations program offers students the opportunity to learn about global issues and international politics in an interactive team environment. MUN allows students to take what they learn in the classroom and apply it to what is going on in the real world. The program creates a space where students can come together, get involved, and build lasting friendships. Students who participate in MUN also gain essential life skills. The skills we focus on are: Critical and creative thinking Problem-solving Decision making Effective communication Interpersonal relationship skills Team and rapport building Conflict resolution', 'modelun', 'Active', '{"Special Interest","College of Humanities & Social Sciences","Social"}', '{"political-social-action","social"}'),
  ('365639', 'CSUF Star Wars Club', 'Hello Titans! CSUF Star Wars Club is back! We strive to have a home for Star Wars fans and give them a welcoming space to talk all things Star Wars.', 'CSUF Star Wars Club strives to build a community of fans across many aspects of the franchise, from the most loyal fans to casual enjoyers to those new to Star Wars. We strive to be an organization that welcomes everyone who participates in our events, and we use our club as a social setting to help fellow Titans make more connections in the Star Wars community. Contacts: Instagram: star.wars.csuf Email: csuf.starwars77@', 'starwarsclub', 'Active', '{"Special Interest","Social"}', '{"social"}'),
  ('137490', 'CSUF Surf Club', 'The main focus of this club is to bring the surfers, bodyboarders and bodysurfers from CSUF together. We will have planned surf meets and events. Our goal is to not only have people enjoy the ocean but also respect it as well.', 'Hey everyone! This is a simple club where we meet up, meet new people and all paddle out together. We send emails but the very best way to be in the know is by filling out our interest form in our instagram bio @csufsurfclub. Through there we plan out events. Hope to see you out there! We can teach when available but this club is not recommended for first timers. There is no fee to join but student must provide a board and transportation. The goal of the club is to meet once a week at the beaches in Orange County and relax while catching a couple of waves. Catch us on our social media ! Instagram: @csuf_surfclub', 'csufsurfclub', 'Active', '{"Special Interest","Sport","Recreation","Health & Wellness","Outdoors","Social"}', '{"health-wellness","outdoors","recreation","social","sport"}'),
  ('403664', 'CSUF Swim Club', 'CSUF Swim Club offers an opportunity for students to form a new strong community at Cal State Fullerton. We intend our swimmers to get stronger, faster, and more competitive which can help positively contribute with their performance and their lives.', '', 'csufswimclub', 'Active', '{"Sport","Recreation","Social"}', '{"recreation","social","sport"}'),
  ('412080', 'CSUF Women''s Club Basketball', 'Our women''s club basketball fosters a supportive team environment, focusing on skills development, team building, and competitive play. We host open gyms and clinics, while competing in tournaments and engaging with the campus and basketball community.', 'CSUF Women''s Club Basketball is dedicated to providing an opportunity for women athletes in our student population to participate in intercollegiate basketball tournaments. Our mission is to promote skills development, teamwork, and competitive play strategies through a variety of tournaments and social events. We provide opportunities for students to improve their basketball abilities, connect with basketball enthusiasts, and to give back to the community. The club hosts open gyms, team bonding activities, and the opportunity to volunteer in skills-building clinics for the youth. We compete in local and regional tournaments, representing CSUF Student Life and Leadership Sports Clubs. Whether you are an experience player or interested in starting basketball, we welcome all to join and be part of having a fun sports experience.', 'womensclubbasketball', 'Active', '{"Service","Sport","Recreation","Social"}', '{"recreation","service","social","sport"}'),
  ('136279', 'Dance Association', 'Dance Association provides a greater opportunity for members to become involved in the Dance and Theater Department, along with the campus community.', 'The purpose of Dance Association is to provide students of all majors an opportunity to dance and to find a community of supportive, like-minded individuals. Our club''s major focus is to provide students with free pop-up classes and master classes taught by students, alumni, and guest artists. We also offer mentorship and onboarding for new students, as well as leadership experience. In addition, DA hosts concessions during performances and other fundraisers to provide scholarships and funding for students to explore their creative endeavors. We aim to provide a space for dancers and individuals interested in dance to engage with the dance community at CSUF and beyond. You can sign up with us through TitanLink, but if interested check out our instagram @csufdanceassociation where we post about all of our events and updates!', 'danceassociationcsuf', 'Active', '{"Special Interest","Sport","Recreation","Career Planning","College of the Arts","Dance","Health & Wellness","Social"}', '{"arts","career","dance","health-wellness","recreation","social","sport"}'),
  ('132823', 'Data Science and Machine Learning', 'The Data Science and Machine learning club''s mission is to create an inclusive environment to network, and foster growth and interest in Technology and its practical uses from data science and machine learning techniques.', 'The purpose of this club is to organize meetings to share knowledge and experience about Machine Learning, Data Science, and Business Intelligence. Also, we are planning to host industry events, workshops, and Machine Learning/Data competitions/Projects. If you are interested in the club, please select the Join button through TitainLink. If you have any questions please email us at csufdsml@gmail.com. Also please join the discord to get up-to-date information regarding the club and its future meeting and workshops.', 'machine-learning-and-data-science-club', 'Active', '{"Special Interest","College of Engineering and Computer Science","College of Business and Economics","Technology"}', '{"ai","data-science","technology"}'),
  ('331331', 'Delta Epsilon Mu - Beta Alpha Chapter', 'Delta Epsilon Mu is the nation''s premier Professional Pre-Health Co-Ed Fraternity. Our organization works with pre-health students across medicine, dentistry, nursing, psychology, physical therapy, veterinary, and allied health studies.', 'Delta Epsilon Mu is the nation’s premier professional pre-health co-ed fraternity. Our fraternity seeks to unite students of diverse backgrounds and pre-health interests under the pillars of Loyalty, Dedication, Friendship, and Support. Along with our four pillars, the Beta Alpha Chapter has created a positive, inclusive, and supportive space, filled with opportunities and resources, for our members to grow throughout their undergraduate path and flourish as they enter the pre-health field to create the next generation of leaders within the community. Please fill out our interest form below, if you are interested in joining! Don''t forget to check us out on our Facebook and Instagram ! Please email us if you have any questions or concerns!', 'dembetaalpha', 'Active', '{"Fraternity & Sorority","Service","Career Planning","College of Health and Human Development","College of Humanities & Social Sciences","College of Natural Science and Mathematics","Health & Wellness","Social"}', '{"career","greek-life","health-wellness","leadership","service","social"}'),
  ('135358', 'Delta Sigma Pi', 'Delta Sigma Pi is America''s foremost Professional Fraternity with over 250,000 members nationally who hold themselves to the highest standards of excellence in the areas of professionalism, community service and brotherhood.', 'Delta Sigma Pi is a Professional Fraternity organized to foster the study of business in universities; to encourage scholarship, social activity and the association of students for their mutual advancement by research and practice; to promote closer affiliation between the commercial world and students of commerce, and to further a higher standard of commercial ethics and culture and the civic and commercial welfare of the community.', 'deltasigmapi', 'Active', '{"Service","Special Interest","College of Business and Economics","Social"}', '{"career","greek-life","leadership","service","social"}'),
  ('430731', 'Delta Upsilon', 'Delta Upsilon is a values-based fraternity dedicated to leadership, academic excellence, service, friendship, and personal development while fostering lifelong brotherhood at California State University, Fullerton.', 'Delta Upsilon at California State University, Fullerton is a values-based fraternity committed to developing ethical leaders and fostering lifelong friendships through scholarship, service, leadership, and personal growth. Our chapter provides members with opportunities to build professional skills, engage with the campus and local community, and support one another academically and personally. We strive to create an inclusive environment where members are encouraged to lead with integrity, uphold the values of Delta Upsilon, and make a positive impact at CSUF and beyond.', 'deltaupsilon', 'Active', '{"Fraternity & Sorority"}', '{"greek-life","leadership","service","social"}'),
  ('135032', 'Delta Zeta Sorority', 'The Iota Upsilon Chapter of Delta Zeta was founded at Cal State Fullerton in April, 1968. Our Values: Friendship, Curiosity, Generosity, Empowerment, Citizenship, and Belonging. Our motto: A life-long, values-based membership experience for women.', 'Delta Zeta ( ΔΖ ) is an international college sorority founded on October 24, 1902, at Miami University in Oxford, Ohio. Today, Delta Zeta is one of the biggest sororities in the world with 170 collegiate chapters in the United States and Canada; and over 200 alumnae chapters. Our Values: Friendship, Curiosity, Generosity, Empowerment, Community, and Belonging. Our Motto: Love that is ever steadfast. Our Mission: A life-long, values-based membership experience for women. Our Vision: A global women''s organization whose shared values truly inspire action and impact lives. Our Philanthropies Delta Zeta''s national philanthropy is Speech and Hearing. In 2015, Delta Zeta named Starkey Hearing Foundation our National Philanthropy Partner in an effort to extend our impact throughout the world. In just 5 years, Delta Zeta raised over $5.5 million for Starkey! Our National Service Project is The Painted Turtle. The Painted Turtle supports children with serious medical conditions. Join our Panhellenic sisterhood today! Check out our Instagram to fill out an interest form and start your journey with Delta Zeta today! Fill', 'deltazeta', 'Active', '{"Fraternity & Sorority"}', '{"greek-life","social"}'),
  ('145305', 'Design Build Institute of America', 'Design-Build Institute of America is an organization that will help students familiarize themselves with Design Build projects and to meet professionals working on Design Build Projects.', 'The only organization that defines, teaches and promotes best practices in design-build project delivery, with educational programs that are developed to teach practical "how to" strategies and techniques for the effective implementation of design-build project.', 'dbia', 'Active', '{"College of Engineering and Computer Science"}', '{"social"}'),
  ('365092', 'Disney Club at Cal State Fullerton', 'A community where Disney fans and Disney enthusiasts can come together, to inspire, entertain and enjoy all things Disney!', 'This club is for anyone who loves Disney. We are a safe space where people can build relationships and meet other Disney fans. We are here to honor the legacy of Walt Disney and look forward to the upcoming projects of the Walt Disney Company. We strive to build a diverse group with an openness to new ideas and exploration of new stories and cultures. Activities include Disney Hangouts, Disney Movie watching, Disney-themed Activities and Discussions, Guest Speakers, Competitions with prizes, Panels and special events, mental health talks, arts and crafts, food days/potlucks, and more! We will also be working closely to help with any career opportunities at the Walt Disney Company and other opportunities related to Disney.', 'disneyclub', 'Active', '{"Special Interest","College of Communications","Social"}', '{"social"}'),
  ('145726', 'Diversity Resilience Education Access Movement Co-Operation', 'DREAM Co-op is dedicated to unifying the undocumented and ally community at CSUF while also advocating on campus and in the broader community for the rights of our undocumented population.', 'The purpose of this organization is to….. Bring awareness to the larger community and first generation college students about AB-540, California Dream Act, Deferred Action and any changes pertaining to immigration legislation. Provide self-empowerment to its members through moral support, mentorship and unity. Facilitate information about financial aid resources for AB-540, undocumented, immigrants, and first-generation students, such as available scholarships, job opportunities, and internships. Fundraise to provide opportunities for the advancement of our members. Advocate on issues relating to the members in the community.', 'dreamco-op', 'Active', '{"Umbrella (Council)","Cultural","Political/Social Action","Service","Special Interest"}', '{"cultural","political-social-action","service"}'),
  ('136209', 'DREAM Campus Ministries', 'The purpose of the organization is to build quality relationships and unity while providing opportunities for anyone to learn more about the Christian faith.', 'The D.R.E.A.M. Campus Ministries is aimed toward helping students have resources and guidance on how to live out the Bible practically on a daily basis. D.R.E.A.M. is our acronym for Disciples Reaching and Evangelizing All Mankind!', 'dream', 'Active', '{"Cultural","Faith"}', '{"cultural","faith"}'),
  ('383407', 'East African Student Association', 'The East African Student Association (EASA) aims to contribute to a thriving East African presence at CSUF. EASA strives to educate, celebrate, and promote the variety of cultures within the East African region.', 'The East African Student Association (EASA) aims to unite students at CSUF with roots in East Africa. Our organization is dedicated to fostering a sense of belonging and cultural exchange among East African students and those interested in East African cultures. Through engaging events, educational programs, and social gatherings, EASA strives to celebrate the rich diversity and heritage of East Africa while providing a platform for personal and professional growth.', 'csufeasa', 'Active', '{"Cultural"}', '{"cultural"}'),
  ('132498', 'Economics Association', 'The Economics Association is a student-run club whose goal is to advance and educate CSUF Students on relevant economic topics and provide career opportunities. We strive to be engaging, inclusive, and community driven in all of our efforts.', 'The Economics Association is a student-centered club whose goal is to advance and educate CSUF Students on relevant economic topics and provide career opportunities. We strive to be engaging, inclusive, and community-driven in all of our efforts. Events are balanced between academic, professional, and social. Events that the Economics Association hold include: Guest speaker events Company tours Internship Opportunities Article discussions Guest professor lectures Social events Volunteer opportunities', 'economicsassociation', 'Active', '{"Service","Special Interest","College of Business and Economics","Social"}', '{"business","career","service","social"}'),
  ('135650', 'Education Inter-Club Council', 'The College of Education Inter-Club Council serves students as a funding body from ASI that can help fund travel to education conferences and research. We serve as an advisory board and a liaison between clubs, the student body, and the Associate Dean.', 'The purpose of this organization is to provide opportunities for ASI interaction between the students in the College of Education and the faculty and administration of the College of Education, to act as a funding body for clubs and organizations within the College, and to serve as an advisory board to the Assistant Dean of Student Affairs for the College of Education. ANNOUNCEMENTS: Visit our website for more information: Registered Organizations Club TEACH Higher Education Leadership Organization Student California Teacher''s Association NAfME (National Association for Music Education)', 'eicc', 'Active', '{"Umbrella (Council)","College of Education"}', '{"leadership"}'),
  ('424892', 'End Overdose at Cal State Fullerton', 'End Overdose at Cal State Fullerton is a student-led public health organization dedicated to overdose prevention, education and harm reduction, saving lives through awareness, training and community outreach on campus.', 'End Overdose at Cal State Fullerton is an official affiliation chapter of End Overdose, a national nonprofit organization focused on overdose prevention and harm reduction education. We work to reduce preventable overdose deaths by providing our community with evidence-based education about substance use, how to recognize an overdose and naloxone administration. We will host educational workshops, campus tabling events, and training sessions that promote health awareness, beating stigma and promoting safety in the CSUF community. We aim to empower students with knowledge than can save their peers lives, connecting them with resources to foster a community where we all look out for each other.', 'endoverdose', 'Active', '{"Service","College of Health and Human Development","College of Humanities & Social Sciences","Health & Wellness"}', '{"health-wellness","service"}'),
  ('137642', 'Engineering & Computer Science Inter Club Council', 'The purpose of this organization is to utilize funds allocated by Associated Students, Inc. (ASI) through democratic means for the purpose of enriching the experience of Engineering & Computer-Science students through the student clubs.', 'ECS- ICC will serve as the College of Engineering and Computer Science student leadership body. They will be responsible for the planning and implementing of activities that enrich the ECS student experience. ECS - ICC supports clubs in computer science, computer engineering, civil & environmental engineering, electrical engineering, and mechanical engineering. These clubs include; Association for Computing Machinery, Association for Computing Machinery - Women, Association for Computing Machinery SIGGRAPH, American Society of Civil Engineers, American Society of Mechanical Engineers, Society of Women Engineers, Construction Engineering Management Association, Data Science and Machine Learning, Design Build Institute of America, Developer Student Club, CalGeo, Institute of Transportation Engineers, American Institute for Aeronautics and Astronautics, Society of Hispanic Professional Engineers, National Society of Black Engineers, Society of Automotive Engineers, Theta Tau, Titan Aero, Titan Rocket, Titan Rover, TitanSat, Video Game Design Club, and more', 'ecsicc', 'Active', '{"Umbrella (Council)","Special Interest","Recreation","College of Engineering and Computer Science","Social","Technology"}', '{"engineering","leadership","political-social-action","recreation","social","software-engineering","technology"}'),
  ('132917', 'Entertainment & Tourism Club at California State University, Fullerton', 'ETC prides itself on hosting a variety of events for members to not only discover career paths in the entertainment and tourism industries but also experience the industry firsthand through networking, industry events, and work opportunities.', 'The Entertainment and Tourism Club (ETC) specializes in providing resources & opportunities to students interested in pursuing a career in Entertainment & Tourism. ETC is proud to be a premier student organization of the College of Communications. For the past 20 years, our mission has been to provide students with the opportunity to network and learn from entertainment and tourism professionals. We do this by hosting numerous panels and events where students are able to learn valuable industry knowledge and network with entertainment and tourism professionals. ETC offers its members a chance to interact with various professionals in the entertainment and tourism industry. Our organization participates in events such as TV tapings, networking meet & greets, and Hollywood events such as large-scale award shows. ETC produces a multitude of industry panels throughout the year and concludes the year with an annual industry social mixer.* Our mission is to provide students with the opportunity to network and learn from entertainment and tourism professionals.', 'etc', 'Active', '{"Special Interest","College of Communications"}', '{"career"}'),
  ('133205', 'Epic Movement', 'The Epic Movement is a Cru ministry, focused on reaching Asian American students and faculty through building Christ-centered movements that are culturally meaningful and significant. FaceBook: Epic CSUF IG: csuf_epicmovement', 'We have our large group every Wednesday at 5:30! There are also small groups throughout the week. Contact us if you have any questions. Instagram: @csuf_epicmovement FaceBook: Epic CSUF Email: epicmovement.csuf@gmail.com', 'epicmovement', 'Active', '{"Faith"}', '{"cultural","faith"}'),
  ('132414', 'Eta Sigma Gamma Professional Health Education Honorary', 'Eta Sigma Gamma is a national health education honorary for students who are either majors or minors in Health Science. Through the honorary, students are introduced to opportunities in scholarship, networking, teaching, research, and service.', 'Welcome to the Eta Sigma Gamma (ESG) organization page! ESG is another opportunity to enhance your college experience On paper, we are a health science honor society. We offer so much more than that. Joining ESG is an opportunity to network with Public Health faculty, public health/health care professionals, and like-minded students. This year, we are expanding our horizons with guest speakers, fundraisers, social events (such as with CSU Long Beach ESG), health awareness events, volunteer opportunities, and more! It''s important to build these connections and be part of something bigger. Mission The mission of the honorary is promotion of the discipline by elevating the standards, ideals, competence and ethics of professionally prepared men and women in Public Health. Goals The goals of the honorary include: Supporting the planning, implementation and evaluation of health education programs and resources Stimulating and disseminating scientific research; Motivating and providing health education services Recognizing academic achievement Supporting health education advocacy initiatives Promoting professional standards and ethics Promoting networking activities among health educators and related professionals *Note: Eta Sigma Gamma only accepts new members during the Fall semester.', 'esg', 'Active', '{"Honor Society","College of Health and Human Development"}', '{"career","health-wellness","leadership","service"}'),
  ('226425', 'Evolution and Genomics Research Club', 'EAGR Club is focused on STEM outreach to minority and low income communities with the model organism Drosophila melanogaster. We aim to give children the opportunity to learn basic lab techniques and concepts at after school programs on and off campus.', 'EAGR lab is focused on outreach to low income and minority communities with the aim of giving kids the opportunity to participate in STEM. We will accomplish this by working hand in hand with programs such as Kids 2 College on campus and the Fullerton Library and their after school program. We as an organization have also created a children''s book focused on a fictional fruit fly in collaboration with the art department which we intend to incorporate into our outreach via donating as well as going to after school programs to read it allowed to children and talk to them about our own participation in STEM. The purpose of our club is to inspire and encourage children to get involved in STEM and pursue a higher education. We as a club have a very diverse background, many of us coming from low income or minority communities, and want children from these area to know that the opportunities they have are endless.', 'eagr-club', 'Active', '{"College of Natural Science and Mathematics"}', '{"social"}'),
  ('132474', 'Finance Association', 'The Finance Association''s mission is to equip students with the means to start their careers through connections with professionals, office tours, and interactive workshops, in addition to striving to foster a close community of like-minded students.', 'To uphold the high ethical standards, spirit of scientific inquiry, and educational endeavors in the field of finance; to promote friendly relations between students, faculty, and business community and enhance the reputation of the Finance Department.', 'csuffinanceassociation', 'Active', '{"College of Business and Economics"}', '{"business","career"}'),
  ('181549', 'Financial Planning Association of California State University, Fullerton Student Community', 'The mission statement of CSUF FPA is to provide an environment that will foster skills, industry knowledge, and professional development for our members to succeed in careers in personal financial planning.', 'We are a professional development group dedicated to creating an environment that fosters development and enhancement of skills necessary for a career in personal finance. By creating opportunities for contact with financial service professionals and financial planning firms. At our biweekly meetings, we host speakers from a wide variety of backgrounds in financial planning, learning about their careers and how they got to where they are today. Through our organization, students are able to network with these industry professionals, attend panel discussions and learn about new job and internship opportunities. Find us on LinkedIn and Instagram to get informed about meetings!', 'fpacsuf', 'Active', '{"Honor Society","Special Interest","Career Planning","College of Communications","College of Education","College of Engineering and Computer Science","College of Health and Human Development","College of Humanities & Social Sciences","College of Natural Science and Mathematics","College of Business and Economics","Social"}', '{"business","career"}'),
  ('135401', 'Flying Samaritans', 'Flying Samaritans at CSUF is a sub-chapter of the larger Palomar Chapter of the Flying Samaritans organization that intends to aid in the provision of free medical and vision care to the citizens of Mexico who lack health care.', 'Our Mission Flying Samaritans at CSUF is a sub-chapter of the larger Palomar Chapter of the Flying Samaritans organization that intends to aid in the provision of free medical care to the citizens of Mexico who lack health care. We also present an opportunity for pre-health students, social sciences students, and Spanish translators to gain international volunteer experience. How to Become a Member Simply click the Join Us! and fill your information on the form. Please use a valid email address that you use regularly as this is how we keep you updated. Once you fill out the form, you will automatically receive our emails on how to sign up for clinics, how to pay your fees, our general meetings, and more! In order to be considered an active member you will need to attend, at the very least, two general meetings and two clinic trips per year. Also be sure to visit Our Website! How to Go to Clinics You will receive an email at the end of the month to sign up for the next month''s clinic. For example, sign ups for March''s clinic will go out at the end of February. There are several factors deciding who is able to go. Some of the factors include how many providers (i.e. doctors, nurses, EMTs, etc.) are going, how many drivers we have, whether or not you have attended meetings or other events, and more. There is no favoritism and is not on a first come first serve basis. For more information please email us at flyingsamselhongo@gmail.com. Fees In order to become a member there are a few fees. Membership Renewal (Annual membership): $30 Regular Membership: $40 Clinic Trip: $30 Once you join, you will receive emails on how you can pay those fees. If you want to be a driver and are selected, you will be reimbursed for gas (provided you have your receipts) and refunded the $25 fee. The fees are used for car insurance, gas reimbursement, medicine, and items that are needed for the clinic.', 'flyingsams', 'Active', '{"Service","Special Interest","Career Planning","College of Health and Human Development","College of Natural Science and Mathematics","Health & Wellness","Social","Sustainability"}', '{"career","health-wellness","service","social"}'),
  ('135468', 'French Club', 'The purpose of this organization is to promote learning, community, and improved understanding and performance of: French language, French culture, and the CSUF French program(s).', 'The purpose of this organization is to promote learning, community, and improved understanding and performance of: French language, French culture, and the CSUF French program(s). We also seek to provide opportunities for association, interaction, and learning from fellow students, faculty, administration, and guest speakers at CSU Fullerton. As well as to promote practices involving intercultural communication, friendship, and other forms of enrichment.', 'frenchclub', 'Active', '{"Political/Social Action","Special Interest","Recreation","Career Planning","College of Communications","College of Humanities & Social Sciences","Music"}', '{"career","cultural","music","political-social-action","recreation"}'),
  ('382853', 'Full Out', 'A dance club that offers free classes twice a week to all experience levels. The club is student run and driven offering opportunities to teach, choreograph, and perform. Full Out will be a safe place for students and an all inclusive dance community.', 'The club does two styles of dance with Hip-hop and Jazz. Both classes are from 7-9pm. No prior dance experience is required, we encourage all levels to come join. Classes are free and members are welcome to go to both or just one if they choose. Every year ends with Full Out Showcase, where we put on an optional show for friends and family to display all of our work throughout the year. It is a fun and supportive club where you can make friends and build community through dance.', 'fullout', 'Active', '{"Special Interest","College of Health and Human Development","Dance","Social"}', '{"dance","social"}'),
  ('132739', 'Fullerton Christian Students', 'Fullerton Christian Students is an organization for anyone interested in knowing about the Christian faith. According to the exhortation in 1 Cor 14:26 all believers have a portion of Christ and we encourage everyone to share their portion of', '1 Corinthians 14:26, "What then brothers? Whenever you come together, each one has a psalm, has a teaching, has a revelation, has a tongue, has an interpretation. Let all things be done for building up." We are a group of Christians that endeavor to encourage one another in our pursuit of Christ. We have weekly Bible studies on campus and two weekly meetings off campus where we study the Bible together, sing, and enjoy the Lord. We are non-denominational and welcome students to come and grow in their Christian faith with us. Want to connect with us? Come find us in front of the Humanities building every Tuesday from 12:30-1:30! Or reach out to us via our Linktree!', 'fullertoncs', 'Active', '{"Faith"}', '{"faith"}'),
  ('297233', 'Fullerton Fashion Association', 'Fullerton Fashion Association is a collective of like-minded students driven by a passion for fashion. Established in 2019, we provide an outlet for creatives who seek to create a community, learn, showcase, and connect in the field of fashion.', 'Fullerton Fashion Association is a student-run organization that provides a space for Titans to discuss the world of fashion. In Fall 2019, members of our student body noticed a lack of representation for students interested in expressing themselves through clothing. Our club aims to create a community where these students can connect with each other and establish an identity on campus. Our goals include building relationships, promoting sustainability, and hosting a platform for creation, education, and collaboration. FFA is an inclusive organization, welcoming diversity in all aspects such as gender, sexuality, ethnicity, etc. We believe that fashion is an interactive art form that provides students from all backgrounds an outlet for individuality and self expression. We hope that at FFA, you will learn more about fashion, design, and culture, as well as a new appreciation for an ever-growing field.', 'ffa', 'Active', '{"Special Interest","Recreation","LGBTQ+","Social"}', '{"lgbtq","recreation","social"}'),
  ('136285', 'Fullerton Foam Fighters Club', 'This club designed to introduce students to the sport of foam fighting. We simulate a medieval style combat through the use of foam weapons. This organization seeks to encourage the personal growth of students through aerobic and team-building exercises.', 'Fullerton Foam Fighters is a club designed to introduce students to the sport of foam fighting. We simulate medieval-style combat through the use of foam-padded weapons. This organization seeks to encourage the personal growth of students through exercise and group team building while providing a safe and encouraging environment to do so. All levels of experience are welcome! Whether you are a seasoned fighter or a novice, we welcome everyone who shares the love of combat! - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - Join our discord by copying this link or clicking the globe down below!', 'fullertonfoamfighters', 'Active', '{"Special Interest","Recreation"}', '{"recreation","sport"}'),
  ('138103', 'Fullerton Motor Group', 'Fullerton Motor Group is a place for car enthusiasts, advocates, and people with general interests in automotive technologies to discuss, educate, and help others with automotive interests.', 'Fullerton Motor Group (FMG) is CSUF''s premier auto enthusiast club! We are a social-recreational and educational club dedicated to providing a platform for all vehicle enthusiasts to discuss with others all things car-related. We enable car people to express their passions at weekly events/group drives and a lively discord server, while promoting the proper education of vehicle maintenance, safety, and driving techniques. FMG strives to make a welcoming community for all auto enthusiast students at CSUF. ------------------------------------------------------- Join our community at: Discord:', 'fullertonmotorgroup', 'Active', '{"Special Interest","Sport","Recreation","Outdoors","Social","Technology"}', '{"outdoors","recreation","social","sport","technology"}'),
  ('138235', 'FullerTones', 'We are an A Cappella group on campus. We love to sing, perform, and share a love for music.', 'The purpose of this organization is to provide CSUF students the opportunity to sing within a well-rehearsed group of fellow A Cappella lovers for fun. This organization also provides the chance to work with others and build teamwork skills. This group is Audition Based. Meetings/Rehearsals are on Tuesdays and Thursdays from 4 to 6:30 PM.', 'fullertones', 'Active', '{"Special Interest","Music"}', '{"music"}'),
  ('136286', 'Funny People Society: Improv and Comedy Club', 'If you wanna learn and perform improv on a team of composed of hilarious and kind people, then come on out and give it a shot!', 'The Funny People Society is a club that provides a place to learn to be spontaneous, quick-witted, and entertaining. We are the improv comedy team at CSUF and are always looking for new members! If you like shows such as Whose Line is it Anyway? Then this is the club for you! We have weekly meetings and monthly performances as well as outside performances with professional improv organizations! Come out to our meetings on Tuesdays at 2:30 pm - held in the Titan Theater in the TSU!', 'fpscomedy', 'Active', '{"Special Interest","Recreation"}', '{"recreation"}'),
  ('425202', 'Future Upcoming Credential Theatre Teachers', 'The student organization Future Upcoming Theatre Teachers is dedicated to supporting individuals currently enrolled in the theatre teaching credential program while also encouraging undergraduate students to pursue careers in theatre education.', 'The student organization Future Upcoming Theatre Teachers is dedicated to supporting individuals currently enrolled in the theatre teaching credential program while also encouraging undergraduate students to pursue careers as credentialed theatre educators. The organization hosts monthly meetings in which credential candidates collaborate by sharing lesson plans, instructional strategies, and classroom activities, while also providing one another with meaningful emotional and professional support as they navigate the demands of the program. In addition, the organization seeks to establish a scholarship program to assist students who aspire to enter the credential program but face financial challenges during the intensive student teaching period. The group also plans to facilitate writing workshops designed to support credential candidates in completing their Teacher Performance Assessments (TPAs) and to assist undergraduate students with application and personal statement writing', 'futureupcomingtt', 'Active', '{"Career Planning","College of Education","College of the Arts"}', '{"arts","career"}'),
  ('132398', 'Gamma Iota Sigma', 'Gamma Iota Sigma (GIS) is the international fraternity for Insurance, Risk Management, and Actuarial Science. We work to connect students to prospective employers through connections with professionals in the industry.', 'Gamma Iota Sigma is the international fraternity for Insurance, Risk Management, and Actuarial Science. We work to provide students with resources and guidance that will benefit their future careers in the insurance industry. - GIS is also deeply connected with the School of Risk Management Insurance and the Insurance Department at CSUF, helping those interested find their path to internships and employment. - If you want to become a member, please check out our socials and feel free to contact us through there!', 'csufgis', 'Active', '{"Fraternity & Sorority","College of Natural Science and Mathematics","College of Business and Economics"}', '{"career","greek-life"}'),
  ('135364', 'Gamma Phi Beta', 'Gamma Phi Beta is an International Sorority dedicated to inspiring the highest type of womanhood. Gamma Phi Beta was founded in 1874 and recognized for being the first woman''s organization to coin the word "sorority".', 'Gamma Phi Beta is an International Sorority dedicated to inspiring the highest type of womanhood. Gamma Phi Beta was founded in 1874 and recognized for being the first woman''s organization to coin the word "sorority". Joining Gamma Phi Beta means making life long friends and connections. Gamma Phi Beta gives members the chance for individual growth through academic excellence, leadership development, social enrichment, and philanthropic involvement that will take its members wherever they want to go with their life. The philanthropic organization that Gamma phi Beta supports is Girls on the Run. This organization empowers young girls to better themselves and always them to acknowledge they can do anything they set their mind to through activities, exercise, and interactive workshops.', 'gammaphibeta', 'Active', '{"Fraternity & Sorority","Social"}', '{"greek-life","social"}'),
  ('415278', 'Gensei Ryu USA Karate', 'We are a non-profit karate organization. We have dedicated our time to being there for the community by providing low cost classes and teaching martial arts to whoever is interested. We are extending our organization to do the same and more at CSUF.', '', 'gensei_ryu_usa_karate', 'Active', '{"Special Interest","Sport","Recreation","Health & Wellness","Social"}', '{"health-wellness","recreation","social","sport"}'),
  ('135038', 'Geography Club of CSUF', 'The Geography Club of CSUF is an organization of students who share interests in humanity''s relations with the natural world, our built environment and cultures. As a club we facilitate activities exploring our natural, urban and cultural landscapes.', 'Welcome to Geography Club of CSUF! Whether you like outdoor activities, helping the environment, social networking, or just hanging out with friends, you''ll fit right in with other members. There is no need to be a Geography major to join the club, and there are no fees! Join our discord account at: The Geography Club of CSUF Discord is a place where alumni, students, and professors can all keep in touch. There are different channels such as the lounge, geography adventures, alumni advice, jobs/internships, maps/posters, events, and a student only section. Please officially join the club through Titan Link. �Where you can find us� Social Media: - Geography Club of CSUF Facebook - Geography Club of CSUF Instagram - Geography Club of CSUF Discord On-Campus: We are located on the 4th floor of the Humanities building in room 422-H. There you will find a few couches, snack wall, conference table, and at least a few of our members to chat with. Come Join the Geography Club of CSUF. Please officially join the club through Titan Link or google form', 'geographyclubofcsuf', 'Active', '{"Special Interest","Recreation","College of Humanities & Social Sciences","Outdoors","Social","Sustainability"}', '{"cultural","outdoors","recreation","social"}'),
  ('137928', 'Geology Club', 'Geology Club is an organization where geology and non geology majors come together to learn and share information about the world around us from a geological perspective. Activities include meetings, social events, fundraisers, and volunteering.', 'The purpose of this organization is to provide an outlet for college students interested in geology and earth sciences to learn about and engage in the field through various activities promoting geology and earth science in a professional manner that elevates the ideals and purposes of the department.', 'geologyclub', 'Active', '{"Special Interest","Recreation","College of Humanities & Social Sciences","College of Natural Science and Mathematics","Outdoors","Social"}', '{"outdoors","recreation","service","social"}'),
  ('365594', 'Girl Gains CSUF', 'We promote and encourage female weightlifting while empowering women to feel strong and beautiful in a judgment-free community. We provide resources and community for women of all backgrounds and fitness levels.', 'We promote and encourage female weightlifting while empowering women to feel strong and beautiful in a judgment-free community. We provide resources, knowledge, and community for women of all backgrounds and fitness levels. We are open to all students who want to improve themselves in the Gym, and out. We promote total health and wellness and are against diet culture. If you are interested in being a part of an accepting and positive gym community, Girl Gains at CSUF is for you! Happy lifting💪', 'girlgainscsuf', 'Active', '{"Special Interest","Health & Wellness","Social"}', '{"health-wellness","social"}'),
  ('383232', 'GITM Running Club', 'GITM Running Club is a student-run organization with the goals of creating a community centered around running, training, and forming lasting bonds.', 'GITM Running Club is designed to provide a space for everyone to join regardless of experience in running. This is a space to build bonds and strengthen them while we strengthen ourselves in what may be a new sport to some and recreation for others. Together we will be meeting consistently to begin and/or continue our running journey and work to challenge ourselves with the end goal of running half marathons, marathons together.', 'titanrunclub', 'Active', '{"Recreation","Outdoors"}', '{"outdoors","recreation","sport"}'),
  ('135859', 'Glass Club of CSUF', 'The Glass and Metal Club of CSUF promotes education of awareness of glass art by sponsoring guest lectures and demonstrations by qualified glass artists and historians. The club also disseminates information promotion.', 'The purposes of the Glass Club of CSUF are to promote education concerning glass art by sponsoring guest lectures and slide presentations by qualified glass artists, historians, and visionaries; to promote Glass arts, by disseminating information, promoting student exhibitions and Fund Raising Glass Sales, participating in campus outreach programs, mentoring beginning Glass students and community involvement. Weekly Meetings - TBA - Hotshop VA-B130', 'glassclubofcsuf', 'Active', '{"Cultural","Special Interest","Recreation","Career Planning","College of Education","College of the Arts"}', '{"arts","career","cultural","recreation"}'),
  ('429512', 'Global Medical Brigades at CSUF', 'Global Medical Brigades at CSUF raises funds to support annual medical mission trips, allowing students to volunteer in underserved communities, shadow local physicians, assist with pharmacy operations, and lead health education workshops globally.', 'Global Medical Brigades at CSUF is a student‑led chapter committed to advancing access to healthcare and supporting sustainable healthcare initiatives in underserved communities worldwide. As part of the international Global Brigades network, our chapter empowers pre‑health and globally minded students to engage in ethical, community‑based global health work through education, fundraising, and hands‑on service. Throughout the academic year, members participate in community service, training, professional development, and fundraising efforts that directly support an annual 7–9 day medical mission trip. During these Brigades, students volunteer in communities with limited access to healthcare, working alongside local physicians and Global Brigades staff to support mobile medical clinics. Students gain meaningful clinical exposure by shadowing licensed providers, assisting with pharmacy operations, conducting triage support, and leading culturally informed public health education workshops. Our chapter has the opportunity to serve in partner countries such as Honduras, Guatemala, Panama, Ghana, Greece, and Belize. Each Brigade focuses on strengthening preventative and primary care efforts while contributing to long‑term, sustainable health solutions developed in collaboration with local communities. Global Medical Brigades at CSUF welcomes students from all majors—especially those pursuing pre‑health pathways such as medicine, PA, nursing, public health, and other health professions, who are passionate about global health, cultural humility, and community service. Through our programs, members develop leadership skills, clinical insight, and a deeper understanding of global health systems while contributing to meaningful, ethical, and sustainable change in the world.', 'gmbcsuf', 'Active', '{"Political/Social Action","Special Interest","Career Planning","College of Health and Human Development","College of Humanities & Social Sciences","College of Natural Science and Mathematics","Health & Wellness","Social","Sustainability"}', '{"health-wellness","service"}'),
  ('415486', 'Global Medical Missions Alliance', 'Our focus is to awaken and mobilize Christ-passionate healthcare workers to join in God’s Kingdom work, and to network with others who are already in the mission fields.', 'G lobal is our destination. M edical M ission is our DNA A lliance is our strategy.', 'gmma', 'Active', '{"Faith","College of Health and Human Development","College of Natural Science and Mathematics","Health & Wellness"}', '{"faith","health-wellness"}'),
  ('224783', 'Good Soil Christian Fellowship', 'The Good Soil is a Christian club serving Chinese-speaking students at CSUF. Good Soil welcomes any believers and non-believers to join us for lively Bible study sections and home-style Chinese food. We would love to have you in our spiritual family.', '', 'goodsoil', 'Active', '{"Faith"}', '{"faith"}'),
  ('132463', 'Graphic Design Club', 'GDC gives students the opportunity to advance design as a professional craft, strategic advance, and vital cultural force. This group also encourages designers to enhance their professional development while providing powerful tools and resources to all.', 'GDC gives students the opportunity to advance design as a professional craft, strategic advance, and vital cultural force. This group also encourages designers to enhance their professional development while providing powerful tools and resources to all. Please join us on Discord (CSUF Graphic Design Club) to stay up to date, interact, and get involved!', 'graphicdesign', 'Active', '{"Special Interest","College of the Arts"}', '{"arts","career","cultural"}'),
  ('349157', 'Grupo de Teatro en Español', 'The Grupo de Teatro en Español is a student theater organization at CSUF that allows students to share their stories through the performing arts. Our goal is to promote cultural and social justice awareness. All are welcome to join our theater familia!', 'Grupo de Teatro en Español is a student theater organization whose mission is to share the stories, struggles, and experiences of the Latino community through theatrical performance. We strive to make students confident in sharing their stories and exploring their identities while creating a safe space where students can heal and build community. We look forward to having you join us! We meet on Wednesdays from 5:00-6:30pm. Please follow our instagram for meeting location updates!', 'www-instagram-com-grupodeteatrodecsuf', 'Active', '{"Cultural","Political/Social Action","Special Interest","College of Humanities & Social Sciences","Social"}', '{"arts","cultural","political-social-action","social"}'),
  ('132780', 'Health & Human Development Inter-Club Council', 'Consisting of various student clubs and organizations within the College of Health and Human Development, the Health and Human Development Inter-Club Council aims to promote the continual success of all college clubs and organizations.', 'The Health and Human Development Inter-Club Council aims to facilitate greater and improved degrees of communication and cooperation between the student clubs and organizations within the College of Health and Human Development. HHD-ICC will strive to foster and promote school unity among the student body within the College of Health and Human Development, as well as facilitate and aid the continual success of all college clubs and organizations. Council Meetings : Thursdays at 11:30AM-12:30PM in KHS 193 To register into the HHD ICC as an organization or Member at Large, please fill out the registration form provided in this link: HHD New Club Registration Form HHD New Member at Large Form To re-register into the HHD ICC as an organization, please fill out this registration form provided in this link: HHD Re-Registration Form If you have any questions, please email hhdicc.chair.csuf@gmail.com. American Lung Cancer Screening Initiative Best Buddies Child and Adolescent Studies Student Association (CASSA) Chi Sigma Iota Delta Epsilon Mu Eta Sigma Gamma Full Out Honors Student Advisory Council (HSAC) Human Services Student Association Kinesiology Student Association Latino Medical Student Association Master of Social Work Association Nursing Student Association Physician Assistants Coming Together (PACT) Pre-Occupational Therapy Club Pre-Physical Therapy Club Public Health Student Association', 'hhdicc', 'Active', '{"Umbrella (Council)","College of Health and Human Development"}', '{"health-wellness","leadership"}'),
  ('414180', 'Her Campus', 'Created by college students, for college students, Her Campus Chapters serve their campuses a fresh and unique experience through their own localized editorial content, social media channels, events, and more.', 'Her Campus is your ultimate destination for navigating the unique experiences that come with this transformative stage in life, whether it’s curating the trendiest dorm on campus, landing your dream internship, or prioritizing your mental health while balancing a crazy packed schedule. We’re more than just a website — Her Campus is a community that uplifts, informs, and connects college women on topics like pop culture, wellness, style, politics, health, and more. Whether you’re aspiring to be a trailblazing journalist, a corporate leader, or a change-maker in your community, Her Campus will help you get there Her Campus serves CSUF a fresh and unique experience through its own localized editorial content, social media channels, events, and more. Join us for fun bonding events like Felt Flag making, bag charms and more. We host an event a month, sometimes more. With opportunities to post on our blog whenever you want. Email or dm us on Instagram for more information and how to join!', 'hercampus', 'Active', '{"Special Interest","Social"}', '{"social"}'),
  ('134511', 'Hermanas Unidas', 'Hermanas Unidas de CSUF was established in December 2003. We are a nonprofit organization that enocurages latinas within higher education to build community, leadership, and thrive in academics together.', 'We are a statewide incorporated organization that runs from Humboldt to San Diego. We are a large support system and resource for individuals in the higher education. We provide this opportunity to our members by consisting of three pillars, which include community service, academics and social networking. HaU de CSUF will create empowering and welcoming spaces by encouraging others to be their true selves, promoting siblinghood, and being understanding of everyone’s situation to obtain self growth, self esteem, and a strong support system. Weekly Meetings: Every Wednesdays 6:30 pm - 8:00 pm in the TSU', 'hermanasunidas', 'Active', '{"Cultural","Service","Social"}', '{"cultural","leadership","service","social"}'),
  ('136274', 'Higher Education Leadership Organization', 'The Higher Education Leadership Organization (HELO) provides supplemental learning, development, and community to Master of Science in Higher Education (MSHE) students through mentorship, workshops, socials, alumni events, and more.', 'The Higher Education Leadership Organization (HELO) is the student professional association of the M.S. in Higher Education (MSHE) program at Cal State Fullerton. HELO provides activities to support student learning and development including social and cultural events. Through HELO, students spend time with each other socially, learn with each other outside of the classroom, and participate in professional development and networking activities. Resources for Undergraduates Interested In Higher Education/Student Affairs: -Western Regional Careers in Student Affairs Day -National Association of Student Personnel Administrators ( NASPA) -American College Personnel Association ( ACPA) -CSUF NASPA Undergraduate Fellows Program Awards/Honors: Alumni Engagement Award (2021) | Tuffy Awards Advisor of the Year - Dr . Gutierrez Keeton (2022) | Tuffy Awards Outstanding Program in Member Development (2022) | Tuffy Awards Outstanding Program in Academia - HELO Conference 2022 (2022) | Tuffy Awards President of the Year - Albin Lee (2022) | Tuffy Awards Graphic & Design Competition Winner (2022) | Tuffy Awards', 'helo', 'Active', '{"Special Interest","College of Education"}', '{"leadership","mentorship"}'),
  ('382510', 'Hindu YUVA', 'The purpose of this organization is to bring together both Hindu and non-Hindu students to raise awareness about what Hinduism is.', 'The mission of The CSUF Hindu YUVA organization is to bring together both Hindu and non-Hindu students to raise awareness about what Hinduism is. As one of the largest and oldest religions in the world, we believe it is necessary that there be an organization on campus to represent the interests of the Hindu community present here. We hope to create a comfortable atmosphere where students can come and celebrate the Hindu culture. We hope to achieve these goals by having team-building games, yoga and meditation, lively and exciting debates, and presentations at our weekly meetings. All in all, we want to build a small Hindu community within CSUF so that students can come and discover a home away from home.', 'hinduyuva', 'Active', '{"Cultural","Faith","Social"}', '{"cultural","faith","social"}'),
  ('135183', 'Honors Student Advisory Council', 'The purpose of HSAC is to create a strong community between honors students and faculty by encouraging achievement, extracurricular involvement, and student leadership and enhance the reputation of this body at CSUF and within the community at large.', 'The purpose of HSAC is to create a strong community between honors students and faculty by encouraging achievement, extracurricular involvement, and student leadership and enhance the reputation of this body at CSUF and within the community at large. In addition, HSAC will strive to provide support, services, and social programs for the development of all honors students to reach their full potential .', 'hsac', 'Active', '{"Umbrella (Council)","Honor Society","Service","Special Interest","Career Planning","College of Communications","College of Education","College of Engineering and Computer Science","College of Health and Human Development","College of Humanities & Social Sciences","College of Natural Science and Mathematics","College of the Arts","College of Business and Economics","Outdoors","Social"}', '{"career","leadership"}'),
  ('365526', 'HopeFull', 'HopeFull''s mission is to raise funds to help families in need enjoy a nice meal at a restaurant. Family dinners are an integral part of family structure, and we aim to support those who are unable to access these meals.', 'HopeFull is dedicated to bringing families together, one meal at a time. Our mission is to raise funds that help families in need enjoy a meaningful meal at a restaurant, creating moments of connection, comfort, and community. Family meals are a vital part of a strong family structure, and we aim to support those who are unable to access them. Fundraising Events HopeFull hosts engaging fundraising events that bring students, faculty, and community members together around a shared cause while raising funds that directly support families. By participating in our events, the campus community plays an active role in creating positive change, turning collective effort into meaningful support for others. Volunteer Opportunities Volunteering with HopeFull is an opportunity for members to get involved through event planning, outreach, and hands-on service. Whether you are looking to develop leadership skills, give back to the community, or connect with like-minded peers, HopeFull offers meaningful ways to get involved and make an impact. By connecting students, community, and purpose, HopeFull works to create lasting impact, both on campus and in the lives of the families we serve. If you have any questions, please do not hesitate to contact us via email or social media. To become a free member, please sign up using the form below: HopeFull Member Interest Form (Spring 2026) Donate to support our mission: HopeFull Donation Page Stay connected: HopeFull - Instagram HopeFull - LinkedIn Join the conversation: HopeFull - Discord Learn more: Frequently Asked Questions (FAQ)', 'hopefull', 'Active', '{"Service","Recreation"}', '{"recreation","service"}'),
  ('432781', 'House of Sculpture', 'The House of Sculpture spreads awareness on 3D art forms, mixed media artwork, and sculpting as a career path; we provide in-house workshops and demos on a variety of assemblage mediums and safety when working with certain materials.', 'Our goal is to spread awareness on 3D art forms, mixed media artwork and sculpting as a career path. Encouraging young artists to go beyond the traditional forms of art. Offering and providing affordable in-house workshops and demos on mixed media art forms. Some of these workshops include, the art of inflatables, paper mâché versatility, fabrication of furniture, crafts and trinket building etc. Safety is our top priority in the industry, and educating students on proper personal protection equipment is key. We want to build a sense of community among 3d artist and will cover available resources for students who are interested in career paths in the fabrication industry.', 'houseofsculpture', 'Active', '{"College of the Arts"}', '{"arts","career"}'),
  ('132787', 'Human Services Student Association', 'HSSA’s goal is to learn how to interact with various populations as well as reach out to those in need. Through friendship, togetherness, communication, compassion, and empathy we strive to become better human beings.', 'The purpose of the Human Services Student Association (HSSA) is to promote professional and ethical development of its members by providing opportunities for interaction between our members, faculty, CSUF administration, and community providers. Also to encourage service to individuals, families, and the greater community while establishing friendships and to recognize high achievement in the pursuit of academic excellence. HSSA membership is open to all CSUF HUSR Major or Minor students who are interested in being a part of our family. Visit our website', 'csufhssa', 'Active', '{"Service","College of Health and Human Development"}', '{"service"}'),
  ('134624', 'Humanities & Social Sciences Inter-Club Council', 'H&SS ICC is responsible for disbursing funds from ASI to student led clubs within the College of Humanities & Social Sciences. We strive to promote Cal State Fullerton and its students within the national and international academic community.', 'Humanities & Social Sciences Inter-Club Council (H&SS ICC) is dedicated to the growth and support of graduate and undergraduate education, research, public service, and professional development. We are responsible for disbursing funds from ASI to student led clubs within the College of Humanities & Social Sciences. We meet weekly on Fridays at 11:00am to 1pm. Meetings are held hybrid style, the last Friday of every month will be held in person while the rest of the month will be held online. Want to Request Funding? Financial Training Workshop Presentation (Fall 2025) Fall 2025 Registered HSS Organizations: Acacia Group Alpha Phi Sigma (APS) CSUF Asian Pacific Islander South Asian Psychological Association (CAPISAPA) College Democrats of CSUF Geography Club of CSUF Latinx Student Psychological Association (LSPA) Psychology Association of Graduate Students of Color and Allies (PAGSOCA) Philosophy Club Psi Chi Honor Society Psychology Department Student Association (PDSA) The Teaching English to Speakers of Other Languages Club (TESOL)', 'hssicc', 'Active', '{"Umbrella (Council)","College of Humanities & Social Sciences"}', '{"leadership"}'),
  ('404006', 'Illustration and Sequential Arts Club', 'Illustration and Sequential Arts Club, or ISAC, is a community of artists and art lovers organizing to facilitate and celebrate the creation of many varieties of illustration, including but not limited to: printmaking, comics, zines, and more.', '', 'isac', 'Active', '{"Special Interest","College of the Arts"}', '{"arts"}'),
  ('132996', 'Indian Student Association', 'The Indian Student Association promotes a community among students to celebrate Indian culture. ISA primarily serves to provide students with community service projects, social/culture events, and education about the South Asian subcontinent.', 'The Indian Student Association at California State University, Fullerton is a non-profit student organization that provides a platform for helping students understand the cultures and the heritage of India, while branching out and networking with the Indian community of Southern California. We use many of the campus resources available to us to promote cultural awareness throughout the student body. With close to 200 members, the Indian Student Association is one of the largest cultural organizations at the CSUF campus. ISA is a great organization for students who want to become more involved on campus or learn about the Indian culture. Our organization also maintains a membership with the ASI Association for Inter-Cultural Awareness (AICA) and South Asian Student Union (SASU). AICA is an organization which was established to enhance the student experience at CSUF by raising awareness of and celebrating the multicultural student population of Cal State Fullerton. SASU is another organization which was established to help incorporate more events and help out the South Asian students. Throughout the academic year, the ISA executive board works vigorously to enhance the student experience on campus by bringing the Indian culture to them through workshops and events. By working in conjunction with AICA and other multi-ethnic groups on campus, ISA is able to host event such as our Ganesh Festival, Garba, Vaisakhi Festival and our annual Cultural Night. Through our own fundraising efforts, ISA hosts various self-sponsored events such as Diwali (Festival of Lights), Uttarayan (Festival of Kites), and Holi (Festival of Colors) in order to showcase the various aspects of the Indian culture.', 'csufisa', 'Active', '{"Cultural","Special Interest","Recreation","Social"}', '{"cultural","recreation","service","social"}'),
  ('432684', 'Industry Networking for Creative Students', 'I.N.C.S is a community based organization on campus for all creative students. We provide students with networking skills, career exploration workshops, and Visual Arts Faculty socials to get to know your professors a little better!', '', 'incs', 'Active', '{"Special Interest","Career Planning","College of the Arts","Social"}', '{"arts","career","social"}'),
  ('136283', 'Institute of Electrical and Electronics Engineers', 'We have devoted our energies towards bringing hands-on, practical experiences to engineering students throughout the campus, as well as creating opportunities for students to interact with industry professionals and more.', 'The Institute of Electrical and Electronics Engineers (IEEE) is the primary professional society of the electrical engineering profession. It has more than 330,000 members worldwide ; including 52,000 student members . It publishes more than 40 technical journals and sponsors or co-sponsors more than 1,000 scientific conferences and meetings around computer engineering, computer science, and related fields.', 'ieee', 'Active', '{"Umbrella (Council)","Service","Special Interest","Recreation","College of Engineering and Computer Science","Technology"}', '{"career","engineering","recreation","service","technology"}'),
  ('135175', 'Institute of Navigation', 'The Institute of Navigation is supported by the Electrical Engineering department in advancing the field of GPS and navigational technologies. In addition, this club focuses on engineering competitions that utilize navigation such as autonomous robotics.', 'The Institute of Navigation at California State University of Fullerton is established and organized as a scientific society, designed to advance the art and science of navigation through regional and national meetings, newsletters, and through its officers and working committees. The Institute of Navigation at California State University, Fullerton shall be a student branch of the Institute of Navigation Southern California Section.', 'ion', 'Active', '{"Special Interest","College of Engineering and Computer Science","Technology"}', '{"engineering","robotics","technology"}'),
  ('135321', 'Institute of Transportation Engineers', 'The Institute of Transportation Engineers of California State University, Fullerton promotes education and professional development of those interested in transportation engineering.', 'We''re Cal State Fullerton''s prominent transportation engineering organization. We educate our members on the subject, develop their leadership and professional skills, and connect them with professionals and companies. Through many activities, such as resume workshops and Lunch-and-Learns, our club aims to help you secure internships and full-time jobs, all while fostering a sense of belonging. Our club size is not huge, so you''ll get more attention and seize more opportunities that will later help you with your future career. Check us out and be part of something memorable.', 'ite', 'Active', '{"College of Engineering and Computer Science"}', '{"career","engineering"}'),
  ('138114', 'Inter-Tribal Student Council', 'ITSC''s purpose is to get involved with the Native American community by attending pow wows, and hosting meetings/workshops. We offer a place for Native and non-native students to share cultural experiences and create bonds through friendship.', 'Inter-Tribal Student Council''s goal is to assist Native Americans/Indigenous students and work towards higher education. We provide cultural awareness about and for Native American/Indigenous communities. During our meetings we discuss ways and means of taking appropriate actions to educate and bring awareness to the student body on issues that are relevant to our communities. The organization is open to all students at California State University, Fullerton, who have affinity or affiliation with Native Americans/Indigenous people. We encourage all to join who want to learn about our history and ask questions to cultivate a stronger and more positive learning environment. The Inter-Tribal Student Council promotes the success of the indigenous student body and celebrates the diverse cultures that compose of it.', 'itsc', 'Active', '{"Umbrella (Council)","Cultural","Political/Social Action","Recreation","Dance","Health & Wellness","Music","Social"}', '{"cultural","health-wellness","music","political-social-action","recreation","social"}'),
  ('134706', 'Interfraternity Council', 'The Interfraternity Council oversees, governs, and supports seven national fraternities at CSUF. IFC also serves as an advocate for fraternity life between ASI and administration. It is our the mission to be resource to all chapters and our members.', 'The Purpose of the Interfraternity Council shall be to govern, advise, and promote harmonious relations among and between member fraternities, the community, and the California State University governing bodies as a clearing house to facilitate the exchange of ideas and information among member fraternities and to encourage social, academic, service, and athletic interrelationships. We, the Interfraternity Council, exist to promote the shared interests and values of our member fraternities: leadership, service, brotherhood, and scholarship. We believe in Fraternity and that the shared values of Fraternity drive the IFC to create better communities, better chapters, and better men. We work to advance the academic mission of the host institution, to enable fraternal organizations to grow and thrive through collaboration and teamwork, to provide an outlet for self-governance and accountability, and to model and teach ethical leadership. In a spirit of mutual support and betterment, we, the men of the Interfraternity Council, pledge to elevate the Ritual and the values of the member organizations.', 'ifc', 'Active', '{"Umbrella (Council)","Fraternity & Sorority"}', '{"greek-life","leadership"}'),
  ('135049', 'InterVarsity Christian Fellowship', 'Our purpose is to establish and advance witnessing communities of students who follow Jesus as Savior and Lord: growing in love for God, God''s Word, God''s people of every ethnicity and culture and God''s purposes in the world.', 'Fullerton InterVarsity is a multi-ethnic multi-denominational Christian family of faith where everyone is welcome. Whether you are Catholic or Protestant, going to church your whole life or just checking out your faith -- you are welcome here! Our purpose is to establish and advance witnessing communities of students who follow Jesus as Savior and Lord: growing in love for God, God''s Word, God''s people of every ethnicity and culture and God''s purposes in the world. Fullerton InterVarsity is one of over 800 InterVarsity chapters at colleges and universities across the U.S.! To learn more about InterVarsity, visit us at www.fullertoniv.com or check out our national website at www.intervarsity.org . If you want to get more information about our small group Bible studies (dorms, apartments and on-campus), Thursday night large group meetings, prayer walks, service projects, and all of our other fun events, drop us a note at www.fullertoniv.com/im-new.html . Also, if you are in a fraternity or sorority (or plan on rushing) and want to hear about Greek InterVarsity, search Titan Link for our sister club!', 'fullertoniv', 'Active', '{"Faith","Service","Social"}', '{"faith","service","social"}'),
  ('132461', 'Iranian Student Association', 'Iranian Student Association (IranSA) is a cultural student organization at California State University, Fullerton with no affiliation with any political party or religious group.', 'The purpose of this organization is “(1) to raise awareness about the Iranian heritage and to exhibit its best aspects by holding cultural, social, and educational events; (2) to promote a sense of unity among members and to facilitate a positive and engaging interaction between the members and the rest of the campus; and (3) to have a vibrant role in the Iranian-American community of Orange County and the Greater Los Angeles Area by providing support for relevant programs through collaboration, volunteer service, and philanthropic activities.” The vision that this organization has been founded on is “to become the most-recognized Persian student organization in California and one of the best in the nation, and ultimately go beyond a student club and become a non-profit organization with chapters at different universities across California.”', 'iransa', 'Active', '{"Cultural"}', '{"cultural"}'),
  ('134738', 'Japanese Anime Club of CSUF', 'JAC is a place for anyone interested in Japanese Animation and its culture: Card Games, Video Games, Art, Music, Fashion, and more! Join us for fun games, prizes, events, and contests.', 'Founded in 2004, Japanese Anime Club is committed to bringing people together, making new friends, sharing our hobbies and interests in a safe and friendly environment. Weekly meetings are every Thursdays from 5:30PM to 7:30 PM! Can’t stay for the whole time? Don’t worry, you are welcome to come and go as you please! We love to watch anime, play games, and hang out together! We love to spread our interests and invite anybody, from anywhere! Need a way to find us, give us suggestions? Email us or DM us through our social media! csufanime@gmail.com • Linktree Discord • Twitch • Instagram • Facebook • Twitter', 'jac', 'Active', '{"Cultural","Special Interest","Recreation"}', '{"arts","cultural","music","recreation"}'),
  ('132500', 'Japanese Culture Club', 'Our purpose is to bring together a diverse group of students who share common interests in Japanese culture and intercultural exchange.', 'Founded in the Fall semester of 2010, the Japanese Culture Club of CSUF is a non-profit cultural student organization at California State University, Fullerton. Our purpose is to bring together a diverse group of students who share common interests in Japanese culture and intercultural exchange. We provide opportunities for students and others in the community to enjoy and learn more about Japanese culture and language through a variety of events. This is a place where everyone can experience fun and exciting adventures as we bridge the gaps of language and cultural barriers.', 'jcccsuf', 'Active', '{"Cultural","Special Interest"}', '{"cultural"}'),
  ('134772', 'Kinesiology Student Association', 'The Kinesiology Student Association (KSA) works to provide support and guidance to create a comfortable environment for students to exchange ideas, skills, and knowledge regarding all aspects of the field of Kinesiology.', 'The Kinesiology Student Association (KSA) works to provide support and guidance to create a comfortable environment for students to exchange ideas, skills, and knowledge regarding all aspects of the field of Kinesiology. KSA helps students share relevant academic experiences with one another, educates its members regarding entrance requirements to various Allied Health graduate programs, and provides networking opportunities through various guest speakers, collaborations with other health-related organizations, a chance to prospect in internships, and volunteering experiences.', 'ksa', 'Active', '{"Sport","College of Health and Human Development","Health & Wellness","Outdoors","Social"}', '{"health-wellness","outdoors","social","sport"}'),
  ('135050', 'Korean American Student Association', 'The Korean American Student Association will provide fun and exciting activities for students who are interested in learning and enjoying a Korean culture, also creating connections with people from CSUF and other schools involved in the SCKCSA.', 'CSUF KASA - Korean American Student Association The Korean American Student Association (KASA) at CSUF will providing a fun environment for students who are interested in learning about Korean American culture. We help to spread the awareness of our community through language, food, and history. We also creating connections with people from CSUF and other schools involved in the Southern California Korean College Students'' Association (SCKCSA) to build a new friendship and enjoy a fun events together.', 'kasa_csuf', 'Active', '{"Cultural","Social"}', '{"cultural","social"}'),
  ('181325', 'KPOP Club of CSUF', 'Kpop Club is a social club where students can bond over their love of Kpop! Whether you''ve liked Kpop for years or want to learn more about it, anyone is free to join at any time. Every week, we play games, cover different artists, and have fun!', 'Our meetings run on Thursdays from 5:30PM-7:00PM. If you have any questions, message us on Instagram or email! Kpop Club is a social club where students can bond over their love of Kpop! Whether you''ve liked Kpop for years or want to learn more about it, anyone is free to join at any time. Everyone that attends can participate in our activities! Activities include: Learning about Kpop culture Learning about new Kpop artists Watching music videos Watching K-dramas Fun ice breakers and games Collaborations with other clubs Fandom days ... and more!', 'k-popclub', 'Active', '{"Cultural","Special Interest","Social"}', '{"cultural","social"}'),
  ('137118', 'Lambda Pi Eta - Tau Epsilon Chapter', 'Lambda Pi Eta (LPH) is the National Communication Association''s official honor society at four-year colleges & universities. LPH recognizes, fosters & rewards outstanding scholastic achievement while stimulating interest in the communication discipline.', 'Lambda Pi Eta (LPH) is the National Communication Association''s official honor society at four-year colleges and universities. LPH recognizes, fosters & rewards outstanding scholastic achievement while stimulating interest in the communication discipline. Lambda Pi Eta represents what Aristotle described in Rhetoric as the three ingredients of persuasion: logos (logic), pathos (emotion), and ethos (character). THE SIX GOALS OF LAMBDA PI ETA 1. Recognize, foster, and reward outstanding scholastic achievement in Communication Studies 2. Stimulate interest in the field of Communication 3. Promote and encourage professional development among Communication majors 4. Provide an opportunity to discuss and exchange ideas in the field of Communication 5. Establish and maintain closer relationships between faculty and students 6. Explore options for graduate education in Communication Studies WHY JOIN? Membership in Lambda Pi Eta signifies distinguished achievement in the discipline of Communication. As NCA’s official honor society, LPH members are encouraged to attend the association’s Annual Convention each November, and to participate in the several LPH-sponsored sessions. The NCA Annual Convention offers tremendous opportunities for networking and presentation of original and exceptional student research. Most importantly, Lambda Pi Eta chapters are communities of students and faculty that organize a wide variety of philanthropic, academic, and social programs.', 'lambdapieta', 'Active', '{"Honor Society","Service","College of Communications","Social"}', '{"career","leadership","service","social"}'),
  ('135277', 'Lambda Theta Alpha Latin Sorority, Inc.', 'Lambda Theta Alpha is an academic organization whose main focus is Sisterhood, Empowering Women, Philanthropy, Community Service, Social Events, and Academics. Established back in 1975 on the East Coast, Lambda Theta Alpha came to CSUF in Spring 2002.', 'Lambda Theta Alpha is an academic organization whose main focus is Sisterhood, Empowering Women, Philanthropy, Community Service, Social Events, and Academics. Established back in 1975 on the East Coast, Lambda Theta Alpha came to CSUF in Spring 2002. Lambda Theta Alpha is the FIRST and LARGEST Latina Sorority in the nation, however we are Latina by tradition not by definition , therefore anyone can join.', 'lta', 'Active', '{"Cultural","Fraternity & Sorority","Political/Social Action","Service"}', '{"cultural","greek-life","political-social-action","service","social"}'),
  ('134892', 'Lambda Theta Phi Latin Fraternity Inc.', 'Lambda Theta Phi was founded December 1st, 1975. "Chivalry Above Self." Gamma Eta was founded May 18th 2003. The first Latino greek organization in the nation. The fraternity''s colors are brown and white.', 'Lambda Theta Phi is the first and largest Latino fraternity in the nation with over 150 chapters across the United States. The fraternity provides the Latino college student the opportunity to be part of a family with a mission: To cultivate a spirit of brotherhood, to value an education, to promote unity among all Latinos, to be proud of and cherish our heritage, to assert roles of leadership, to develop character, to practice chivalry, and to serve mankind. Lambda Theta Phi raises the social and cultural conscience of the Latin male college student. Since its start at Kean University in 1975, it has raised awareness for political involvement amongst Latinos through their national philanthropy. The purpose of thee Gamma Eta Chapter is to to promote and practice unity, respect among all cultures and creeds, to promote brotherhood, to maintain a high standard of learning, to develop character, and to practice chivalry while upholding dignity and self-identity. To assert positive leadership while serving as positive role models. We strive to serve as a source of support for students and professionals, while promoting Latinx unity. We also make students and professionals aware of their responsibilities to the community. Official Website Linktree', 'fullertonlambdas', 'Active', '{"Cultural","Fraternity & Sorority","Service","Special Interest"}', '{"cultural","greek-life","service","social"}'),
  ('132736', 'Latino Business Student Association', 'We, the Latino Business Student Association (LBSA), are more than a club, we are a familia. Our organization revolves around professional development, networking, and community service. Our goal is to help our members become community leaders.', 'The Latino Business Student Association ( LBSA ) is a student led organization at College of Business and Economics of CSUF where we work to create future business leaders, through professional and social networking. Whether you’re a student looking to get involved or a business professional looking for student leaders, you need an organization that helps you connect to the community so you can establish rapport at the grassroots level. Our goal is to develop diverse leaders who conscientiously care about the community and the triple bottom line. We are dedicated to networking, community involvement, leadership development, and diversity. Put simply: the community is not here for us, we are here for the community. We look forward to earning your friendship and serving you. If you have a question or want to join our familia, please email us at lbsacsuf@gmail.com.', 'lbsa', 'Active', '{"Cultural","Service","Career Planning","College of Business and Economics","Social"}', '{"business","career","cultural","leadership","service","social"}'),
  ('132939', 'Latino Journalists of CSUF', 'We are a California State University, Fullerton organization dedicated to promoting diversity in the news media. We prepare our members professionally through workshops, panels, and networking opportunities.', 'Latino Journalists of CSUF is a student chapter of the National Association of Hispanic Journalists (NAHJ). We focus on providing networking opportunities, mentoring programs, panels with professionals, and informational workshops that help our members excel in individual skills to thrive in the news media. 2026-2027 MEMBERSHIP We recommend registering for NAHJ. Click here to register. By registering for NAHJ, you get access to informative and beneficial conferences, conventions, scholarships, and professional networking opportunities with experienced media professionals.', 'latinojournalistsofcsuf', 'Active', '{"College of Communications"}', '{"career"}'),
  ('135850', 'Latino Medical Student Association Pre-medical Society', 'Founded to represent, support, educate and unify Latino(a) Pre-Medical Students. LMSA-PLUS is a network of pre-medical & pre-health students and organizations providing a space for pre-meds to come together and share our projects, ideas, and', 'Mission Statement : To provide a voice for underrepresented pre-medical students To actively promote recruitment and retention of Latino students at all levels To educate pre-medical students on Latino health issues To advocate for the rights of Latinos in health care To provide leadership opportunities for Latinos To promote volunteerism in the Latino community', 'lmsa-plus', 'Active', '{"Service","Special Interest","College of Health and Human Development","College of Natural Science and Mathematics"}', '{"health-wellness","service"}'),
  ('135665', 'Latinx Student Psychological Association', 'The Latinx Student Psychological Association (LSPA) strives to empower the Latinx community and provide graduate-level resources to all students across campus.', 'LSPA exists to advocate, educate, and empower the Latinx community to realize their full potential in the field of psychology. The objective of LSPA is to guide members to become qualified candidates for graduate school through the implementation of the five pillars: Academics, Leadership, Research Experience, Practical Experience, and Community involvement. Latinx Student Psychological Association is a new organization, founded in the spring of 2013 and was created to represent the Latinx community in the psychological field on the CSUF campus. Our goals include reaching out to the underrepresented Latinx community, academics, community service, networking, and socializing. We desire to advocate, educate, and empower the Latinx community to realize their full potential in the field of Psychology. Meetings are held weekly in the Titan Student Union. We help sponsor presentations, workshops, and discussions with various topics such as graduate programs, speakers, GRE prep work, showcasing resources available on campus, difficulties facing the Latinx community, and much more. We also offer leadership opportunities, networking opportunities, fundraisers, socials. Meetings and presentations pertain to current psychology major/minors, potential majors, those with interests in psychology, and to various other majors, as some topics vary in applicable fields. We actively encourage all majors/minors to participate in our meetings. Our elected positions offer great leadership experience to help build skills for post and current bachelor careers. Elections are held annually at the end of the spring semester. For more information or to join* please email us lspacsuf@gmail.com or follow us on Instagram @lspa.csuf! Membership is tracked through google account rather than TitanLink.', 'lspa', 'Active', '{"Cultural","Special Interest","College of Humanities & Social Sciences"}', '{"cultural"}'),
  ('372868', 'Latter-Day Saint Student Association at CSUF', 'This club promotes fellowship and learning through Christ, through the Church of Jesus Christ of Latter-Day Saints and Institute of Religion, commonly known as LDS or Mormon.', '', 'ldssacsuf', 'Active', '{"Faith"}', '{"faith"}'),
  ('224555', 'Lebanese Student Association', 'To promote the interests of the Lebanese students at California State University, Fullerton (CSUF). As well as to acquaint the California State University, Fullerton community with Lebanon and the Lebanese people, as well as to promote their culture.', 'To promote the interests of the Lebanese students at California State University, Fullerton (CSUF). As well as to acquaint the California State University, Fullerton community with Lebanon and the Lebanese people, as well as to promote their culture.', 'lebanesestudentassociation', 'Active', '{"Cultural","Special Interest"}', '{"cultural"}'),
  ('349484', 'LGBTQ+ Public Health Club', 'A medical focus on LGBTQ+ issues, advocacy, and community volunteer opportunities.', 'We provide a medical focus to LGBTQ+ issues, advocacy, and community volunteer opportunities to CSUF students and affiliates.', 'lgbtqphc', 'Active', '{"Service","Special Interest","College of Health and Human Development","College of Humanities & Social Sciences","Health & Wellness","LGBTQ+","Social"}', '{"health-wellness","lgbtq","political-social-action","service","social"}'),
  ('132890', 'Liberal Studies Student Association', 'The Liberal Studies Student Association is an organization that focuses on building a community for Liberal Studies students.', 'The Liberal Studies Student Association (LSSA) is a CSUF-recognized student organization that aims to connect Liberal Studies Majors through community, service, and Titan pride. LSSA is a place where students can network with each other and department professors. The association holds study groups, game nights, movie nights, and other social events to grow our community and get connected to the Liberal Studies and Humanities and Social Sciences student body.', 'lssa', 'Active', '{"College of Education","College of Humanities & Social Sciences"}', '{"social"}'),
  ('413431', 'LIFT-57 Marketing Agency', 'LIFT-57 is a student-run marketing agency, focused on providing a platform for students to apply marketing knowledge toward different projects in collaboration with local businesses, non-profits, and community organizations.', 'LIFT-57 is a student-run marketing agency at California State University, Fullerton. We provide a platform for students to apply their marketing knowledge by working on real projects with local businesses and nonprofit organizations across Orange County. Through collaboration, hands-on learning, and creative problem solving, students gain valuable experience in branding, strategy, digital marketing, content creation, and client communication. We prioritize developing talent over prior experience, helping students build their skills and confidence as they prepare for their careers.', 'lift-57', 'Active', '{"Service","Special Interest","Career Planning","College of Business and Economics"}', '{"business","career","service"}'),
  ('424638', 'Live Action at California State University, Fullerton', 'Live Action at CSUF is a chapter of the national, non-profit organization founded in 2003 by Lila Rose. We are dedicated to building a culture of life on campus and beyond through community service, outreach, and social efforts.', 'Live Action at CSUF is a chapter of the national, non-profit organization founded in 2003 by Lila Rose dedicated to ending abortion and building a culture of life. Through education, service, and outreach, this chapter will defend the inherent dignity of all human life, particularly the preborn, educate our peers in the horrors of the abortion industry, and mobilize the Titan community in pro-life efforts. We will make abortion unthinkable by sharing factual information about abortion, promoting resources for pregnant and parenting students, and fostering respectful dialogue on human rights, marriage, and the family as foundational to a flourishing society. We will participate in activities including meetings, educational events, service projects, conferences, activism, and advocacy consistent with Live Action’s values of truth, compassion, faith, and non-violence.', 'csuf-liveaction', 'Active', '{"Political/Social Action","Faith","Service","Special Interest","Health & Wellness"}', '{"faith","health-wellness","political-social-action","service"}'),
  ('135053', 'M.A.S Familia De California State University Fullerton', 'The purpose of this organization is to provide and reach out to the Chicano/Latino community. As well as to increase the graduation, and retention rate of Latinx students; through academic excellence, community service, and social networking.', 'Mas Familia de CSUF is an organization that focuses on increasing the retention, and graduation rates of Latinos at the university level. Through academic excellence, community service, and professional networking we create an opportunity for Latinos to give back to their community as well as prepare for their future career.', 'hermanosunidos', 'Active', '{"Cultural","Political/Social Action","Social"}', '{"career","cultural","political-social-action","service","social"}'),
  ('364767', 'Mariachi Titans', 'the purpose of this organization is to bring a cultural musical group to the CSUF campus. This organization will highlight the latinx/chicanx culture here at CSUF. To bring people together and foster a sense of community on the campus.', 'The purpose of this organization is to bring a cultural musical group to the CSUF campus. This organization will highlight the latinx/chicanx culture here at CSUF. To bring people together, foster a sense of community on the campus, and provide a joyous reminder of home for anyone and everyone in the community. We hope to empower the latinx/chicanx community with our music. Mariachi Titans are Cal State Fullerton’s first ever Mariachi Group. Mariachi titans hope to highlight and promote Latinx culture at CSUF. They love to share their passion for la cultura by enriching the local community with music. Marichi Titans are here to remind our peers at Cal State Fullerton that music is an excellent way to connect with others and increase awareness of different programs available at Hispanic Serving Institutions such as CSUF.', 'mariachititans', 'Active', '{"Cultural","Special Interest","College of Humanities & Social Sciences","College of the Arts","Dance","Music"}', '{"cultural","music"}'),
  ('424998', 'Marvel Rivals Club', 'Marvel Rivals Club brings CSUF students together through Marvel Rivals for social gameplay, strategy discussions, and optional student-run events. We welcome all skill levels and aim to build community while helping new players learn the game.', 'Our club, Marvel Rivals Club , is for CSUF students who love the game Marvel Rivals. We focus on bringing people together for social gameplay, talking strategy, and optional student-run events. Our goal is to build a community and get people involved, and we’d love to teach new players the game as well. While we do organize gameplay groups, participation is completely optional and open to everyone, no matter their', 'csufrivals', 'Active', '{"Special Interest","Social","Technology"}', '{"social","technology"}'),
  ('134512', 'Master of Social Work Association', 'MSWA aims to empower MSW students through community, peer support, and professional development.', 'MSWA is dedicated to empowering MSW students at CSUF by fostering a strong sense of community, peer support, and professional growth. Through a variety of events, programs, and opportunities, we create spaces for graduate students to connect, gain experience, and build meaningful networks. Members benefit from opportunities such as participating in our peer mentor program, serving as cohort representatives, and accessing a range of organizational resources. Grounded in values of kindness, empathy, compassion, advocacy, and mutual support, MSWA strives to ensure every student feels encouraged, connected, and empowered to thrive.', 'mswacsuf', 'Active', '{"Political/Social Action","Service","Special Interest","College of Health and Human Development","Health & Wellness","Social"}', '{"career","health-wellness","mentorship","political-social-action","service","social"}'),
  ('134810', 'Medieval Swordsmanship Club', 'We practice, teach, and raise awareness of Historical European Martial Arts (HEMA) and the historical context of these various traditions.', 'The Medieval Swordsmanship Club (also referred to as Kron, Fullerton) is a student organization dedicated to the study and practice of Historical European Martial Arts (HEMA). Using sources written during the Medieval and Renaissance time periods, the HEMA community pieces back together a martial art that has been unpracticed for ages. Our club has various European sword and weapon styles that we practice. We do so using blunted trainers which are weighted to simulate the balance of the historic weapons. Once members have gained an understanding of the proper techniques, they have the opportunity to spar and test their abilities with their peers. All sparring is done with technique, self-control, and proper safety equipment. Our primary area of study is the German longsword. It is from this tradition the club got its name, ''Kron'' which is a guard position that protects one''s head- or ''crown''. We welcome all who are interested! No experience or knowledge is necessary! First-time guests may practice at no cost at all! If you are interested in joining or wish to learn more about what we do, please email us at Kronfullerton@gmail.com for our discord link. Practices are every Wednesday from 7:00 pm to 9:00 pm on the lawn in front of the Student Recreation Center.', 'medievalswordsmanship', 'Active', '{"Cultural","Special Interest","Recreation"}', '{"cultural","recreation","sport"}'),
  ('135387', 'Men''s Club Soccer', 'The Men''s Soccer Club at CSUF is a great way for students to play soccer in a competitive environment while still having time for work and school. The team is part of the West Coast Soccer Association and plays against other local universities.', 'For inquiries, please contact us on Instagram: @csufmensclubsoccer', 'menssoccerclub', 'Active', '{"Sport"}', '{"recreation","sport"}'),
  ('135755', 'Men''s Club Volleyball', 'The purpose of this organization is to provide opportunities for male students to participate in a competitive sport of volleyball while interacting with other students of CSU Fullerton as well as other universities across the nation.', 'Men''s Club Volleyball at CSUF is a unique sports club that offers many exciting opportunities from out of state tournaments, to leadership roles. Being the only competitive mens volleyball community on campus, this club enables students to create lifelong friendships and compete in tournaments against other schools. Other expenses like jerseys and tournament fees are charged separately as incurred. Approximate total cost for both Fall and Spring Semester: $450*** [ESTIMATE] This estimate includes: -Membership for a year -Club T-shirts -Fees to play in tournaments -Custom personal jersey and Slunks -Club equipment Club dues are non-refundable. Meeting Location and Time: Monday/Wednesday from 7:00pm to 9:00pm in KHS 204. If you have any questions or concerns, please email csufmcvb@gmail.com or DM @csufmcvb on Instagram. Thank you for taking an interest in Men''s Club Volleyball. For Tryout information and updates follow us on IG @csufmcvb Additionally, fill out this interest form to be notified when we announce tryouts! (Link Below) FA25 MCVB Interest Form', 'csufmensclubvolleyball', 'Active', '{"Sport"}', '{"recreation","sport"}'),
  ('135898', 'Men''s Lacrosse', 'The Men''s Lacrosse club team provides students the opportunity to participate in all activities related to the sport of lacrosse. As a collegiate team representing CSUF, our goal is to promote teamwork and competition while striving for academic success.', 'The Men''s Lacrosse Club was established Fall 2008. We are student-ran and a member of the the Southwestern Lacrosse Conference (SLC) in the Men''s Collegiate Lacrosse Association (MCLA). To make a donation, see instructions below: 1. Click here for Donation Link! 2. Enter your gift amount 3. Click the "Comments/Make Multiple Gifts" dropdown menu 4. Type "Donate to Men''s Lacrosse at CSUF (#4214)" in the text box 5. Finish the rest of the forms!', 'menslacrosse', 'Active', '{"Sport","Recreation","Outdoors"}', '{"outdoors","recreation","sport"}'),
  ('137628', 'Men’s Rugby', 'This club sport was founded on campus in 1985 by a group of athletes to promote brotherhood, camaraderie, athleticism, and scholarship through the sport of rugby.', 'MEN''S RUGBY CLUB!! NO EXPERIENCE NEEDED!!! This club sport was founded on campus in 1985 by a group of athletes to promote brotherhood, camaraderie, athleticism, and scholarship through the sport of rugby. Please reach out to @csufmensrugby if you are interested in joining.', 'mensrugby', 'Active', '{"Sport","Recreation","Health & Wellness","Social"}', '{"health-wellness","recreation","social","sport"}'),
  ('132689', 'Mesa Cooperativa', 'Mesa Cooperativa is the voice of the Chicano/Latino students at Cal State Fullerton. We strive to unify our Chicanx/Latinx community through dialogue and collaboration while creating a conscious community.', 'MESA Cooperativa is an organization that brings together our Chicanx/Latinx student organizations here at CSUF. MESA was originally created to bring our student community together in unity on campus, and we hope to carry that on. Our cultural, social, and educational events create spaces where students can celebrate cultures and support one another to build a stronger presence at CSUF. Some of our major events are La Bienvenida, Chicanx/Latinx Heritage Month, Las Posadas, and Día de los Padres. With these events, we steer focus to growing community closer on campus. MESA is committed to uplifting the voices of its students and creating a supportive space where students feel seen, heard, and represented. For more information, reach out to any of our board members! Founded: MESA was founded in 1992 by Chicanx/Latinx students and faculty members interested in a support network for students on campus', 'mesacooperativa', 'Active', '{"Umbrella (Council)","Cultural","Political/Social Action"}', '{"cultural","leadership","political-social-action"}'),
  ('135855', 'Movimiento Estudiantil Chicanx de Aztlan', 'Movimiento Estudiantil Chicanx de Aztlán (M.E.Ch.A.) is a student organization that promotes higher education, culture, and history.', 'Movimiento Estudiantil Chicanx de Aztlán (M.E.Ch.A.) is a student organization that promotes culture, history, and encourages students to pursue higher education. M.E.Ch.A. was founded on the principles of self determination for the liberation of our members and respective communities. We believe that political involvement and education is the avenue for change in our society. This organization strongly reflects on it’s prominent identity as a student movement, and we acknowledge that monumental traction was gained during student organizing in the late 1960’s. To move forward with the work that must be done to elevate these communities, students are committed to returning to the communities that guided us and together resist against the influences that oppress us. M.E.Ch.A. continues to be an organization that seeks to open the doors of higher education for our communities and hold positions in power accountable for their roles within our communities and strive to reject imperialism, racism, sexism, and homophobia.', 'mechadecsuf', 'Active', '{"Cultural","Political/Social Action"}', '{"cultural","political-social-action"}'),
  ('423736', 'Moving Forward Community @ CSUF', 'To empower CSUF students through mental health education, peer support, and professional growth opportunities, advancing MFPI’s mission to #EndSuicide. We aim to foster wellness, cultural awareness, and leadership development for the campus community.', 'The purpose of this club is to provide Cal State University–Fullerton students with career development and personal growth opportunities that equip them to address mental health challenges both on campus and in their wider community. Powered by Moving Forward Psychological Institute, Inc. (MFPI) , the club will support students through workshops, events, mentorship, and internship preparation — all designed to help them thrive both inside and outside the classroom.', 'mfcsuf', 'Frozen', '{"Cultural","Service","Career Planning","College of Humanities & Social Sciences","Health & Wellness","Social"}', '{"career","cultural","health-wellness","leadership","mentorship","service","social"}'),
  ('133037', 'Multicultural Greek Council', 'Multicultural Greek Council (MGC) oversees 6 culturally-based fraternities and sororities on campus.', 'The purpose of the Multicultural Greek Council at California State University, Fullerton shall be to create and maintain higher standards of Fraternity and Sorority Life coming from a culturally unique and diverse perspective. We aim to build a community that promotes higher education, provide community services, and enhance student leadership. MGC’s Executive Board serves with the goal to be support system for member organizations, offering guidance and resources to help them thrive and uphold their individual missions. Our council consists of a total of six diverse organizations, three fraternities and three sororities. Active MGC Organizations at CSUF: Lambda Theta Phi Latin Fraternity, Inc. Lambda Theta Alpha Latin Sorority, Inc. Sigma Delta Alpha Fraternity, Inc. Sigma Lambda Beta International Fraternity, Inc Sigma Theta Psi Multicultural Sorority, Inc. Tau Theta Pi Sorority', 'mgc', 'Active', '{"Umbrella (Council)","Cultural","Fraternity & Sorority"}', '{"cultural","greek-life","leadership"}'),
  ('225366', 'Music Industry Club', 'MIC is an organization for students interested in all aspects of the music industry. We explore career pathways by inviting guest speakers and sharing job/internship opportunities. MIC holds panels and workshops to help students learn and network. Join!', 'MIC is an organization for students interested in any aspect of the music industry. As an organization, we invite industry professionals and hold bi-weekly panels. From there, students are able to network and learn from valuable resources. We also work to share job/internship opportunities (on LinkedIn, Discord, and more). Through collaboration and collective learning as a group, we aim to prepare students who are hoping to break into this unique and multi-faceted industry. MIC has many other resources in the works as well. For example, we hope to hold workshops that help students network and build their professional careers. We also create content (blog posts, TikToks, and other social media assets) to help students dive deeper into their dream jobs.', 'csufmic', 'Active', '{"College of Communications","College of the Arts","College of Business and Economics"}', '{"career","music"}'),
  ('135778', 'Muslim Student Association', 'Muslim Students is an organization that promotes religious, social and spiritual values. It is a community, a space where Muslim students can feel comfortable growing and engaging their campus in a focused manner. Everyone is welcome regardless of faith.', 'The purpose of the Muslim Student Association is to unify all Muslims across different ethnic backgrounds. We want to develop our members into spiritual and moral people. We will have general meetings, Chaplaincy, and other events every week. Do not hesitate to contact one of our board members if you have any questions. Follow our Instagram for updates: @msacsuf Email us at Csufullertonmsa@gmail.com "The universality of Islam is not uniformity, it is unity with diversity"', 'msa', 'Active', '{"Cultural","Faith","Social"}', '{"cultural","faith","social"}'),
  ('404012', 'Muslim Tech Collaborative', 'The Muslim Tech Collaborative (MTC) at CSUF is dedicated to building a vibrant professional and supportive community for Muslims in technology. Our mission is to showcase our values and talents by leveraging skills to drive impactful change.', 'The Muslim Tech Collaborative (MTC) at CSUF is committed to building a vibrant professional and spiritual community for Muslims in technology. Our mission is to showcase our values and talents by harnessing our skills to drive meaningful and impactful change in the world.', 'muslimtechcollaborative', 'Active', '{"Cultural","Faith","College of Engineering and Computer Science","College of Business and Economics"}', '{"cultural","faith","technology"}'),
  ('159164', 'National Association for Music Education', 'An organization that works towards professional development and advocacy in music. Our chapter at CSU Fullerton provides opportunities for future and current music educators to connect with professionals in the field and refine their skills.', 'The National Association for Music Education is a national organization that works towards providing educators from all across music with opportunities for professional development. We advocate for the necessity of music within our public schools taught by well-qualified teachers in the field. Our chapter here provides students within our school the chance to better their skills as educators with one another. We connect current and future teachers from all areas of music to learn from one another and create bonds that will be beneficial later in the field. Advocacy is a main goal of ours, giving back to our local community at large to benefit music students of all ages and backgrounds. We promote a safe environment for all members to share their experiences as educators and practice their craft with members who are kind and supportive.', 'nafme', 'Active', '{"Service","Special Interest","College of Education","College of the Arts","Music","Social"}', '{"career","music","political-social-action","service","social"}'),
  ('402720', 'National Marrow Donor Program', 'NMDP CSUF is an organization geared towards building the stem cell/bone marrow donor registry to help save the lives of blood cancer patients. Join us and learn how you can help save a life!', 'NMDP (National Marrow Donor Program), is an organization that helps blood cancer patients and their families. The goal of the organization is to find a stem cell/bone marrow match for the patients that can save their life and potentially cure them. The goal of NMDP at CSUF will be to help build the registry further and to raise money for leukemia patients, their families, and donors since NMDP covers all stem cell/bone marrow donation affiliated costs.', 'nmdpcsuf', 'Active', '{"Service","College of Health and Human Development","College of Natural Science and Mathematics","Social"}', '{"service","social"}'),
  ('404632', 'National Organization of Black Chemists and Chemical Engineers', 'The purpose of this student chapter shall be consistent with the objectives NOBCChE. The objectives of NOBCChE, as established in the Certificate of Incorporation, are: to further the application of chemistry, chemical engineering and', 'The purpose of this student chapter shall be consistent with the objectives NOBCChE. The objectives of NOBCChE, as established in the Certificate of Incorporation, are: to further the application of chemistry, chemical engineering and related fields', 'nobcche', 'Active', '{"Cultural","College of Natural Science and Mathematics"}', '{"cultural","engineering"}'),
  ('133035', 'National Society of Black Engineers; California State University, Fullerton Chapter', 'The National Society of Black Engineers is a non-profit student run organization. Our mission is to increase the number of culturally responsible black engineers who excel academically, succeed professionally, and positively impact the community.', 'The purpose of the National Society of Black Engineers (NSBE); California State University, Fullerton (CSUF) Chapter is to stimulate and develop student interest in engineering, strive to increase the number of students studying engineering at both the undergraduate and graduate levels; and to endeavor in the advancement of the ethnic minority engineer within the professional industry.', 'nsbecsuf', 'Active', '{"Cultural","College of Engineering and Computer Science"}', '{"cultural","engineering"}'),
  ('136129', 'National Student Speech Language and Hearing Association', 'The National Student Speech Language Hearing Association (NSSLHA) is a pre-professional organization for students interested in furthering their study of communication sciences and disorders and audiology.', 'CSUF NSSLHA is a GOLD accredited chapter and one of the largest local chapters in California. The National Student Speech Language Hearing Association (NSSLHA) is a pre-professional organization for students interested in furthering their study of communication sciences and disorders and audiology. NSSLHA membership is available to undergraduate, graduate, and doctoral students enrolled full or part time in a communication sciences program or related major. Cal State Fullerton’s local NSSLHA chapter strives to provide cutting edge opportunities for students to supplement their education through service events, conferences, panels, social gatherings and more. We are a GOLD accredited chapter which is the highest level of recognition given by the National Association. This level of achievement provides CSUF NSSLHA with several resources including scholarships, grants, career awareness workshops, and more. CSUF NSSLHA is committed to supporting students and building valuable partnerships in the community.', 'nsslha', 'Active', '{"College of Communications"}', '{"social"}'),
  ('132998', 'Natural Sciences and Mathematics Inter-Club Council', 'NSM-ICC is a student-lead council comprised of representatives from clubs in the College of Natural Sciences and Mathematics. Our goal is to help students make connections, form collaborations, and build a community within the college and across campus.', 'What is NSM-ICC? NSM-ICC is a student-led council comprised of representatives from clubs in the College of Natural Sciences and Mathematics. The goal of the inter-club council (ICC) is to help students make connections, form collaborations, and build community within the college and across campus. What do we do? We distribute funds for students to travel to conferences as both attendees and presenters. If you are a member of a club with an ICC representative and would like to apply for funding, contact your rep for further details. If you are not an active member of a club but are a current NSM student, you can still apply. NSM Fall 2026 Meetings Meetings will be held weekly on Wednesday from 12:00 - 1:00 pm. The first meeting of the semester will take place on Wednesday, September 2nd, at the MH 488 - NSM Student Success Center/zoom. NSM Club Funding! We also fund clubs to host events on campus for all CSUF students. Please get in touch with an NSM-ICC representative or send us an email for more information. NSM ICC 25-26 Rep Contact Form 2025 - 26 NSM Registered Clubs American Medical Student Association (AMSA) Flying Samaritans Physician Assistants Coming Together (PACT) Pre-Dental Society Society for Advancement of Chicanos/Hispanics and Native Americans in Sciences (SACNAS) Biology Graduate Student Club American Lung Cancer Screening Initiative (ALCSI) NOBCChe Applied Researchers of Biology To register into the NSM-ICC as an organization, please fill out the registration form provided in this link: NSM ICC REGISTRATION FORM To re-register into the NSM-ICC as an organization, please fill out the registration form provided in the following link: NSM ICC RE-REGISTRATION FORM Note: After submitting the registration form, organizations requesting to join the NSM ICC must attend an upcoming meeting and be voted in. Symposium Each spring, the NSM-ICC sponsors "NSM Week", a two or three-day celebration dedicated to recognizing the hard work of students in STEM programs. This week is most notable for the research symposium that showcases student research from CNSM and other colleges at CSUF. Poster presentations, research talks, and a keynote speaker* have highlighted past celebrations. *Past keynote speakers include Dr. Adam Summers, Bill Nye, the Mythbusters, and Bob Ballard. Funding Please fill out the required documents for funding and submit them to the Wufoo form. All required documents must be submitted at least TWO WEEKS BEFORE your event or travel date. Complete the 25-26 Allocation Form if your registered NSM organization wishes to present a funding request at an upcoming council meeting: Allocation Form 25-26 Complete the 25-26 Reimbursement Form to request reimbursement after being approved for council funding support. Note: This only happens once your packet and request have been approved. Reimbursement Request 25-26 Questions? E-mail us at officialnsmicc@gmail.com', 'nsmicc', 'Active', '{"Umbrella (Council)","College of Natural Science and Mathematics"}', '{"leadership"}'),
  ('136115', 'Nikkei Student Union', 'The purpose of this organization is to promote Japanese American culture and political awareness among the student body; as well as to organize social and community service activities.', 'The purpose of this organization is to promote Japanese American culture and political awareness among the student body; as well as to organize social and community service activities.', 'csufnikkei', 'Active', '{"Cultural","Social"}', '{"cultural","political-social-action","service","social"}'),
  ('429952', 'Nurses for Sexual and Reproductive Health', 'NSRH provides students with the education, tools, and resources necessary to become social-change agents within the healthcare system as it relates to sexual and reproductive justice.', '', 'nsrh', 'Active', '{"Political/Social Action","College of Health and Human Development","Health & Wellness","LGBTQ+"}', '{"health-wellness","lgbtq","political-social-action"}'),
  ('332203', 'Nursing Peer Tutoring', 'The purpose of this organization is to advance academic success in nursing courses through proven active learning strategies, peer-to-peer collaboration, and leadership development.', 'The purpose of this organization is to advance academic success in nursing courses through proven active learning strategies, peer-to-peer collaboration, and leadership development. To do this, students who excelled in nursing courses are welcome to apply as tutors and be an extra resource for fellow students. The group tutoring sessions are open to students in the courses and to pre-nursing students who would like an insight into nursing studies.', 'nursingpeertutoring', 'Active', '{"Service","College of Health and Human Development","Health & Wellness"}', '{"health-wellness","leadership","mentorship","service"}'),
  ('135663', 'Nursing Student Association', 'Nursing Students Association supports and encourages all levels of nursing students. NSA creates opportunities for members to meet and network in monthly meetings, social, fundraising, and outreach events, while acting as a positive resource for members.', 'Mission Statement The purpose of the Nursing Students'' Association (NSA) is to support and encourage all nursing students in completing their respective nursing programs. Our membership includes all levels of nursing ranging from pre-nursing, undergraduate, and graduate nursing students. We pride ourselves in being another resource for nursing students as nursing is a very difficult major. We are able to accomplish these goals by providing opportunities to connect and network with other students, in addition to creating avenues to participate in job fairs, social events, fundraising, outreach activities, and monthly meetings with guest speakers. Moreover, we also act as a resource for incoming nursing students and others interested in the nursing field. At the core, our goal is to help nursing students succeed while creating a community of compassionate healthcare providers. Are you a current or future nursing student at Cal State Fullerton, or are you interested in finding out about the nursing profession? If you are, then the Nursing Student Association (NSA) is for you! NSA was recently founded by Austin Nation, a RN-BSN student. We are a fairly new club on campus, but are affiliated and recognized by the National Student Nurses'' Association (NSNA) , the only recognized student nursing society! We encourage you to join us for meetings and events to give yourself a voice in this new formed club! As part of NSA you will be able to share your experiences with your fellow nursing students and receive help and encouragement. NSA is also about fun and giving back to the community as we try to plan volunteer and fundraising activities throughout the semester! We look forward to seeing you at our next meeting!', 'csufnsa', 'Active', '{"Service","Special Interest","College of Health and Human Development"}', '{"health-wellness","service"}'),
  ('136539', 'Offensive Security Society', 'To catch a criminal, you need to think like one. At OSS, we teach you the necessary skills to accomplish this over cyberspace to become an ethical hacker. Learn and network with CSUF Students brought together by Cybersecurity interest!', 'OSS offers an entry point into the field of offensive and defensive cybersecurity - a proactive and adversarial approach to protecting computer systems, networks, and individuals from attacks. At OSS, you will learn the basic real-world skills needed to succeed and become a cybersecurity professional. Some topics we cover throughout the school year in our weekly workshop meetings include Web Application penetration testing, Windows Active Directory attacks, lockpicking, Application Security, System Hardening, and various other topics. We regularly compete in regional and international competitions that expose us to realistic scenarios while providing a stepping stone into potential career paths. Other activities OSS participates in include vulnerability research, defensive security training, organizing guest speakers to discuss opportunities and research, and promoting student-led projects partnered with companies. Check out all our socials: RULES: 1 - Be nice and play nice. Be professional and respectful. 2 - CSUF Students, Alumni, and Staff only. 3 - Do not violate CSUF''s Academic Dishonesty Policy. 4 - Admins reserve the right to delete messages and links, and kick anyone for malicious behaviour. 5 - OSS is an educational organisation. OSS material is intended to be used for strictly educational purposes, and is not intended to cause harm, damage, or distress of any kind. This includes but is not limited to any actions such as malicious hacking of any computer systems or any actions that damage/misuse school property. 6 - Social engineering is allowed so long as it is non-harmful to any individual and computer involved. 7 - No NSFW content in any of our Discord (or any other) communication channels. Keep the profanity to a minimum. Inappropriate profiles and toxic spouting will not be tolerated. No spamming or DDoS-ing. Don''t post pirated content, links, or discuss pirating, religion, or politics. Direct Messages cannot be moderated. 8 - We are enforcing a zero-tolerance policy on any unprofessional or malicious behaviour at any OSS events, CSUF events, ECS events, etc. 9 - If there are any problems, contact an OSS Board Member . 10 - By joining OSS, you agree to subscribe to its ethical standards and regulations. Members found in violation of this can be disciplined with measures up to and including expulsion from the club and any legal consequences resulting from the member''s misconduct. Individuals who report an ethical or legal concern in good faith will never be subject to retaliation for reporting.', 'oss', 'Active', '{"Special Interest","College of Engineering and Computer Science","Technology"}', '{"cybersecurity","technology"}'),
  ('134482', 'Panhellenic Council (PHC)', 'The Panhellenic Council is the umbrella organization for CSUF''s six social sororities. These include: Alpha Chi Omega Alpha Delta Pi Delta Zeta Gamma Phi Beta Sigma Kappa Zeta Tau Alpha', 'The Panhellenic Council is the governing body for the six social sororities on campus. These sororities include Alpha Chi Omega, Alpha Delta Pi, Delta Zeta, Gamma Phi Beta, Sigma Kappa, and Zeta Tau Alpha.', 'panhellenic', 'Active', '{"Umbrella (Council)","Fraternity & Sorority"}', '{"leadership"}'),
  ('132785', 'Pencil Mileage Club', 'The Pencil Mileage Club is a group of animators, illustrators, and visual art students at CSUF looking to create, connect, and collaborate with one another.', 'We hold club meetings every Wednesday at 12PM, and we host events every Friday evening. The Pencil Mileage Club is a group of animators, illustrators, and visual art students at CSUF looking to create, connect, and collaborate with one another. Our community is passionate about the entertainment arts industry, and we help develop connections among the students through speaker events with industry professionals, life drawing sessions, group projects, and more. Our club is committed to keeping members informed and involved in local artistic events, and we encourage our members to follow their artistic passions to pursue careers in the art industry. Some fun activities we host for our members include monthly drawing challenges, game nights, cafe sketching, and more. The PMC is a place where students may forge meaningful connections, learn something new, and above all have fun.', 'pencilmileageclub', 'Active', '{"Special Interest","College of the Arts","Social"}', '{"arts","social"}'),
  ('136956', 'Phi Alpha Theta', 'Phi Alpha Theta is a national history honor society. CSUF''s Theta-Pi chapter, established in 1962, promotes academic excellence through research, publications, conference participation, visits to historical sites and museums, as well as social events.', 'We are Phi Alpha Theta, the university''s history honor society. We seek to encourage the study of history and to recognize excellence in the field. We accomplish this through research, publications, conference participations, and visits to historical sites and museums. Additionally, we seek to bring students and faculty together for scholarly and social exchanges in a range of venues, build career development skills, and explore careers with a history degree. We also sponsor history majors by reimbursing travel fees they have when traveling to conferences.', 'phialphatheta', 'Active', '{"Honor Society","Service","Special Interest","College of Humanities & Social Sciences"}', '{"career","leadership","service"}'),
  ('413299', 'Phi Delta Theta', 'Phi Delta Theta Alpha Alpha promotes leadership, academic excellence, and community service among its members. Our fraternity emphasizes lifelong brotherhood and personal development.', 'Phi Delta Theta is an international social fraternity founded on December 26, 1848, at Miami University in Oxford, Ohio. Known for its principles of friendship, sound learning, and moral rectitude, Phi Delta Theta promotes leadership, academic excellence, and community service among its members. The fraternity emphasizes lifelong brotherhood and personal development, operating under the motto "Become the greatest version of yourself." With chapters across North America, Phi Delta Theta maintains a strict alcohol-free housing policy and supports various philanthropic initiatives, including its partnership with the LiveLike Lou Foundation for ALS research.', 'phidelt', 'Active', '{"Fraternity & Sorority","Service","Sport","Career Planning","Social"}', '{"career","greek-life","leadership","service","social","sport"}'),
  ('134896', 'Phi Kappa Tau Fraternity', 'Phi Kappa Tau is one of the most unique and diverse fraternal organizations on campus. Phi Tau is the oldest fraternity in Orange County and our growth as an organization has been hand in hand with the growth of CSUF.', 'Phi Kappa Tau (ΦKT) – Gamma Omicron Chapter Nationally Founded: March 17, 1906 Colors: Harvard Red; Old Gold National Flower: The Red Carnation Philanthropy: SeriousFun Children''s Network runs camps that give children with serious illnesses a chance to take a break from their medical routines. Our specially designed programs allow kids to be kids for a while, letting them enjoy fun activities and make new friends in a safe, supportive environment. By creating a space where children can temporarily set aside their health challenges, we help them build confidence, create happy memories, and experience the joys of childhood. Motto: “Learning. Leading. Serving.” Vision: The vision of Phi Kappa Tau is to be recognized as a leadership organization that binds men together and c hallenges them to improve their campuses . Mission: The mission of Phi Kappa Tau is to champion a lifelong commitment to brotherhood, learning, ethical leadership and exemplary character. Follow @thebarnpkt on Instagram to stay updated!', 'thebarnpkt', 'Active', '{"Fraternity & Sorority"}', '{"greek-life","social"}'),
  ('137434', 'Phi Mu Alpha Sinfonia Fraternity', 'National Social Fraternity for Men of Music.', 'Phi Mu Alpha Sinfonia is the world’s oldest and largest secret national fraternal society in music. Sinfonia was born on October 6, 1898, at the New England Conservatory in Boston, when a group of thirteen young men under the guidance of Ossian Everett Mills met “to consider the social life of the young men students of that institution [and] to devise ways and means by which it might be improved.” Sinfonia became a national fraternity on October 6, 1900, with the admission of a group of men at the Broad Street Conservatory in Philadelphia. For over a century, Sinfonians in nearly every field of study and professional endeavor have transformed music in America. The opportunity of becoming a Sinfonian is offered to as many men as possible who, through a love for music, can assist in the fulfillment of the Fraternity’s Object and ideals either by adopting music as a profession, or by working to advance the cause of music in America. OUR MISSION adopted 1901 The Object of this Fraternity shall be for the development of the best and truest fraternal spirit; the mutual welfare and brotherhood of musical students; the advancement of music in America and a loyalty to the Alma Mater.', 'sinfoniaomicronpi', 'Active', '{"College of the Arts"}', '{"career","greek-life","leadership","music"}'),
  ('132951', 'Philosophy Club', 'We are a passionate group of students, friends, and faculty who come together to cultivate and explore our shared interests in philosophy.', 'The Philosophy Club at CSUF is a student-run organization that organizes events to cultivate your interests in philosophy. Every year, we collaborate with the faculty of the Philosophy department to put together the annual Philosophy Symposium. The Philosophy Symposium offers students and faculty an opportunity to hear visiting philosophers speak on various issues. It also gives students the chance to engage with professionals from the discipline. Aside from the symposium, the Philosophy Club organizes reading groups, socials, and student/faculty presentations to enrich the philosophy community at Cal State Fullerton.', 'philclub', 'Active', '{"Honor Society","Special Interest","College of Humanities & Social Sciences"}', '{"social"}'),
  ('138237', 'Physician Assistants Coming Together', 'The purpose of this organization is to serve pre-PA students to help become better applicants for PA school or other health profession students who are interested in learning more.', 'The purpose of this organization is to support pre-PA students or those who are interested in learning more about the profession. This club will provide an outlet and be a resource in opportunity and progression towards the Physician Assistant profession. The California State University, Fullerton’s Physician Assistants Coming Together (PACT) Club will be open to all students who have interest in the profession and the field of healthcare. The main objective for this club is to expand knowledge of the PA role, offer diverse perspective from practicing PAs, current PA students, and admissions representatives, as well as create a supportive, welcoming community. Additionally, we host informational sessions, workshops, and volunteer opportunities that support student growth and help foster a caring, collaborative community for those pursuing the PA profession, while striving to give our members the best resources to succeed. This organization welcomes students of all backgrounds and will not tolerate hate, disrespect, or harassments of any kind. -- -- * For the latest info on the club, please follow us on Instagram @pact.csuf * Sign up for our email list here * Join the PACT Discord for organization updates and resources! here', 'pact', 'Active', '{"College of Health and Human Development","College of Natural Science and Mathematics"}', '{"health-wellness"}'),
  ('137924', 'Physics Club at California State University, Fullerton', 'Physics Club is open to all physics enthusiasts, be they physics majors or not! The purpose of Physics Club is to instill the desire for self-improvement, scholastic excellence, and civic responsibility in our members, all while learning about physics.', 'The Physics Club of CSUF is a club dedicated to the further knowledge of the physical studies for all students of all backgrounds. We focus on the integration of classes and students through the use of club activities and events. Our goal is to prepare and connect our members to future endeavors and careers of graduate school and industry.', 'physicsclub', 'Active', '{"Special Interest","Career Planning","College of Natural Science and Mathematics","Social"}', '{"career","social"}'),
  ('136288', 'Pi Alpha Alpha', 'Pi Alpha Alpha is the National Honor Society for Public Affairs and Administration. Our programs promote and reward excellence in public service. Additionally, foster camaraderie among like-minded individuals for serving the public in an impactful way.', 'Pi Alpha Alpha (PAA) is the Global Honor Society for Public Affairs and Administration. The purpose of PAA is to encourage and recognize outstanding scholarship and accomplishment in public affairs and administration. Its objectives, such as fostering integrity, professionalism, and effective performance, promote the advancement of quality in the education and practice of the art and science of public affairs and administration. PAA membership identifies those with the highest performance levels in educational programs preparing them for public service careers. Undergraduate students must have average GPA of 3.0 in all courses included in the major of public affairs and public administration, at least a 3.0 in all other course work. Graduate students must have a GPA of at least 3.7 for 50% of the required course work (a minimum of 18 semester hours). If you are interested in applying for membership, please', 'pialphaalpha', 'Active', '{"College of Humanities & Social Sciences"}', '{"career","leadership","service"}'),
  ('383202', 'Pickleball', 'We are an organization dedicated to fostering environment of pickleball for students to make friends and have fun! All skill levels are welcome, casual and competitive for our recreational open play. As well as a Competition Team for college leagues.', 'We are an organization dedicated to fostering a welcoming social environment around the sport of pickleball. All skill levels are welcome, casual and competitive. Open play is held weekly at the Cal State Fullerton Tennis courts. Tournaments are held monthly and are open to all students. Other special events and fundraisers are planned throughout the semester/year. A competitive team that plays other collegiate pickleball teams is also available to join through a tryout process.', 'pickleball', 'Active', '{"Sport","Recreation","Social"}', '{"recreation","social","sport"}'),
  ('132484', 'Pilipinx American Student Association Kaibigan', 'The Pilipinx-American Student Association at California State University, Fullerton, is a student based group set out on promoting Pilipino unity through education, responsibility, and character.', 'The Pilipinx-American Student Association at California State University, Fullerton was established in 1983 by Robert Litorjua and Eloine de Jesus. We are student based group set out on promoting Pilipinx unity through education, responsibility, and character. This is accomplished with good communication, organization, leadership, recruitment and retention. By teaching Pilipinx culture among the youth, we aim to build Integrity & Friendship, so that one day they themselves can make a difference. By hosting annual events like Friendship Games and our Pilipinx Culture Night, PASA provides an environment open to learning, friendship, self-expression, and growth. For more information on PASA, feel free to contact any board member. Our contact information can be found on csufpasa.com.', 'csufpasa', 'Active', '{"Cultural","Social"}', '{"cultural","social"}'),
  ('226015', 'Planned Parenthood Generation Action at CSUF', 'Our club is committed to educating and advocating issues of reproductive rights and freedoms, while prioritizing inclusivity and political action.', 'Planned Parenthood Generation Action at CSUF is a network of young activists who organize events on their campus and in their community to: Mobilize advocates for reproductive freedom Raise public awareness about reproductive health and rights Educate young people about sexual health Create lasting change in their communities To communicate with our club members about meetings and events we will use discord (the app) and our Instagram page. Discord Code: Instagram name: @ppgenactioncsuf', 'csufppgen', 'Active', '{"Political/Social Action","Service","Health & Wellness","LGBTQ+"}', '{"health-wellness","lgbtq","political-social-action","service"}'),
  ('224831', 'Political Science Student Association', 'Engaging Political Science Students with each other and the community around them.', 'We are a non-partisan, student organization aimed at building community for Political Science Students. We are a resource for all CSUF students to learn about Politics and the importance of Political Science We are working to help increase healthy political engagement on campus. We aim to be the platform to safely discuss political events and topics, safely, on campus. We want to be the outlet for connecting and informing students about careers, internships, and alumni in the field of Political Science.', 'poli-sci-association', 'Active', '{"Political/Social Action","Special Interest","College of Humanities & Social Sciences"}', '{"political-social-action"}'),
  ('431659', 'pop culture communications club', 'Come together and explore different expressions of Pop Culture. Collaborate with clubs and industry professionals through hands-on workshops.', 'A space that allows students to come together and explore different expressions of popular culture. The broadness of the club allows collaboration with different clubs and industry professionals. Students will gain hands-on experience in a variety of different media. We desire to host engaging events that allow members to learn and experiment with pop culture, so they can create their own.', 'popculturecommunicationsclub', 'Active', '{"Cultural","Special Interest","College of Communications","Music","Social"}', '{"career","cultural","music","social"}'),
  ('331224', 'Pre Occupational Therapy Club', 'Our goal is to support an educational environment where CSUF students can learn more about the field of Occupational Therapy.', 'Our goal is to support an educational environment where CSUF students can learn more about the field of Occupational Therapy.', 'preotclub', 'Active', '{"Career Planning","College of Health and Human Development","College of Humanities & Social Sciences","College of Natural Science and Mathematics"}', '{"career","health-wellness"}'),
  ('132865', 'Pre-Dental Society', 'The Pre-Dental Society at California State University, Fullerton is a student run organization that strives to provide undergraduate students and Post-Bac Students a dental concentration with valuable information and resources about the dental field.', 'Official Website: csufpds.com The Pre-Dental Society primary mission is to serve CSUF students interested in pursuing dental related fields. We provide students with the necessary tools to have a strong and well rounded competitive dental school application by integrating students into volunteering, shadowing, educational opportunities, guidance, and support. Our officers for the Pre-Dental Society have committed themselves in serving you to all the dental information for your knowledge in how to be a competitive dental applicant and also to provide opportunities for pre-hygiene/pre-dental students to be involved and to grow within this student organization. We will guide you in hopes you have gained the knowledge that dentistry is the right health profession for you in the future. Joining the PDS has its benefits: It is a great way to meet others who share your interest in dentistry. Provides a great opportunity to get involved in your community. Good source of information that will help you al ong your path to dental school and aid into acceptance to dental school.', 'csufpds', 'Active', '{"Special Interest","College of Natural Science and Mathematics"}', '{"health-wellness"}'),
  ('225830', 'Pre-Physical Therapy Club', 'The Pre-Physical Therapy Club is an organization dedicated to providing students interested in physical therapy with information, experience, and connections to outside organizations, thereby better preparing them for a career in physical therapy.', 'The Pre-Physical Therapy Club is an organization dedicated to providing students interested in physical therapy with information, experience, and connections to outside organizations, thereby better preparing them for a career in physical therapy.', 'prept', 'Active', '{"Special Interest","College of Health and Human Development"}', '{"career","health-wellness"}'),
  ('132413', 'President''s Scholar Student Association', 'As President''s Scholars, we serve as role models to the CSUF community and beyond. PSSA provides opportunities for President''s Scholars to reach higher in our respective 4 pillars: leadership, service, mentorship, and academic excellence.', 'The CSUF President''s Scholars Student Association strives to reach higher by upholding the four pillars of our program: leadership, academic excellence, mentorship, and community service. We are a family of President''s Scholars, encouraging and driving our students to be their very best selves and develop to their highest potential!', 'pssa', 'Active', '{"Service"}', '{"career","leadership","mentorship","service"}'),
  ('431047', 'Project Propel Club', 'Project Propel Club is a community where we uplift, encourage, and grow together as we navigate our journeys in becoming bilingual educators.', 'We are a safe and welcoming space for students passionate or interested about becoming bilingual educators . Project Propel is a community where we uplift, encourage, and grow together as we navigate our journeys in education. Join us for meaningful conversations, learning opportunities, and opportunities to build lasting connections.', 'projectpropelclub', 'Active', '{"Special Interest","College of Education","College of Health and Human Development","Social"}', '{"career","leadership","social"}'),
  ('138173', 'Psi Chi Honor Society', 'We represent the Psi Chi International Honor Society in Psychology - Local Chapter at CSUF. Our mission is to recognize and promote excellence in the science and application of psychology.', 'What is Psi Chi? The International Honor Society in Psychology, founded in 1929. To encourage, stimulate, and maintain excellence in scholarship and advance the science of psychology. Membership is open to graduates and undergraduates. Psi Chi is an international honor society. Psi Chi provides programs to help achieve its goals, including Society and regional conventions, research award competitions, and certificate recognition programs. Benefits of Joining Psi Chi Psi Chi provides international recognition for academic excellence in psychology. Through membership in Psi Chi, students gain a sense of community with others in psychology and identification with the discipline. Psi Chi provides a local, regional, and national forum for obtaining information and developing perspectives about the field of psychology. Having interaction with other students who have similar interests. Members receive a certificate. Psi Chi chapter activities provide students with valuable opportunities to develop one-on-one relationships with professors. Psi Chi encourages student research through research award competitions and provides opportunities for students to present research and receive certificates. Psi Chi provides over $400,000 annually in awards and grants to student members, faculty advisors, and chapters. Psi Chi sponsors outstanding programs at psychological association meetings where members can meet leading psychologists and students from other chapters. Membership is for life! Requirements to Join Psi Chi - Undergraduates, Transfers, and Graduate Students Completed nine 9 semester units of Psychology coursework or completed 6 psychology units with at least 3 in progress. Registered as a psychology major or minor . Students must have an overall GPA of 3.0 or better, and a psychology GPA of 3.2 or better. Fill out your CSUF Psi Chi membership application and download a PDF of your TDA (Titan Degree Audit) . Register with Psi Chi International - Membership Application . After completing the application, click ''Print page'' to download a PDF. Send all materials to csuf.psichi@gmail.com and CC (Carbon Copy) our Membership Coordinator and Treasurer with the subject line titled: Last name, First name - (Semester, Year) Membership Application . Pay your one-time membership fee - pay $20 to our local chapter via email link and pay $55 to the international organization via email link *Only pay once you have receieved an approval email from us* . Email csuf.psichi@gmail.com and CC our Membership Coordinator and Treasurer with the subject line titled: Last name, First name - (Semester, Year) Membership Steps Completed. Requirements to Join Pre-Psi Chi - Freshmen and New Majors/Minors 1. Be enrolled as a psychology major or minor . 2. Fill out your CSUF Pre-Psi Chi membership application and download a PDF of your TDA . 3. Send materials to csuf.psichi@gmail.com and CC our Membership Coordinator and Treasurer with subject line titled: Last name, First name (Semester, Year) - Pre-Psi Chi Membership Application. 4. Pay $10 (plus processing fees) pre-membership fee for local chapter *Only pay once you have received an approval email from us*. 5. Email csuf.psichi@gmail.com and CC our Membership Coordinator and Treasurer with the subject line: Last name, First name (Semester, Year) - Pre-Psi Chi Steps Completed. Members under Pre-Psi Chi Program cannot earn regalia or be recognized for their academic achievement at the local or international level, but are encouraged to participate in order to foster community and network with other Titans *Members under Pre-Psi Chi can reapply for official (local and international) membership at any time once they meet the academic requirements for CSUF Psi Chi)*', 'psichi', 'Active', '{"Honor Society","Service","Special Interest","Career Planning","College of Humanities & Social Sciences","Social"}', '{"career","leadership","service","social"}'),
  ('134986', 'Psychology Department Student Association', 'The Psychology Department Student Association (PDSA) was founded in 1973 and is the departmental club for psychology majors and minors. The purpose of PDSA is to assist all psychology students in achieving their academic goals while attending CSUF.', 'The Psychology Department Student Association (PDSA) strives to educate and inform members of a wide variety of options within the Psychology field. We present workshops, colloquiums, speakers, community services opportunities, and fun activities throughout the year. Some of the events for previous academic years included: bowling night, curriculum vitae workshop, MA/MS graduate student speakers, GRE prep workshop, NAMI walk, bake sale, movie nights, volunteer opportunities, a clothing drive, and more. We also provide socialization opportunities and encourage networking amongst peers and faculty who come to speak during our workshops. PDSA contributes to our CSUF Psychology Department''s Annual Psychology Day by sponsoring a panel discussion on psychology degrees and careers. To view current and upcoming activities and photos, please visit the following: Instagram:', 'pdsa', 'Active', '{"Service","College of Humanities & Social Sciences","Social"}', '{"service","social"}'),
  ('430903', 'Psychology Student Support Club', 'The Psychology Student Support Club (PSSC) is always on standby and ready to assist all California State University, Fullerton students to facilitate a safe space for unity and an opportunity for all.', 'The Psychology Student Support Club, led by faculty advisor Professor Madracki (M.S., LMFT), bridges the gap between students, faculty, and other psychology student-led organizations and associations in support of students throughout their time at California State University, Fullerton. Whether it be connecting with other peers, faculty, other college departments on campus, to internal and external support resources, to managing the multitude of sentiments that go along with being a college student. The Psychology Student Support Club is keen to assist every and all California State University, Fullerton students to facilitate, empower, and endorse a secure space of unity and opportunity for all.', 'psychologystudentsupportclub', 'Active', '{"Cultural","Career Planning","College of Humanities & Social Sciences","Health & Wellness","LGBTQ+","Social","Sustainability"}', '{"career","cultural","health-wellness","lgbtq","social"}'),
  ('415123', 'Public Administration Student Association', 'PASA is a club for all Public Administration students--undergraduate majors and minors and MPA students. The club provides social, professional and academic development, and service opportunities throughout the year.', 'PASA is a club for all Public Administration students, including undergraduate majors and minors and MPA students. The club provides social, professional and academic development, and service opportunities throughout the year. PASA also serves as the host organization for the International City/County Management Association (ICMA) Student Chapter.', 'pasa', 'Active', '{"Service","College of Humanities & Social Sciences","Social"}', '{"service","social"}'),
  ('413298', 'Public Health Student Association', 'Public Health Student Association''s main goal to provide community for those who are interested in protecting and improving quality of life for people in all communities. PHSA also helps educate and prepare the future public health workforce.', 'The Public Health Student Association (PHSA) is dedicated to building a welcoming community for students who are passionate about protecting and improving the health and quality of life of individuals and communities. While PHSA was founded to support students majoring or minoring in Public Health, we welcome students from all academic disciplines and backgrounds who share an interest in public health. Through advocacy, professional development, networking opportunities, and educational programming, PHSA strives to prepare the next generation of public health professionals while fostering a collaborative and inclusive environment. Stay Connected! Instagram: @phsacsuf Email: phsacsuf@gmail.com', 'phsacsuf', 'Active', '{"Service","Special Interest","College of Health and Human Development"}', '{"career","health-wellness","service"}'),
  ('430870', 'Public Interest Law Society', 'A student org connecting students with Public Interest Law through attorney panels and interviews, giving them insight into the field, plus the resources and guidance to pursue it, whether that means law school prep or a future career in public interest.', 'This organization introduces students to Public Interest Law through various panels and interviews with attorneys working in the field. Our goal is to give students the information and resources they need to pursue Public Interest Law as a career, and to navigate the law school process more broadly. Throughout the year, we will have meetings both in person and on Zoom. We will also provide guidance on law school prep, the LSAT, and anything related to students'' journey to law school and beyond.', 'csufpilsmycanvasite', 'Active', '{"Special Interest","Career Planning","College of Humanities & Social Sciences"}', '{"career"}'),
  ('134817', 'Public Relations Student Society of America', 'The Public Relations Student Society of America (PRSSA) at California State University, Fullerton is the leading pre-professional organization for students to jump-start their careers in communications and public relations.', 'The Public Relations Student Society of America (PRSSA) chapter at California State University, Fullerton is a pre-professional organization that assists students in pursuing careers in public relations and communications. As one of the largest PRSSA chapters, we aspire to provide students with meaningful opportunities to learn, connect, and gain real-world experience. PRSSA is the only student-run organization affiliated with a professional chapter. This enables our members to transition seamlessly to the professional organization (PRSA) after graduation. PRSSA operates a student-run public relations firm that provides students with real-world experiences in areas such as social media management, outreach campaigns, media relations, and more. Founded by Robert E. Rayfield in 1968, CSUF PRSSA today fosters nearly 200 members and continues to grow year-over-year. Regardless of your major or experience, our chapter is a welcoming place to grow, form meaningful connections, and prepare for your professional journey. Our members are exposed to all facets and intricacies of the public relations profession through a comprehensive program that includes: Speaker Panels: CSUF PRSSA hosts speaker panels that bring industry professionals to campus to share insights, career advice, and real-world PR experiences. Agency Tours: Members gain first-hand exposure to the field through agency tours that showcase workplace culture, client work, and career opportunities. Workshops: Designed to help students improve public speaking, craft strong resumes and cover letters, and build their personal brand for their future career. Networking Events: CSUF PRSSA provides networking events that connect students with professionals, alumni, and peers to build lasting industry relationships. Enhance your education. Broaden your network. Launch your career. Join us today. Titan Public Relations Titan Public Relations (TPR) is the student-run public relations firm at California State University, Fullerton. Operated by passionate Cal State Fullerton students, TPR provides primarily pro-bono, full-service support to clients, with occasional paid projects through social media strategy, brand management, media relations, outreach campaigns, and more. Our mission is to provide hands-on experience for students at California State University, Fullerton, who strive to apply their knowledge in a real-world setting. TPR provides an environment for students to gain as much knowledge and experience in the field as possible, to become well-equipped professionals in today’s competitive workforce. Learn more about Titan Public Relations here .', 'csufprssa', 'Active', '{"Special Interest","Career Planning","College of Communications","Social"}', '{"career","social"}'),
  ('136486', 'Real Estate Association', 'The Real Estate Association is a club within the College of Business and Economics. Our vision is to achieve success in real estate through building community and providing industry knowledge.', 'Our mission is to e ducate students toward real estate success, build relationships, and collaborate to build a strong community. Guest Speakers | CEO''s | Events | Internships | Company Tours | Professional Organizations | Workshops Interested in our club? Please fill out this interest form for more', 'reacsuf', 'Active', '{"Special Interest","Career Planning","College of Business and Economics","Social"}', '{"business","career","social"}'),
  ('134617', 'Resident Student Association', 'The Resident Student Association (RSA) is the elected student government whose mission is to enhance the overall living and college experience within Housing and Residential Engagement.', 'The Resident Student Association (RSA) is the elected student government whose mission is to enhance the overall living and college experience within Housing and Residential Engagement. RSA serves as the voice in advocacy of the community, while providing leadership opportunity and engaging programs. RSA encourages all students to get involved by attending weekly General Council and Committee meetings to voice their concerns, get informed, and get connected to the greater CSUF community.', 'rsa', 'Active', '{"Umbrella (Council)"}', '{"leadership"}'),
  ('136694', 'Roller Hockey', 'The Roller Hockey Club competes in the Western Collegiate Roller Hockey League as part of the National Collegiate Roller Hockey Association. We field one team in DII and one team in DIV. 2013/2014, 2016/2017, 2018/2019 DII NATIONAL CHAMPIONS.', 'The Roller Hockey Club competes in the Western Collegiate Roller Hockey League as part of the National Collegiate Roller Hockey Association. We field one team in DII and one team in DIV. 2013/2014, 2016/2017, 2018/2019 DII NATIONAL CHAMPIONS.', 'ncrha', 'Active', '{"Sport"}', '{"recreation","sport"}'),
  ('382108', 'Sabor Latino Social Club', 'SABOR LATINO SOCIAL CLUB IS A SALSA DANCING CLUB DEDICATED TO TEACHING SALSA COMBINATIONS ON A BEGINNER LEVEL AS WELL AS COVERING THE BASICS OF OTHER LATIN RHYTHMS SUCH AS CUMBIA, BACHATA, AND MERENGUE.', 'SABOR LATINO SOCIAL CLUB IS A SALSA DANCING CLUB DEDICATED TO TEACHING SALSA COMBINATIONS ON A BEGINNER LEVEL AS WELL AS COVERING THE BASICS OF OTHER LATIN RHYTHMS SUCH AS CUMBIA, BACHATA, AND MERENGUE. WE AIM TO CREATE A COMFORTABLE ENVIROMENT WHERE PEOPLE WITH VARYING LEVELS OF INTEREST IN SALSA CAN COME AND PRACTICE/LEARN, WHILE ALSO CREATING FRIENDSHIPS AND JOINING AN INCLUSIVE COMMUNITY OF PEOPLE WHO HAVE SIMILAR BACKGROUNDS OR INTERESTS. OUR GOAL IS TO EXPOSE EVERYONE TO THE VAST WORLD OF MUSIC, DANCING, AND CULTURE THAT EXISTS WITHIN THE SOCIAL DANCING SCENE. WE PLAN TO DO SO BY HAVING LESSONS ONCE A WEEK, AND PLANNING DIFFERENT OUTINGS/SOCIALS AS OFTEN AS WE CAN BOTH IN AND OUT OF THE SCHOOL. SOCIAL DANCING IS A GREAT WAY TO LET LOOSE AND ENJOY YOURSELF AND WE HOPE TO BE THE FIRST STEPPING STONE FOR A LOT OF OUR MEMBERS TO FEEL COMFORTABLE GOING OUT AND EXPLORING ON THEIR OWN.', 'saborlatinosocialclub', 'Active', '{"Cultural","Recreation","Dance","Social"}', '{"cultural","dance","recreation","social"}'),
  ('429216', 'School on Wheels at CSUF', 'The CSUF based chapter of SOW will aim to support K-12 students facing homelessness in the north Orange County region. Our volunteers provide tutoring and mentoring services to these students with the intent to empower them to obtain higher education.', 'School on Wheels at CSUF seeks to create a supportive and encouraging environment where students facing homelessness can succeed academically despite challenges caused by housing instability. Through tutoring and mentorship, we will strive to reduce educational inequities, inspire a passion for learning, and foster resilience, confidence, and long-term academic success. In addition to supporting K–12 students, our organization will also aim to connect CSUF students with meaningful volunteer opportunities that promote leadership, empathy, and community engagement. School on Wheels at CSUF will also work to raise awareness about homelessness and educational inequality through campus outreach, volunteer recruitment, and community service initiatives. The organization may also host school supply drives, fundraising events, guest speakers, advocacy discussions, and collaborations with other organizations focused on serving vulnerable populations. Our goal will not only be to provide direct academic support, but also to create a campus community dedicated to service, compassion, and educational equity.', 'schoolonwheels', 'Active', '{"Service"}', '{"mentorship","service"}'),
  ('295468', 'SEOULFUL', 'SEOULFUL focuses on spreading the love for both K-POP and dance! We upload dance covers on Youtube, perform at events on-campus, and compete outside of campus.', 'SEOULFUL is a K-POP Dance Cover Team based in Cal State Fullerton and was formed in 2018. The team consists of members from multiple backgrounds who share the love of dance and K-POP. SEOULFUL is split into three teams, Angelic, Heavenly, and Ethereal. The team is made up of trainees, cover team, and performance team, respectively. The main goal is to help each dancer flourish in different areas based on the teams.', 'seoulful', 'Active', '{"Cultural","Dance","Social"}', '{"cultural","dance","social"}'),
  ('376152', 'Sigma Alpha Epsilon', 'As brothers of Sigma Alpha Epsilon, we strive to reach the highest standards of friendship, scholarship, leadership, and service throughout our lives.', 'The values put forth by our Founding Fathers are as relevant today as they were in 1856. And we believe it’s our duty to follow them in order to better ourselves, our brothers, and everyone around us. Our goal is to give young men the community, culture, guidance, and tools they need to be a True Gentleman. This means having focused principles, strong convictions and the strength to always do the right thing—as a True Gentleman rises above his peers to be a guiding light today and tomorrow.', 'sigmaalphaepsilon', 'Active', '{"Fraternity & Sorority"}', '{"greek-life","leadership","service","social"}'),
  ('134885', 'Sigma Alpha Iota', 'Sigma Alpha Iota is an organization which promotes interaction among those who share a commitment to music. Members of SAI are active in all areas of campus music and campus life, working closely with faculty, administration, campus and community groups.', 'Sigma Alpha Iota is an international women’s music fraternity that specializes in projects and events for the purpose of empowering others through music. Our membership includes music majors, music minors, and non-majors who wish to continue their passion for music with other women who are as passionate as they are. We do such projects as Girl Scout Day in which we help troops achieve their music badge through different workshops and performances, caroling for cans in which we perform Christmas carols in exchange for can good to which we donate, and much more! Some of our Phillanthropic efforts include a project called People to People in which we donate instruments, sheet music, etc. to developing countries to further their growing performing arts programs. Music is the basis of or fraternity, we love music and wish to share that love to the community, the country, and the world.', 'sigmaalphaiota', 'Active', '{"Service","College of the Arts","Music"}', '{"career","leadership","music","service"}'),
  ('138106', 'Sigma Delta Alpha Fraternity Incorporated', 'A Multiculturally oriented Fraternity founded on May 5, 1992 at SJSU. SDA reached CSUF in 2006, with 12 chapters spread throughout the west coast. We strive to achieve academic excellence, while also giving back to the community and creating brotherhood.', 'A Multiculturally oriented Fraternity. Founded in May 5, 1992 at SJSU, Sigma Delta Alpha reached California State University Fullerton in 2006, with 12 chapters in the West. We strive to achieve academically excellence, while giving back to the community and creating brotherhood. Excellence and Loyalty amongst brothers; SDA seeks to help members succeed in school and achieve academic excellence, while teaching valuable life skills, and creating life long bonds of brotherhood. We are accepting of all cultural backgrounds, and welcome new cultures enthusiastically. Sigma Delta Alpha is a non-profit organization that works with a wide range of causes like St. Jude, CHOC, Avid program, Maywood Education Fair, and raise awareness for other causes like Men’s health awareness.', 'sigmadeltaalpha', 'Active', '{"Cultural","Fraternity & Sorority"}', '{"cultural","greek-life","service","social"}'),
  ('383333', 'Sigma Gamma Rho Sorority, Incorporated', 'The Owt-Most Omicron Mu Chapter was charter on April 13, 1998 on the campus of California State University, Fullerton. Omicron Mu is in the process of reactivating on campus to continue the history of making a positive impact on and off campus.', 'Sigma Gamma Rho is a national collegiate sorority incorporated in 1922. Over the years, Sigma Gamma Rho has served as a home for thousands of collegiate and professional women looking for a place to share inspiring life experiences, learn new things, conquer life challenges, thrive in society, and uplift the community through sisterhood, scholarship, and service. The dynamic women of Sigma Gamma Rho have built and sustained a well-known and highly respected reputation for leading positive change. We currently have more than 500 chapters in the United States, U.S. Virgin Islands, Bahamas, Bermuda, Canada, Germany, South Korea and the United Arab Emirates.', 'sgrhoomicronmu', 'Active', '{"Fraternity & Sorority"}', '{"greek-life","social"}'),
  ('135394', 'Sigma Kappa', 'The Epsilon Tau chapter of Sigma Kappa national sorority at Cal State Fullerton. Our sorority provides a strong foundation of support and sisterhood for collegiate women, surrounding the values of personal growth, service, friendship, and loyalty.', 'Sigma Kappa Sorority was founded on November 9th, 1874 at Colby College in Waterville, Maine. Our five founders, the only women at the university, sought to create a sisterhood that would encourage a woman’s heart, mind, and spirit while giving her skills to positively impact her campus and community. The Epsilon Tau chapter of Sigma Kappa at CSUF was founded in 1971. Our values are Friendship, Loyalty, Service, and Personal Growth. Our symbols are the heart and the dove. Our mottos is "One heart, One way" As Sigma Kappas we hold our value of Service close to our hearts. Our five philanthropies include the Sigma Kappa Foundation, Inherit the Earth, Gerontology, the Maine Seacoast Mission, and Alzheimer''s Awareness/Research. This year we have been able to serve our community through raising over $10,000 for the Sigma Kappa Foundation, attending the Walk to End Alzheimer''s event, and Sigma Kappa''s Best Dance Crew (SKBDC) philanthropy.', 'sigmakappa', 'Active', '{"Fraternity & Sorority"}', '{"greek-life","service","social"}'),
  ('144250', 'Sigma Lambda Beta International Fraternity, Inc.', 'ΣΛB is the largest historically Latino-based fraternity in the nation, established with a multicultural membership. We promote Latinx culture as well as standards of excellence in morality, ethics, and education.', 'In the fall of 1985, Baltazar Mendoza-Madrigal began envisioning a Latino-based fraternity at the University of Iowa. Inspired by the influence of established organizations like Phi Beta Sigma Fraternity, he recognized the potential for a brotherhood centered on Latino culture that could provide unity, support, and leadership opportunities for Latino students on campus. With no idea of the legacy he was about to create, Mendoza-Madrigal committed himself to extensive research and exploration. After several months of preparation, he convened a pivotal meeting on March 7, 1986, at the Chicano Indian American Cultural Center—now known as the Latino Native American Cultural Center. This gathering brought together Latino students to discuss the viability of creating a social fraternity rooted in cultural awareness and unity. “At the time, the Latino community was fragmented across multiple social circles,” Mendoza-Madrigal recalled. The overwhelming enthusiasm for forming a unified organization sparked rapid momentum. Excitement quickly spread throughout campus, signaling that something transformative was on the horizon. Through continued collaboration and planning, the ideals and mission of the new organization were solidified. On April 4, 1986, Sigma Lambda Beta International Fraternity was officially founded at the University of Iowa. Nearly four decades later, Sigma Lambda Beta has grown into a powerful network of over 100 collegiate entities across 29 states. While founded with a Latino-based vision, the fraternity has since evolved into one of the most culturally diverse Greek-letter organizations in the nation. Its rich and inspiring history is chronicled in the book Out of the Iowa Cornfields .', 'slb1986', 'Active', '{"Cultural","Fraternity & Sorority","Service","Social"}', '{"cultural","greek-life","service","social"}'),
  ('135095', 'Sigma Nu', 'Sigma Nu provides its members unique opportunities to enhance their college experience through leadership, brotherhood and social events, as well give back to the University and community through philanthropy and volunteering.', 'Headquartered in Lexington, Virginia, Sigma Nu Fraternity was founded in 1869 at Virginia Military Institute in Lexington. Sigma Nu currently has 172 active chapters and colonies on college campuses throughout the United States and Canada, and has initiated over 230,000 members since its founding.', 'sigmanu', 'Active', '{"Fraternity & Sorority"}', '{"greek-life","leadership","service","social"}'),
  ('132835', 'Sigma Tau Delta English Honors Society', 'Sigma Tau Delta is an international English honor society that recognizes the successful hardworking individuals within the undergraduate, graduate, and professional levels of study. We are the Alpha Delta Zeta chapter.', 'Sigma Tau Delta at Cal State Fullerton strives to promote an environment of literary exchange and discussion, to provide opp ortunities for scholarships and publishing, to help students make connections within the English department, and to create a community for like-minded individuals who want to talk for hours about the books they love.', 'csufsigmataudelta', 'Active', '{"Honor Society","Special Interest","College of Humanities & Social Sciences","Social"}', '{"career","leadership","social"}'),
  ('340751', 'Sigma Theta Psi Multicultural Sorority', 'Sigma Theta Psi is a multicultural, academic, and social sorority.', 'Sigma Theta Psi is a multicultural, academic, and social sorority founded on November 13, 1991 by eighteen visionaries. Our founders sought to solidify and immortalize the values and responsibilities that embodied their persons. They worked to create a space within their Greek community that celebrated people from all walks of life, a vision we carry forth to this day. Our organization strives to share a message of cultural diversity, respect, and compassion with others through the shared principles of honesty, loyalty, respect, open-mindedness, leadership, and academic excellence. It is through unity and sisterhood that our members continue to embrace diverse cultures and excel in their life ambitions.', 'stp', 'Active', '{"Cultural","Fraternity & Sorority","Social"}', '{"cultural","greek-life","social"}'),
  ('134819', 'Sigma Upsilon Mu', 'Sigma Upsilon Mu is a co-ed fraternity whose purpose is to inspire students of all backgrounds to follow their dreams by applying entrepreneurship principles. We are passionate leaders who pursue our goals by upholding our motto Deeds Not Words.', 'Sigma Upsilon Mu (SUM) is a co-ed entrepreneurship business fraternity established in March 2014. Our motto is “Facta Non Verba” (Deeds, Not Words). This means taking action instead of being idle. Our mission is to completely transform the lives of college students to reach their fullest potential. With the implementation of entrepreneurship principles, we will be a community of lifelong learners who will become future innovators such as founders, executives, and people who are financially independent. We host a variety of events throughout the semester, such as the 8 hour business challenge, networking events, opportunity to learn from guest speakers from various industries, and much more. New members go through a pledging process in which they enter into a chapter class and attend workshops, work on projects together, and apply entrepreneurial principles that are learned throughout the semester into their everyday lives to create a business of their own or pursue a career in whatever they would like. Sigma Upsilon Mu strongly believes in its pillars A.B.L.E (achievement, brotherhood, leadership, entrepreneurship) and emphasize these principles to all our members. We are an organization of people who are more than just talk, we accomplish what we aim to do. Click here for our DiscoverFest Zoom Link', 'sigmaupsilonmu', 'Active', '{"Fraternity & Sorority","Career Planning","College of Business and Economics"}', '{"career","greek-life","leadership","startups"}'),
  ('365094', 'Sikh Student Association', 'The Sikh Student Association (SSA) provides Sikhs a space for discourse and engagement with Sikh faith and practices. Our mission is to educate both Sikh and non-Sikh peers through community involvement, fostering educational dialogue about the faith.', 'The Sikh Student Association at California State University, Fullerton, is built to create a welcoming environment for Sikh students to foster educational dialogue about the Sikh faith and its practices. The purpose is to serve the greater campus community—both Sikhs and non-Sikhs—by bridging the gap for students to engage in selfless service, meaningful discussions, and promote Sikh values on campus. The association collaborates with other Sikh Student Associations to build a strong network of college Sikhs across Southern California, creating a united community for shared growth and support.', 'sikhsofcsuf', 'Active', '{"Cultural","Political/Social Action","Faith"}', '{"cultural","faith","political-social-action"}'),
  ('383119', 'Ski and Snowboard Club', 'Welcome to the CSUF Snowboard and Ski Club! Whether you''re a seasoned rider or a first-timer, our inclusive club offers unforgettable experiences on and off the slopes. Join us for regular trips, skill-building, and a vibrant social scene', 'Welcome to the CSUF Snowboard and Ski Club, where snow enthusiasts of all kinds come together to chase powder, embrace the thrill of the slopes, and receive special discounts. About Us: Our club is dedicated to providing a supportive environment where members can improve their techniques, explore new terrains, and enjoy the sheer joy of winter sports. Meetups & Group Rides: Join us for regular outings to the best local resorts and hidden gems. Our group rides cater to all skill levels, from beginners to advanced, ensuring everyone has a blast while improving their skills. Social Events: Off the slopes, we host fun social events like movie nights, bonfires, après-ski gatherings, and seasonal parties. It’s a great way to relax, bond with fellow members, and share your latest snow adventures. Special Trips: From weekend getaways to epic powder chases, our club organizes exciting trips to renowned ski resorts and backcountry spots. Gear & Pass Discounts: Our members receive special discounts to lower the prices of gear, Ikon passes, and lift tickets. We know how expensive this sport can get, so we try our best to accommodate everyone who is interested in joining our community! Join Us: Whether you''re looking to perfect your technique, find new riding buddies, or just enjoy the thrill of the snow, the Ski and Snowboard Club is the place for you. Come for the skiing and snowboarding; stay for the community and the shared passion for winter fun. Let’s hit the slopes and make every winter day an adventure!', 'skisnowclub', 'Active', '{"Sport","Recreation","Outdoors","Social"}', '{"outdoors","recreation","social","sport"}'),
  ('203288', 'Society for the Advancement of Chicanos/Hispanics and Native Americans in Science at California State University, Fullerton', 'SACNAS is a national society that fosters the success of persons from groups historically under-represented in science and seeks to improve and expand opportunities for students in the scientific workforce and academia.', 'SACNAS (Society for the Advancement of Chicanos/Hispanics and Native Americans in Science) is a national organization dedicated to “True diversity in STEM. True diversity means that the field (including leadership positions) reflects the demographics of the population.” We envision a CSUF SACNAS chapter as an opportunity for students from all STEM fields to build community. Members would span experience levels from first year undergraduates to graduate students. From the SACNAS website ( www.sacnas.org ): “The purpose of chapters is to promote the mission of SACNAS at the local and national level to offer educational and professional development resources and opportunities to students.” “SACNAS is an inclusive organization; the student chapter shall be open to any interested students regardless of STEM major, ethnicity, race, religion, economic background, gender, sexual orientation and/or disability.”', 'sacnascsuf', 'Active', '{"Cultural","Service","Special Interest","College of Natural Science and Mathematics","Social"}', '{"career","cultural","service","social"}'),
  ('297863', 'Society for the Advancement of Material and Process Engineering CSUF Chapter', 'The Society for the Advancement of Material and Process Engineering (SAMPE®) is a global professional member society that provides enhanced educational opportunities, by delivering information on new and advanced materials and processing technology.', 'The Society for the Advancement of Material and Process Engineering (SAMPE®) is a global professional member society that provides enhanced educational opportunities, by delivering information on new and advanced materials and processing technology. SAMPE provides growth and educational opportunities via conferences, exhibitions, technical forums, and publications. As the only technical society encompassing all fields of endeavor in materials and processes, SAMPE provides a unique and valuable forum for scientists, engineers, and academicians.', 'sampe', 'Active', '{"Special Interest","College of Engineering and Computer Science","Technology"}', '{"engineering","technology"}'),
  ('137052', 'Society of Automotive Engineering - Formula', 'SAE is California State University, Fullerton’s Formula Titan Racing team and one of the university’s premier engineering legacy organizations. Members gain hands-on experience in designing, manufacturing, testing, and competing with a Formula SAE car.', 'SAE is California State University, Fullerton’s Titan Racing Formula SAE team and one of the university’s premier engineering legacy organizations. The club gives students hands-on experience in designing, manufacturing, testing, and competing with a formula-style race car in the international Formula SAE Collegiate Design Series. Members work across multiple subteams, including suspension, chassis, aerodynamics, powertrain, electrical, and vehicle dynamics, while also gaining experience in teamwork, project management, sponsorship, and business operations. Titan Racing provides students with real-world engineering experience that prepares them for careers in the automotive and motorsports', 'fsae', 'Active', '{"Special Interest","Recreation","College of Engineering and Computer Science","Technology"}', '{"engineering","recreation","technology"}'),
  ('423292', 'Society of Cybersecurity Professionals', 'A Community of students interested in pursuing the field of Cybersecurity and developing connections along the way.', 'A Community of students interested in pursuing the field of Cybersecurity and developing connections along the way.', 'scp', 'Active', '{"College of Engineering and Computer Science","Social"}', '{"cybersecurity","social"}'),
  ('132625', 'Society of Excellence in Human Resources', 'SEHR is a professional society focused on connecting students with HR Professionals and developing young leaders. We provide all students with professional development, networking, and social opportunities. We invite you to come and grow with us!', 'Society of Excellence in Human Resources (SEHR) is a Business Inter-Club Council (BICC) funded club. Its purpose is to promote the professional development of California State University, Fullerton students of all majors, with a particular emphasis on promoting development of future human resource professionals. These goals are achieved by providing bi-weekly symposiums, presentations and guest speakers focusing on topics related to the Human Resource profession. Members of SEHR are also members of the Professionals in Human Resources Association and are given great opportunities to network with large groups of human resource professionals throughout Southern California on a monthly basis. Along with these exceptional networking opportunities, SEHR also offers opportunities to: volunteer for various causes, earn leadership skills by applying for the executive board, compete in the SHRM Case competitions, and social gatherings to build relationships with students with similar interests and goals! For more information please reach out to us through email or any of our social media platforms!', 'sehrcsuf', 'Active', '{"College of Business and Economics"}', '{"career","leadership"}'),
  ('135973', 'Society of Hispanic Professional Engineers', 'The vision of SHPE at CSUF is a world where our members are highly valued and influential as the leading innovators, scientists, mathematicians and engineers.', 'SHPE at CSUF is a student-driven organization at the College of Engineering and Computer Science (ECS) that strives to leave a lasting impact on its members. Our mission is to develop and strengthen the next generation of Innovators, Scientists, Mathematicians, and Engineers through STEM awareness, access, support, and development. SHPE at CSUF provides its member''s opportunities to network with professionals, access to workshops, along with attending regional and national conventions. Not only do we focus on professional development, but also your personal development by providing a support system and leadership opportunities. If you’re a student looking to get involved, look no further, and join your SHPE Familia! If you have a question, please email us at csufshpe@gmail.com . We look forward to meeting you!', 'csufshpe', 'Active', '{"Cultural","Special Interest","Career Planning","College of Engineering and Computer Science","Social","Technology"}', '{"career","cultural","engineering","social","technology"}'),
  ('137481', 'Society of Manufacturing Engineers', 'SME is an organization for individuals, students, educators and companies involved in all facets of manufacturing. SME will attempt to bring advanced manufacturing methods to campus and better prepare students leaving CSUF for the industry.', 'SME is dedicated to bringing advanced manufacturing methods to Cal State Fullerton, as well as teaching and training to use these methods. Knowing various manufacturing methods will help our students in designing for the industry.', 'sme', 'Active', '{"College of Engineering and Computer Science"}', '{"career","engineering"}'),
  ('138169', 'Society of Women Engineers', 'We are an organization that supports diversity in engineering and technology, through outreach, volunteering and community service.', 'Stimulate women to achieve full potential in careers as engineers and leaders, expand the image of the engineering profession as a positive force in improving the quality of life, and demonstrate the value of diversity.', 'swe', 'Active', '{"Political/Social Action","Service","College of Engineering and Computer Science","Technology"}', '{"engineering","political-social-action","service","technology"}'),
  ('135495', 'Sociology Department Student Association', 'Sociology Department Student Association (SDSA) is dedicated to applying Sociology in the community and providing valuable opportunities to students through workshops, community service, and networking opportunities with the faculty at CSUF.', 'Sociology Department Student Association (SDSA) is dedicated to applying Sociology in the community and providing valuable opportunities to students through workshops, community service, and networking opportunities with the faculty at CSUF. We are open to all majors! CSUF SDSA is part of Alpha Kappa Delta, the International Sociology Honor Society.', 'alphakappadelta', 'Active', '{"Honor Society","Political/Social Action","Service","College of Humanities & Social Sciences","Social"}', '{"career","political-social-action","service","social"}'),
  ('134814', 'Soon Movement / KCCC', 'Soon Movement (KCCC) at CSUF is one of several campus ministries all across America committed to helping to fulfill the Great Commission as stated in Matthew 28:18-20: "All authority has been given to me. Therefore go and make disciples', '', 'kccc', 'Active', '{"Faith"}', '{"faith"}'),
  ('129836', 'Sports Club Inter-Club Council', 'The mission of the Club Sports program is to provide high-quality, structured, competitive, and fun activities that offer participants the opportunity to experience physical, social, and emotional growth in a safe and fun learning environment.', 'Welcome to the Club Sports program at California State University, Fullerton (CSUF). Club Sports are offered within the department of the Dean of Students, within the division of Student Affairs at CSUF. The Club Sports program is administered by the office of Student Life and Leadership. The Club Sports program aims to enhance the CSUF experience for all student’s and campus life. Club Sports teams are formed, developed, governed and administered by student club membership. Each Club Sports team works in conjunction with the Club Sports program administrators for program oversight. List of Sports Clubs Archery Badminton Bowling Climbing Cricket Gaming/Esports Golf Ice Hockey Jujitsu M Baseball M Lacrosse M Soccer M Volleyball Pickleball Powerllifting Roller Hockey Rugby Ski and Snowboarding Softball Swim Tennis Titan Strong Ultimate W Lacrosse W Soccer W Volleyball Water Polo', 'clubsports', 'Active', '{"Umbrella (Council)","Sport"}', '{"leadership","sport"}'),
  ('181118', 'Student Academy of Audiology at California State University, Fullerton', 'The mission of the Student Academy of Audiology Chapter at CSUF is to advance the rights, interests, and welfare of students interested in pursuing a career in audiology.', 'The mission of the Student Academy of Audiology Chapter at CSUF is to serve as a collective voice for students within the chapter area and to advance the rights, interests, and welfare of students pursuing careers in audiology or related fields. The chapter will engage students in lifelong professional activities that promote and advance the profession of audiology and provide services, information, education, representation and advocacy for the profession and the public we serve. Feel free to check out our instagram!', 'saaatcsuf', 'Active', '{"Special Interest","College of Communications","Health & Wellness","Technology"}', '{"career","health-wellness","technology"}'),
  ('135118', 'Student Alumni Ambassadors', 'SAA is a student led club that aims to help their peers get connected to alumni and CSUF as a whole. It''s a great way to get involved on campus, learn how to network, meet alumni, develop leadership skills, and much more! We are open to ALL students!', 'ABOUT US: The Student Alumni Ambassadors promote, foster, and create mutually beneficial relationships among the University’s students, alumni, staff, faculty, prospective students and the campus community for the betterment of Cal State Fullerton. We work hand–in–hand with the CSUF Alumni Association’s Board of Directors and Alumni Engagement staff. Being a member of SAA is easy. Click JOIN and look out for our emails! Only attend meetings and events that fit your interests and schedules. Get updates about how to connect with alumni, learn about scholarships, and get early bird registration for signature events! Follow our Instagram @csufsaa for updates! For those looking to elevate your involvement: By being an active member that joins meetings, events, and/or takes on a leadership role: your involvement as a Student Alumni Ambassador gives you a voice and a direct connection to more than 340,000 outstanding Titan Alumni. This experience offers an opportunity to gain leadership and networking skills, develop personal relationships with prominent and successful CSUF Alumni, participate in and volunteer alongside alumni at Association sponsored events. Within the Ambassador team, you will gain experience in leadership positions, teamwork, and programming. Student Today, Alumni Tomorrow, Titan Forever', 'saa', 'Active', '{"Service","Special Interest","Career Planning","Social"}', '{"career","leadership","service","social"}'),
  ('223584', 'Student Association for Asian American Studies', 'The Student Association for Asian American Studies (SAAAS) is the official student organization of the Department of Asian American Studies. Connect with students, build friendships, and access resources for academic, personal, and professional growth.', 'The purpose of this organization is to support the growth and development (academic, personal, and professional) of the students of the CSUF Department of Asian American Studies (ASAM), to provide opportunities for student leadership, organizing, and community building, to provide space to build friendships and connections within Asian American Studies, and to serve Asian Pacific Islander South Asian American (APISAA) and allied communities.', 'saaas', 'Active', '{"College of Humanities & Social Sciences"}', '{"social"}'),
  ('132947', 'Student California Teachers Association', 'A student club for future educators dedicated to community outreach, social justice, diversity, and advocacy in education. Under the teacher union CTA, we offer benefits, professional development, networking and personal growth opportunities for members.', 'SCTA is a student union organization under CTA, the largest teachers association in California. SCTA is an organization specifically for aspiring future educators. Our chapter helps members connect with the SCTA organization by participating in community outreach events, social gatherings, and professional development workshops. SCTA offers members many opportunities to learn about diversity and culture while actively changing social injustices for future generations. In addition, all members will access benefits, discounts, conferences, and classroom resources! We strive to make a positive difference in education by preparing aspiring educators to make lifelong impacts on students for their future careers. For more information, visit our website: Be sure to follow us on Instagram as well @csuf.scta', 'scta', 'Active', '{"Special Interest","Career Planning","College of Communications","College of Education","College of Health and Human Development","College of Humanities & Social Sciences","College of Natural Science and Mathematics","Outdoors","Social"}', '{"career","political-social-action","service"}'),
  ('132978', 'Student Health Professions Association', 'The Student Health Professions Association (SHPA) provides critical resources to students pursuing careers in healthcare, such as networking with professionals, hearing from health speakers, clinical experience, volunteer opportunities, and more.', 'SHPA is dedicated to informing students about the opportunities available in the various health professions, such as allopathic medicine (MD), osteopathic medicine (DO), physician associates (PA), dentistry, optometry, veterinary science, and nursing (RN). Professionals from each of the aforementioned careers speak for members of the club, detailing their journeys and experiences to students and establishing relationships with interested students. Beyond this, events such as the American Red Cross Blood Drive, suturing events, and various volunteer opportunities are often present, allowing students to get connected to their fields and the community at large. We work closely with the Health Professions Advising Office to provide members the resources needed to accomplish their dreams. Join through', 'shpa', 'Active', '{"Special Interest","Career Planning","College of Natural Science and Mathematics"}', '{"career","health-wellness","service"}'),
  ('381980', 'Student Productions Organized by Titans', 'We host meetings to talk all things theatre and play fun theatre games. We put on one production per semester to provide opportunity to CSUF students in acting and designing.', 'The purpose of this organization is to engage with the CSUF community by giving students the opportunity to learn and grow in the performing arts, both performance and production. We stand strongly behind the values of acceptance, tolerance, and inclusivity. This will be represented through those involved and our production choices. Our student organization produces one production per semester aiming to showcase the theatrical talents of CSUF students.', 'csufspot', 'Active', '{"College of the Arts"}', '{"arts"}'),
  ('137636', 'Student Speech Therapists and Audiologists Nurturing Cultural Enrichment', 'Student Speech Therapists and Audiologists Nurturing Cultural Enrichment (STANCE) is an academic subchapter of CSUF NSSLHA that seeks to promote awareness of multiculturalism and diversity in the fields of Speech-Language Pathology and Audiology.', 'Settled within an eclectic, multicultural university and community, California State University, Fullerton’s STANCE highlights the importance of social justice, multiculturalism and diversity. As an academic subchapter of CSUF’s gold-accredited NSSLHA, STANCE provides events, information, and resources to Communicative Disorders students. STANCE facilitates an open forum between community representatives, professionals, and aspiring speech-language pathologists and audiologists to share insights and ideas that will aid students in serving culturally and linguistically diverse populations. STANCE not only strives to engage Communicative Disorders students in their ongoing education, but also encourages students to make connections to various diverse groups, on-campus organizations, and volunteer opportunities within the Fullerton community. Learn more about us from this Youtube video! this YouTube video', 'stance', 'Active', '{"Cultural","Service","Career Planning","College of Communications"}', '{"career","cultural","health-wellness","service"}'),
  ('132783', 'Student Veterans of America', 'The purpose of this organization is to cultivate a sense of belonging among student veterans in higher education to foster success on and off campus.', 'We are the Student Veterans of America (SVA) at California State University Fullerton (CSUF). We strive to connect local veteran organizations with our student veterans through volunteering and networking. This organization is affiliated with Student Veterans of America, which is a national non-profit organization that advocates for student veterans through legislation and policy in Washington D.C.', 'studentveteransassociation', 'Active', '{"Service","Special Interest","Recreation","Career Planning","College of Humanities & Social Sciences","Outdoors","Social"}', '{"career","outdoors","recreation","service","social"}'),
  ('137435', 'Students for Smiles', 'Students for Smiles is an organization dedicated to bringing awareness to cleft lip and palate and for raising funds for Smile Train.', 'Students for Smiles is an organization dedicated to bringing awareness to cleft lip and palate around the world and for raising funds for Smile Train. Smile Train is a leading international children’s charity that provides free cleft lip and palate repair surgery to children in 85+ developing countries. Their medical services consist of but are not limited to speech therapy, orthodontic care, emotional support, and nutritional care. Cal State Fullerton''s Students for Smiles chapter is committed to furthering the mission of Smile Train by providing students with informational workshops and fundraising and volunteer opportunities. Through community outreach, students advocate for the awareness and needs of children with cleft lip and palate all around the world. Join our GroupMe:', 'studentsforsmiles', 'Active', '{"Service","Special Interest"}', '{"service"}'),
  ('135857', 'Super Smash Brothers Club', 'The Smash Club of CSUF is a club to help grow and bring together the local community of students interested in the Super Smash Bros. franchise and engage in social events that encourage friendly competition and community building.', 'Our club''s goal is to help bring together the Super Smash Bros franchise to the students who are interested in learning in a competitive way and built a community around it. Our meetings consist of friendly grind session and we also host weekly tournaments. In addition, we will have fun events such as doubles, crew battles, squad strike, and even other Smash franchises.', 'csufsmash', 'Active', '{"Cultural","Special Interest","Recreation","LGBTQ+","Social","Technology"}', '{"cultural","lgbtq","recreation","social","technology"}'),
  ('297375', 'SWANA (SouthWest Asian North African)', 'To promote the interests of the SWANA (SouthWest Asian North African) students at California State University, Fullerton (CSUF), and to acquaint the California State University, Fullerton community with SWANA-identifying students.', 'To promote the interests of the SWANA (SouthWest Asian North African) students at California State University, Fullerton (CSUF), and to acquaint the California State University, Fullerton community with SWANA-identifying students.', 'swana', 'Active', '{"Cultural","Special Interest"}', '{"cultural"}'),
  ('349481', 'Tabletop Titans Club', 'This club aims to introduce as many people as possible to the collaborative storytelling tabletop RPG game Dungeons and Dragons as a way to boost creativity, imagination, and bonds. We believe it is a fantastic way to make friends and express yourself!', 'Formerly the D&D club, this club aims to build community through tabletop gaming, such as card games, board games, and tabletop games such as Dungeons & Dragons. We intend to introduce as many people to the joys of tabletop gaming and demonstrate it as an excellent tool to connect and bond with other people. We believe tabletop gaming has something for everyone to enjoy and is a fantastic way to not only make friends, but to find self-expression alongside our', 'csuftabletoptitans', 'Active', '{"Special Interest","Recreation","Social"}', '{"recreation","social"}'),
  ('136222', 'Taiwanese Student Association', 'TSA is a student organization that works to bring together the Taiwanese students at Cal State Fullerton. With the community, we develop an awareness of Taiwanese culture, and we welcome everyone who wants to learn more about them.', '', 'tsa', 'Active', '{"Cultural"}', '{"cultural"}'),
  ('135443', 'Tau Beta Pi California Chi Chapter', 'Tau Beta Pi is the only engineering honor society representing the entire engineering profession. It is the nation''s second-oldest honor society, founded at Lehigh University in 1885.', 'Tau Beta Pi is the only engineering honor society representing the entire engineering profession. It is the nation''s second-oldest honor society, founded at Lehigh University in 1885 to mark in a fitting manner those who have conferred honor upon their Alma Mater by distinguished scholarship and exemplary character as students in engineering, or by their attainments as alumni in the field of engineering, and to foster a spirit of liberal culture in engineering colleges. Our local Chapter here a California State University, Fullerton is known as the California Chi Chapter. Undergraduate students whose scholarship places them in the top eighth of their engineering class in their next-to-last year or in the top fifth of their engineering class in their last college year are eligible for membership consideration. These scholastically eligible students are further considered on the basis of personal integrity, breadth of interest both inside and outside engineering, adaptability, and unselfish activity. Once students are found eligible here at CSUF, they are notified and are given the opportunity to accept or decline their invitation to Tau Beta Pi. Once an invitation is accepted they can begin the initiation process along with other initiates. The initiation activities are opportunities for the initiates to show the current members of Tau Beta Pi their outstanding moral character, this is important as the members are the ones who collectively decide whether an initiate will uphold the Tau Beta Pi creed “Integrity and excellence in engineering”. Tau Beta Pi’s mission is to: Recognize – accomplishments among engineering students and professionals. Celebrate – exemplary people and their important engineering contributions to society. Champion – engineering as a highly valued career. Our Purpose is to: 1. Recognize and promote leadership, excellence, innovation, and ethics in the profession of engineering through membership in its honor society. 2. Celebrate and gain recognition in academic, professional, and business circles that its members are the best, the brightest, and the most talented engineers in America. 3. Champion ongoing education and advancement of the engineering profession. 4. Seek to make the engineering profession exciting and cool. 5. Formulate and promote unbiased, independent education to the population at large on important engineering issues. Tau Beta Pi gives its member opportunities to network with students who also excel in academics through District and National Conferences. These conferences also provide member with professional networking opportunity. Along with networking Tau Beta Pi also provides scholarships for its members. Another benefit is comradery. Our chapter holds social and service events for our members to bond and also to give back to our community. We want to be a support group to help further your educational and personal growth.', 'tbp', 'Active', '{"Honor Society","College of Engineering and Computer Science","Sustainability","Technology"}', '{"career","engineering","leadership","technology"}'),
  ('132778', 'Tau Theta Pi', 'Tau Theta Pi is an academic, social, and philanthropic sorority that does not tie itself to one cause or because we believe that being a well-rounded individual is essential to being a woman of character and strength.', 'Tau Theta Pi is an academic, social, and philanthropic sorority that does not tie itself to one cause or because we believe that being a well-rounded individual is essential to being a woman of character and strength. Our diverse backgrounds enables us to learn from each other and help ourselves grow into the woman that we all strive to be. The genuine sisterhood that Tau Theta Pi brings to each of us gives us empowerment to continue on through life not alone, but with a number of sisters by our side. Our differences and similarities in personalities, abilities, and skills enhance the strength of our sisterhood. Because of this, we really believe that, "My Letters is My Sisters."', 'csuftauthetapi', 'Active', '{"Fraternity & Sorority"}', '{"greek-life","service","social"}'),
  ('137681', 'Tennis For Titans', 'Tennis for Titans is dedicated to promoting the game of tennis by giving players of all skill levels a place to learn, practice, play, and make friends while giving an opportunity for players to compete against other collegiate tennis clubs.', 'Tennis For Titans is dedicated to promoting the game of tennis by giving players of all skill levels a place to learn, practice, play, and make friends while giving an opportunity for players to compete against other collegiate tennis clubs. Our practices are held Tuesday, Wednesday, and Thursday from 3-5 pm at the CSUF tennis courts. Please join our discord server for updates! Follow/Message us on Instagram! @titanstenniscsuf', 'tennisfortitans', 'Active', '{"Special Interest","Sport","Recreation","Social"}', '{"recreation","social","sport"}'),
  ('134223', 'tEYEtans Pre-Optometry Club', 'tEYEtans Pre-Optometry Club at CSUF is an organization that supports and accommodates students who are interested in the field of Optometry.', 'tEYEtans Pre-Optometry Club at CSUF was established in 2013 to accommodate students interested in the field of Optometry in order to educate themselves more about this healthcare profession and network with other students and professionals wi th similar interests. The club is also committed to providing the resources available, including school tours, guest speakers, mentor-mentee guidance, and much more to broaden the experiences of the pre-optometry students and prepare them for applying to Optometry School.', 'csufpreoptometryclub', 'Active', '{"Special Interest","College of Health and Human Development","College of Natural Science and Mathematics"}', '{"social"}'),
  ('431279', 'The American Sign Language Club, California State University, Fullerton', 'This Club aims to provide innovative opportunities for advocacy, accessibility, and inclusion for individuals at CSU Fullerton who primarily communicate in American Sign Language.', 'California State University, Fullerton''s American Sign Language Club promotes learning American Sign Language and understanding of Deaf culture, accessibility, and inclusion. The club offers a friendly environment for students from any academic field, with any background and level of ASL experience, who wish to learn American Sign Language, engage with Deaf culture, and connect with other aspiring signers.', 'aslcsuf', 'Active', '{"Cultural","Special Interest","College of Communications","College of Humanities & Social Sciences","Social"}', '{"cultural","political-social-action","social"}'),
  ('332117', 'The Association of Environmental Professionals Student Chapter at CSUF', 'The Association of Environmental Professionals (AEP) is a non-profit organization established to facilitate greater relationships between students, professionals and the environment. Open to all students at CSUF, undergraduates and graduates.', 'OCAEP is committed to supporting students who are preparing to pursue careers in the environmental field. AEP strives to encourage students in their efforts to gain knowledge of the various environmental professions and network with environmental professionals in their field of expertise. Students represent the lifeblood of our profession. Their involvement with AEP at an early stage in their careers provides invaluable networking opportunities with environmental professionals, and provides environmental professionals a new source for eager and motivated staff. Supporting our students through an effective chapter organization will have a mutually beneficial outcome for both our organization and', 'aepcsuf', 'Active', '{"Career Planning","College of Humanities & Social Sciences","College of Natural Science and Mathematics","Outdoors","Sustainability"}', '{"career","outdoors","sustainability"}'),
  ('132863', 'The DREAM Club (CSUF Chapter)', 'Join The DREAM Club (CSUF Chapter) at California State University, Fullerton for an inclusive and supportive community, advocating for students with invisible and physical disabilities through diverse activities and meaningful connections!', 'The DREAM Club (CSUF Chapter) at California State University, Fullerton is more than an organization—it is a vibrant community dedicated to fostering inclusivity, understanding, and support. We welcome students of all abilities, including those with disabilities, neurodivergent identities, and allies, and we are committed to providing a safe and affirming space where every member feels a genuine sense of belonging. Our mission extends beyond raising awareness; we strive to create meaningful connections and opportunities for all who join us. Whether you are interested in socializing, participating in group activities, networking, or engaging in community service, The DREAM Club (CSUF Chapter) offers a platform for diverse experiences and connection. Beyond promoting disability advocacy and awareness, we are committed to bridging gaps between different communities across campus. We partner with Disability Support Services and other student organizations to advocate for accessible campus spaces, implement sensitivity training, and address pressing issues such as the establishment of a Disability Cultural Center. We are proud to be an LGBTQIA+ affirming organization that supports all gender identities, orientations, and lifestyles, ensuring our club remains a truly inclusive space for every member''s unique experience. We invite you to join us in helping make our campus a more inclusive and supportive environment for all. To become a member or officer of this organization, please complete the form below: TDC Membership Form To join our Discord community, please visit: The DREAM Club Discord Stay connected with us on Instagram for the latest updates: Instagram', 'thedreamclub', 'Active', '{"Political/Social Action","Special Interest","College of Humanities & Social Sciences"}', '{"political-social-action"}'),
  ('225298', 'The Fullerton Saxophone Alliance', 'The Fullerton Saxophone Alliance is a club dedicated to providing educational, professional, and performing opportunities for the saxophone students at CSUF.', 'The Fullerton Saxophone Alliance brings together undergraduate, graduate, and transfer students who share a passion for saxophone performance. Open to both classical and jazz musicians, the club provides opportunities to connect with internationally renowned guest saxophonists, collaborate with fellow students, and stay involved in saxophone events and performances on and off campus. Whether you''re looking to grow as a performer or build community, the Fullerton Saxophone Alliance welcomes saxophonists of all backgrounds.', 'thefullertonsaxophonealliance', 'Active', '{"College of the Arts","Music"}', '{"music"}'),
  ('135276', 'The Linguistics Student Association at California State University, Fullerton', 'The Linguistics Student Association provides events and opportunities to those interested in the fields of linguistics at CSU Fullerton.', 'The goal of the Linguistics Student Association is to provide a space for those interested in the diverse field of linguistics, and to provide networking opportunities to students wishing to pursue a career in the field. Every year we hold a symposium on campus featuring notable guest speakers from around the country to talk about different topics in linguistics. Please join our Discord at discord.gg/ZNrDedm', 'lsa', 'Active', '{"College of Humanities & Social Sciences"}', '{"social"}'),
  ('165984', 'The National Residence Hall Honorary- Titan Chapter', 'The National Residence Hall Honorary is a community service and recognition-based organization. We focus on spreading recognition throughout the Housing community and we serve our Fullerton community by hosting community service and recognition events.', 'The National Residence Hall Honorary (NRHH) is a campus chapter that recognizes student leaders that reside on campus. NRHH is intended to give local, regional, and national recognition to students making exceptional contributions to the residential areas on campus. Each NRHH member is recognized for their contributions to the six NRHH pillars: Leadership, Academics, Recognition, Service, Outreach and Growth. The NRHH Titan Chapter at CSUF is committed to giving back to the community and is involved in several ongoing service projects. As an NRHH member you can be involved in a number of different service projects both at CSUF and the surrounding community.', 'nrhh', 'Active', '{"Umbrella (Council)","Honor Society","Service","Social"}', '{"career","service","social"}'),
  ('421279', 'The National Society of Leadership and Success', 'The National Society of Leadership and Success (NSLS) is the largest collegiate leadership development program in the United States, partnering with over 800 colleges and universities and engaging more than 2 million members.', 'The National Society of Leadership and Success (NSLS) is the largest collegiate leadership development program in the United States, partnering with over 800 colleges and universities and engaging more than 2 million members. Through accredited leadership development programming, NSLS equips students with the skills, confidence, and resources to achieve their goals and make a positive impact in their communities. At California State University,Fullerton, our organization aims to provide students with the opportunity to earn leadership certificates, gain recognition through a nationally affiliated leadership society, and engage in a structured, goal-oriented leadership development experience. Members will complete the Foundations of Leadership certificate, earning two widely recognized digital badges that can be showcased on resumes and LinkedIn profiles to enhance career opportunities. Beyond the certificate, NSLS members will have access to exclusive leadership summits, held both virtually and in person, allowing them to expand their professional networks by connecting with fellow leaders from campuses across the country. Additionally, our chapter is committed to service-oriented leadership, organizing community engagement projects throughout the academic year to foster meaningful impact both on campus and beyond. Our mission aligns with that of the NSLS: "We build leaders who make a better world." Through leadership training, networking opportunities, and service initiatives, we strive to empower California State University, Fullerton, students to lead with integrity, purpose, and lasting influence.', 'nsls', 'Active', '{"Service","Special Interest","Social"}', '{"leadership","service","social"}'),
  ('332185', 'The SIAM Student Chapter at California State University, Fullerton', 'The SIAM Student Chapter provides opportunities for students to participate in a national organization, benefit from its resources, foster connections with members of industry, and explore opportunities for pursing careers in applied mathematics.', 'The Society of Industrial and Applied Mathematics (SIAM) is an internationally recognized organization designed to promote the application of mathematics and computational science to engineering, industry, science, and society. SIAM organizes regular conferences, outreach activities, journal publications, internships, fellowships, and networking opportunities. The purpose of the SIAM Student Chapter at CSUF is to provide opportunities for undergraduate and graduate students interested in applied mathematics to participate in a national organization, benefit from its wealth of resources, foster connections with members of industry, and explore opportunities for pursing careers in applied mathematics. We will hold meetings to foster a community of students interested in applied mathematics and invite speakers to share their experience using mathematics in industry.', 'siamstudentchaptercsuf', 'Active', '{"Career Planning","College of Natural Science and Mathematics"}', '{"career"}'),
  ('132624', 'The Teaching English to Speakers of Other Languages Club of California State University, Fullerton', 'Providing resources and opportunities on how to teach English to speakers of other languages. A place to network and exchange ideas; we focus on developing professional knowledge of language teaching and expanding intercultural inclusion and awareness.', 'The Teaching English to Speakers of Other Languages (TESOL) Club is dedicated to serving the students of California State University, Fullerton by providing excellent academic opportunities to develop professional expertise in the field of ESL/EFL education and cultural enrichment through connecting with our multi-ethnic association. A community-minded organization, our heart is to positively influence and impact teachers and students alike. Every semester, we regularly host and promote Project SHINE, cultural events, lectures, workshops, and conferences led by seasoned instructors and researchers in the field of TESOL. We also host social events ranging from coffee talks to karaoke night. Email us today and learn about how you can make an impact! If you are interested in joining us, please send us an email at tesol.csuf@gmail.com', 'tesol', 'Active', '{"Cultural","Political/Social Action","Service","Special Interest","Recreation","Career Planning","College of Humanities & Social Sciences","Social"}', '{"career","cultural","political-social-action","recreation","service","social"}'),
  ('424999', 'The Titan Banda Oaxaqueña', 'The purpose of this organization is to incorporate indigenous roots to the latinx/chicanx community through music while continuing and growing Oaxacan traditions in Orange County.', 'The purpose of this organization is to incorporate indigenous roots to the latinx/chicanx community through music while continuing and growing Oaxacan traditions in Orange County. We hope to nurture a community both in CSUF and the surrounding communities as a reminder of home for everyone through music.', 'thetitanbandaoax', 'Active', '{"Cultural","College of Education","College of the Arts","Music","Social"}', '{"cultural","music","social"}'),
  ('181143', 'Theta Tau', 'Theta Tau is a professional co-ed Engineering Fraternity for all type of engineers and computer science. Its main goal is to develop and maintain a high standard of professional interest among its members and to unite them in a strong bond of fellowship.', 'Theta Tau ( ΘΤ ) is a co-ed professional engineering fraternity. As defined by the fraternity, "The purpose of Theta Tau is to develop and maintain a high standard of professional interest among its members, and to unite them in a strong bond of fraternal fellowship." The goals of the fraternity are to promote the social and professional development of its members during and after their college years. Today, Theta Tau is the oldest and largest professional engineering fraternity in the United States, with a diverse membership of men and women studying engineering at more than 80 campuses. As a Theta Tau Phi Epsilon Chapter at CSUF, we embody our three pillars, Brotherhood, Service, and Professionalism through our work and our experiences. We participate in professional events such as the ECS career fair to find opportunities into the workforce as well as linking with other professional organizations. We also have project opportunities where we can put our skills to use such as the Pumpkin launch that we have participated in for the last three fall semesters, and the battle bots we will be working on this semester. Through Service, we are able to give back to our community by volunteering at local thrift stores and food drives, as well as events such as the STEM Expo where we gave girl scouts an insight into the stem world. We cherish the bonds we make with our fellow brothers and get to know each other through socials and bonding events such as retreat. Theta Tau is an amazing way to make lifelong relationships and connections. If you want to become apart of our legacy here at CSUF then come to our Rush Week starting Monday, August 31-September 4th and get to know more about us and how to join! The Fraternity was founded as the "Society of Hammer and Tongs" on October 15, 1904, by Erich J. Schrader, Elwin L. Vinal, William M. Lewis, and Isaac B. Hanks. The name was changed to Theta Tau at the fraternity''s first national convention at the University of Minnesota in 1911. Since then, approximately 30,000 members have been initiated.', 'thetatau', 'Active', '{"Fraternity & Sorority","Service","Career Planning","College of Engineering and Computer Science"}', '{"career","engineering","greek-life","leadership","service","software-engineering","technology"}'),
  ('365379', 'Titan Aero', 'An Engineering club that focuses on research, design, and manufacturing of aerodynamic projects through collaboration between CSUF faculty and student members.', 'An Engineering club that focuses on research, design, and manufacturing of aerodynamic projects through collaboration between CSUF faculty and student members.', 'titanaero', 'Active', '{"College of Engineering and Computer Science"}', '{"engineering"}'),
  ('349485', 'Titan Badminton', 'Titan Badminton Club welcomes players of all levels to play at the SRC. Whether you play competitively or casually, this club will connect you with new friends and provide an encouraging and cooperative environment for everyone.', 'Titan Badminton Club welcomes players of all levels to play at the SRC. Whether you play competitively or casually, this club will connect you with new friends and provide an encouraging and cooperative environment for everyone.', 'notapplicable', 'Active', '{"Sport","Recreation"}', '{"recreation","sport"}'),
  ('296750', 'Titan Bowling at CSUF', 'An intercollegiate bowling club for anyone who loves the sport of bowling', 'Titan Bowling at CSUF is a competitive intercollegiate bowling team through the Club Sports Program of CSUF. It is devoted to promoting competitive bowling while also encouraging teamwork in a positive, supportive environment. As of Fall 2025 we are meeting at OAK TREE LANES biweekly on Mondays to host team practices. Practices are open to all those wanting to join a club and meet new people. The team competes with other West Coast colleges and universities, traveling in the local West Coast area. See us on Instagram @csufbowling for current updates. Contact us on our Instagram for any questions/concerns you may have! Looking forward to meeting all of you!', 'csufbowlingclub', 'Active', '{"Sport"}', '{"recreation","sport"}'),
  ('134615', 'Titan Catholic', 'The purpose of this organization is to look for young adults seeking a relationship with God within the Catholic Church.', 'Titan Catholic exists to bring college students into an intimate relationship with Christ and His church through sacraments, formation, fellowship, and service. Those who are inquiring about the Catholic faith are welcome! Usual activities include Bible studies, Fully Alive gatherings, praise and worship, and men''s/women''s fellowship. Mass is celebrated on campus on a weekly basis on campus and at St Juliana''s, a local parish.', 'titancatholic', 'Active', '{"Faith"}', '{"faith"}'),
  ('365835', 'Titan Consulting', 'Titan Consulting (TC) is a student-led organization dedicated to helping educate students of all majors about the consulting industry while also giving members resources to help them pursue and succeed in a consulting career.', 'Titan Consulting (TC) is a student-led organization dedicated to helping educate students of all majors about the consulting industry while also giving members resources to help them pursue and succeed in a consulting career. Members will have the opportunity to participate in a variety of professional development events, including resume reviews, speaker panels, and workshops. For more information do not hesitate to reach out to us through email or social media!', 'tc', 'Active', '{"College of Business and Economics"}', '{"business","career"}'),
  ('414921', 'Titan Graduate Student Advisory Group', 'The Herd is dedicated to representing the collective voice of graduate students within the College of Business and Economics at Cal State Fullerton.', 'The Herd is dedicated to representing the collective voice of graduate students within the College of Business and Economics at Cal State Fullerton. We strive to enhance the graduate experience by fostering collaboration, advising college leadership, and building a strong, connected community that drives academic excellence, professional development, and inclusive engagement. Objectives Advocate for Graduate Student Interests Represent the perspectives and needs of business graduate students in conversations with faculty, staff, and leadership to support continuous improvement of the student experience. Facilitate Open Communication Serve as a liaison between students and administration by collecting feedback, raising concerns, and promoting transparency in program decisions and policies. Foster Student Belonging and Engagement Promote a sense of community by organizing events, initiatives, and forums that connect students across programs, cultures, and backgrounds. Support Professional Development Partner with campus resources and external organizations to coordinate events that enhance students’ leadership, networking, and career readiness. Provide Information the Advisors are current students and alumni that provide insight on the experience of transitioning back into academic life Encourage Inclusive Dialogue and Accessibility Ensure that all graduate students feel heard and valued by maintaining open channels for feedback, hosting listening sessions, and being approachable advocates. Collaborate with CBE Leadership Work alongside the College of Business and Economics administration to develop initiatives that align with student needs and academic excellence. Promote Awareness of Student Resources Help graduate students navigate university services and opportunities by highlighting key resources and offering peer-to-peer support.', 'theherd', 'Active', '{"College of Business and Economics"}', '{"business"}'),
  ('136238', 'Titan Ice Hockey', 'Titan Ice Hockey competes in the ACHA Division II against other universities all over the United States. We try to compete at the highest level possible to build the reputation for Cal State Fullerton and for hockey on the West Coast.', 'Titan Ice Hockey is a competitive team functioning through the California State University, Fullerton Club Sports Program. We are a part of the American Collegiate Hockey Associate in Division III in the Western Region. We play the majority of our games against local colleges, but also travel all over the United States competing with the best teams in DII ACHA. We consistently rank in the top 15 team in the Western region, and made the Western Regionals Tournament in our 2013-2014 season. Finished first place in the 25/26 Conference.', 'titanicehockey', 'Active', '{"Sport"}', '{"recreation","sport"}'),
  ('403554', 'Titan Investment Banking Club', 'Our mission is to prepare students for the rigors of investment banking or other high-finance careers through technical workshops, networking events, internship opportunities, Superday (interview) preparation, and general guidance.', 'Our mission is to prepare students for the rigors of investment banking or other high-finance careers through technical workshops, networking events, internship opportunities, Superday (interview) preparation, and general guidance. Through our workshops and preparation sessions, we aim to position them for success. We also aim to align with the university’s mission of providing students with career readiness, professional development, and expanded opportunities.', 'tibc', 'Active', '{"Career Planning","College of Business and Economics"}', '{"business","career"}'),
  ('382111', 'Titan Powerlifting Club', 'Please look below at our organization description', 'The Titan Powerlifting Club is a new competitive sports club under Cal State University Fullerton. Our goal is to create a social environment that allows individuals of all backgrounds to unite and better each other. Powerlifting is an individualized sport that caters to a supportive community. We believe we can translate that into the Titan Powerlifting Club while respecting the quality that Powerlifting possesses. In order to do that, we are more than welcome to help participants realize that quality through individualized processes and professional coaching. The Titan Powerlifting Club shall meet your personal goals whether it be achieved through competition or not. The powerlifting sport is to intelligently construct diet and training regimens, to encourage a safe and healthy activity to enhance physical well-being and longevity.', 'titanpowerliftingclub', 'Active', '{"Sport"}', '{"recreation","sport"}'),
  ('430732', 'Titan Product Management Club', 'Titan Product Management Club is a student organization dedicated to developing the next generation of product leaders through hands-on workshops, industry speaker events, and a community of driven peers passionate about building innovative products.', '', 'titan-product-management-club', 'Active', '{"College of Engineering and Computer Science","College of Business and Economics","Technology"}', '{"career","leadership","technology"}'),
  ('132479', 'Titan Racing', 'The purpose of this organization is to provide engineering opportunities for students at CSU Fullerton and to build an SAE approved mini baja for competition.', 'Baja SAE® consists of competitions that simulate real-world engineering design projects and their related challenges. Engineering students are tasked to design and build an off-road vehicle that will survive the severe punishment of rough terrain. The object of the competition is to provide SAE student members with a challenging project that involves the design, planning and manufacturing tasks found when introducing a new product to the consumer industrial market. Teams compete against one another to have their design accepted for manufacture by a fictitious firm. Students must function as a team to not only design, build, test, promote, and race a vehicle within the limits of the rules, but also to generate financial support for their project and manage their educational priorities. All vehicles are powered by a ten-horsepower Intek Model 20 engine donated by Briggs & Stratton Corporation. For over twenty-five years, the generosity of Briggs & Stratton has enabled SAE to provide each team with a dependable engine free of charge. Use of the same engine by all the teams creates a more challenging engineering design test.', 'titanracing', 'Active', '{"Special Interest","Career Planning","College of Engineering and Computer Science","Technology"}', '{"career","engineering","technology"}'),
  ('132862', 'Titan Radio Street Team', 'Titan Radio serves as a laboratory environment for use by CSUF students, staff, and faculty in support of their classes and in pursuit of a career in the radio industry by showcasing the talents of CSUF students and their eclectic tastes in programming.', 'Titan Radio is California State University, Fullerton’s official radio station. We host over 80 student and faculty on-air DJ''s per semester. Our staff has worked tirelessly since 2000 to mold Titan Radio into a creative outlet for a vast array of different people. Along with our 24/7 broadcast on titanradio.org, we also host events, post online articles, and actively interact with our listeners through social media. Titan Radio Street Team is the student organization side of Titan Radio, where DJ''s and anyone else interested in being part of the Titan Radio family can get involved. Street Team members have the opportunity to get involved by writing articles that get published on our website, creating content for our social media, planning Titan Radio events, tabling, and much more. Our community is what makes us who we are, and we are proud to be a safe space for all to discover and explore their creative passions. If you would like to get involved, visit us in PLS-51, located in the southern basement of Pollak Library. Our station is open to the public, so make sure to stop by, hang out, and see everything we do for yourself whenever we are able to reopen.. We also encourage you to follow our social media accounts (@titanradio) for all upcoming ticket giveaways, announcements, and events.', 'titanradio', 'Active', '{"Special Interest","Recreation","College of Communications","Music"}', '{"career","music","recreation"}'),
  ('137054', 'Titan Rocket', 'We research, design, build, and test rockets made from scratch. Our goal is to develop a rocket that will fly to 30,000 ft. and compete at the Spaceport America Cup competition.', 'Titan Rocket (TR) is a club that researches, designs, builds, tests, and flies rockets. The purpose of this organization is to provide students with opportunities in competition and research based rocketing with an intent to contribute sophisticated, groundbreaking innovation to the aeronautics field.', 'titanrocket', 'Active', '{"Special Interest","Recreation","College of Engineering and Computer Science"}', '{"recreation"}'),
  ('136541', 'Titan Rover', 'Titan Rover is an interdisciplinary collaboration of students from multiple backgrounds with an interest in extraterrestrial robotic and scientific applications. Our goal is to qualify and compete in the Mars Society''s annual University Rover Challenge.', 'Titan Rover began as an electrical engineering project. Over time, Titan Rover has expanded to include students with backgrounds in: Mechanical Engineering, Computer Engineering, Computer Science, Biology, Geology, Business, Chemistry, Photography, Film, Graphic Design, Marketing, etc. Thus there was a recognized need to expand the project into a club in order to be a home to anyone who has an interest in robotics, space, science, engineering, or the inhabitation of Mars. If you are interested in learning more about Titan Rover or desire to expand your knowledge in STEM, Titan Rover is the organization for you! We host virtual workshops and meetings throughout the year to teach students practical skills and new concepts to include, but not limited to: 3D printing, coding on Arduinos and Raspberry Pis, and soldering! Workshops are open to all so keep your eye out throughout the year. What is Titan Rover?', 'titanrover', 'Active', '{"Special Interest","Career Planning","College of Engineering and Computer Science","College of Natural Science and Mathematics","College of Business and Economics","Social","Technology"}', '{"career","robotics","social","technology"}'),
  ('144371', 'Titan Speech and Debate', 'The Titan Speech and Debate Club aims to provide students with the opportunity to gain public speaking and argumentation skills in an all-inclusive environment. Members work with and learn from the CSUF Forensics Team.', 'The Titan Speech and Debate Club is focused on fostering a space where students can improve on public speaking and argumentation skills. This club is perfect for those looking to go into law, do advocacy work, or simply gain confidence in public speaking. Members of the club will have the opportunity to work with the competitive team (CSUF Forensics) as well as faculty. Involvement in this club will teach critical thinking, performance, public speaking, argumentation, communication skills, as well as a broad range of advocacy techniques. While this club is marketed as non-competitive, students of the club are encouraged to compete in our in-house tournament, the Blumer, that we hold at the end of every semester! Join us every Tuesday at 4 pm PST in College Park 430!', 'titanspeechanddebate', 'Active', '{"Political/Social Action","Special Interest","Recreation","College of Communications"}', '{"political-social-action","recreation"}'),
  ('432446', 'Titan Tuffs Calisthenics', 'Promote and spread awareness of calisthenics and its benefits. Train to learn, practice and excel at new skills. Train for competitions ahtletes may want to participate in.', 'To promote calisthenics, bodyweight fitness, health, wellness, and personal development, learn new skills, and train and compete for competitions at different levels within the school, regionally, and nationally among CSUF students and collaborate with other schools and organizations.', 'titantuffscalisthenics', 'Active', '{"Sport","Recreation","Health & Wellness","Social"}', '{"health-wellness","recreation","social","sport"}'),
  ('145650', 'Titan TV', 'CSUF''s premier television channel, Titan TV, cable casts over Channel 98 on Time Warner Cable and AT&T U-Verse in Fullerton, Placentia, Santa Ana, Buena Park, Seal Beach, and Newport Beach. Become a member to help boost awareness of Titan TV on campus.', 'Titan TV cable casts over Channel 98 on Spectrum (TWC) and AT&T U-Verse in Fullerton, Placentia, Santa Ana, Buena Park, Seal Beach, and Newport Beach as well as on the internet via titancomm.org. Titan TV broadcasts CSUF local origination programs such as In Focus, The Report, OC News, Titan Radio Live!, Al Día, Tech On, Latino Communicators and other informational and educational programs. Titan TV also provides coverage of important University Events. All programming is crewed by talented students from all majors and disciplines at CSUF. Titan TV is the premier broadcast station at Cal State University, Fullerton, engaging students in the diverse fields of broadcast journalism and film and television studio production. In addition, all students involved at Titan TV have the opportunity to go through a hands-on training program on a broad range of topics, including: cinematography, audio, lighting, post-production, reporting, policies and guidelines, social media, and web integration. Students of all majors can get involved, as volunteers, interns, and student assistants at Titan TV, in a professional environment that supplements what they learn in the classroom.', 'titantv', 'Active', '{"Special Interest","Career Planning","College of Communications","College of the Arts","Technology"}', '{"career","technology"}'),
  ('225446', 'Titan YDSA', 'Titan YDSA promotes a safe, affordable, and quality education for students at California State University, Fullerton.', 'Titan YDSA promotes a safe, affordable, and quality education for students at California State University, Fullerton, across the California State University system, and around the world; connects students to union organizing through local labor unions and DSA chapters; promotes socialism and socialist policies locally and abroad; educates the student population and the masses about socialism; plays a helpful and principled role in the movement for social justice; defends the idea that human liberation is impossible under capitalism; and organizes students in support of the above objectives, both within California State University, Fullerton, and at the national, state and local levels.', 'ydsa', 'Active', '{"Political/Social Action","College of Humanities & Social Sciences"}', '{"political-social-action"}'),
  ('134719', 'TitanTHON: A Miracle Network Dance Marathon', 'TitanTHON is one of 400+ Miracle Network Dance Marathons across the United States and Canada! By raising funds for our local CHOC Children''s hospital, we are equipped to change kids'' health. Kids can''t wait so neither should you.', 'Through Miracle Network Dance Marathon, students and campus communities have raised $350M for local children’s hospitals since 1991. In the past eight years, TitanTHON has raised over a quarter of a million dollars. Join us in raising $15,000 this year #ForTheKids at Rady Children’s Hospital of Orange County! TitanTHON: A Miracle Network Dance Marathon is a nationwide student-run non-profit organization that raises money for the Children''s Miracle Network Hospital in the community. Throughout the year, students dedicate their time to learning invaluable leadership and life skills while raising funds and interacting with children''s hospital patients and families. The year culminates in preparation for the event that lasts several hours, where students participate in games and entertainment to celebrate the total amount raised that year. TitanTHON is a club AND an event. The 4-hour dance marathon raises money for Rady Children''s Hospital, Orange County (formerly CHOC), treating thousands of kids with various illnesses. The best thing about CHOC and other CMN Hospitals is that through the people''s donations, they never refuse treatment to a child despite their ability to pay.', 'titanthon', 'Active', '{"Service","Special Interest","Recreation","College of Health and Human Development","Social"}', '{"dance","health-wellness","recreation","service","social"}'),
  ('349722', 'Turning Point USA at California State University, Fullerton', 'Turning Point USA is a 501(c)3 non-profit organization. The organization’s mission is to identify, educate, train, and organize students to promote the principles of freedom, free markets, and limited government.', 'Turning Point USA: Igniting the Flame of Freedom 🚀🔥 At Turning Point USA, we''re on a mission! Our goal is to educate and empower the next generation of leaders about the pillars of fiscal responsibility, free markets 📈, and the value of limited government. 📚 Educate : TPUSA takes education to the next level! We''re all about educating students about the importance of freedom, free markets, and limited government. 🔎 Identify : TPUSA finds student activists across the country who believe in limited government and individual liberty. TPUSA activists are the community organizers of the right. 💪 Empower : We''re not just educating; we''re inspiring action! TPUSA empowers young activists to join the battle for free markets and limited government. We''re building strong campus networks, organizing conferences, and equipping these trailblazers with the knowledge and strategies they need to take on the left. 🤝 Organize : We don''t believe in going it alone. TPUSA organizes young activists in chapters and networks across the country. TPUSA believes there is strength in organization, and our activists work tirelessly to build grassroots networks on every high school and college campus in America. 📢 Mobilize : We''re not here to sit on our hands. TPUSA mobilizes students who believe in free markets its networks to get involved in activism, issue advocacy, public policy education, and grassroots organization. 🗳️ Register : Democracy is at the heart of it all. TPUSA has helped thousands of college students get their voices heard by applying for voter registration and accessing absentee ballots. We''re making sure the future generation has a say in shaping their country''s destiny! Join us at Turning Point USA , where we''re not just educating – we''re sparking a revolution! 🔥', 'turning_point_usa_csuf', 'Active', '{"Cultural","Political/Social Action","Service","Special Interest","Social"}', '{"cultural","political-social-action","service","social"}'),
  ('349456', 'United States Institute for Theatre Technology, Inc. Student Chapter at California State University, Fullerton', 'The CSU Fullerton USITT Student Chapter was established to provide opportunities for students wishing to further their experience in technical theatre, design, and management through education, outreach, and networking.', 'USITT was founded in 1960 as an organization to promote dialogue, research, and learning among practitioners of theatre design and technology. Today it has grown to include members at all levels of their careers and has embraced the new technologies being used in entertainment. Our goal as a club is to connect students to working theater professionals through tours, workshops, and master classes. We create fundraising opportunities in order to get students to go to the USITT conference every year. To accomplish these goals we create a welcoming community to include anyone who is interested in the theater industry (you don''t have to be a theater major to participate!). Join the community and ask any questions through our discord: Fill out this When2Meet for the', 'usittcsuf', 'Active', '{"Special Interest","College of the Arts","Technology"}', '{"arts","career","technology"}'),
  ('132967', 'Video Game Development Club', 'The Video Game Development Club at CSUF is an organization aimed at aspiring game developers, artists, composers, and any other individuals looking to apply their skills with like-minded students to create interactive applications and games.', 'The Video Game Development Club at CSUF is an organization aimed at aspiring game developers, artists, composers, writers, and any other individuals looking to apply their skills with like-minded students to create interactive applications and game media. Each semester, members of the club will have the opportunity to create their own games, lead projects, and collaborate with other club members to create something amazing! The club will also be hosting many events, such as: studio tours of nearby game studios, socials to meet and hangout with club members, workshops about game development and the industry, and Q&A sessions with members of the gaming industry. The club will have in-person meetings every week, where we’ll show updates to our semester projects, and general news about the club! If you want to join and get news about the club please join our official', 'vgdc', 'Active', '{"Special Interest","Recreation","Career Planning","College of Engineering and Computer Science","College of the Arts","LGBTQ+","Music","Social"}', '{"career","game-dev","lgbtq","music","programming","recreation","social"}'),
  ('132866', 'Vietnamese Student Association', 'The Vietnamese Student Association is a social and cultural group on campus at CSU Fullerton that promotes cultural awareness through fun, educational, and philanthropic events. We help to expand the Vietnamese Community and give members a home.', 'The Vietnamese Student Association (VSA) (Họi Sinh Viên Việt Nam) is a social and cultural group on campus at CSU Fullerton that promotes cultural awareness through fun, educational, and philanthropic events. We help to expand the Vietnamese Community and help them have a sense of home while joining this organization. VSA is part of the coalition called UVSA (Union of Vietnamese Student Associations). UVSA consists of 12 other University VSAs in Southern California. We support other organizations on campus as well, as part of AICA (Association of Inter-Cultural Awareness). The organization was founded in 1984 and has been growing continuously ever since. VSA holds meetings to let members know about what is happening in the Vietnamese Community and how to help out, such as the annual Tet Festival. We welcome anyone who is interested in Vietnamese culture. For regular updates please follow our social media! Facebook, Instagram, TikTok: CSUFVSA. Meetings are held every other Wednesday on campus. Updates on events will be all posted on our Instagram @CSUFVSA and not on TitanLink!', 'vietnamesestudentassociation', 'Active', '{"Cultural","Service","Special Interest","Social"}', '{"cultural","service","social"}'),
  ('135119', 'VOLUNTEER INCOME TAX ASSISTANCE', 'We provide free tax preparation for low-income students, families, and the community.', 'VITA is an IRS-based volunteer program that provides you the opportunity to give back to the community and make a difference. Volunteers are trained and certified to offer free tax help and preparation to low-income taxpayers, persons with disabilities, and limited English-speaking taxpayers who need assistance preparing their tax returns. Whether you are a seasoned tax expert wishing to work with the community, or a student looking to develop new skills and build experience and knowledge, we welcome you with open arms! Please follow our Instagram page @vitaatcsuf and connect with "CSUF Volunteer Income Tax Assitance" on LinkedIn for current events and information.', 'vita', 'Active', '{"Service","College of Business and Economics"}', '{"service"}'),
  ('225615', 'Women in Animation at California State University, Fullerton', 'CSUF chapter of the global organization Women in Animation. We envision a world where all genders share equally in the creation, production and rewards of animation, and we provide resources and connections to make it happen. All genders are welcome.', '', 'wia', 'Active', '{"College of the Arts"}', '{"arts"}'),
  ('381813', 'Women In Business & STEM', 'The Women in Business and STEM club supports student career and personal growth through resume help, webinars with industry experts, leadership roles, study groups, community service, and public speaking', 'The Women in Business and STEM Club is a dynamic student organization committed to enhancing career and personal growth. We provide resources such as resume assistance, mock interviews, and expert-led webinars on finance and technology. Through leadership roles, study groups focusing on the latest trends, community engagement, and public speaking training, we foster essential professional skills and boost confidence in professional settings, ensuring students are well-equipped to excel in their chosen fields. Our aim is to create a supportive environment for students to network, learn, and develop their potential while contributing to their communities. Join us: Website: 📧 Email: wibsfullerton@gmail.com 📷 Instagram: @wibsfullerton 🔗 LinkedIn: 🪧Sign up here: 👩‍💻 Linktree:', 'womeninbusinessstem', 'Active', '{"Cultural","Special Interest","Career Planning","College of Engineering and Computer Science","College of Natural Science and Mathematics","College of Business and Economics","Social","Technology"}', '{"business","career","cultural","leadership","service","social","technology"}'),
  ('382499', 'Women''s Business Association', 'Women’s Business Association Club collaboration aims to break barriers, promote diversity, and champion the advancement of all genders in all sectors within the areas of business.', 'Women''s Business Association is dedicated to empowering women entrepreneurs and professionals by providing a dynamic platform for networking, mentorship, and business development. We aim to foster an inclusive and supportive community where all genders can share knowledge on business, gain valuable insights, and grow professionally across all sectors of business.', 'wbacsuf', 'Active', '{"Career Planning","College of Business and Economics"}', '{"business","career"}'),
  ('132861', 'Women''s Club Soccer of CSUF', 'The Women''s Soccer Club of CSUF is a great way for students to play soccer in a competitive yet fun environment. The team is part of the West Coast Soccer Association and competes against other colleges during the Fall and Spring seasons.', 'JOIN US AT DISCOVERFEST FALL 2024 FOR INFORMATION ABOUT TRYOUTS! Women''s club soccer grows the sport of soccer on our campus, while promoting school pride and involvement. We start as individual players wanting to succeed, and come together as a team; with confidence, unity, and encouragement as our main values. As a cohesive unit, on and off the field, we represent our school with pride and sportsmanship; building a foundation for future Titan soccer players. Students who join the team will be required to help with events, such as philanthropy (donating clothes to a goodwill, supporting CHOC, volunteering at a food bank, etc.), fundraising (car wash, selling team gear, etc.), and fan support (supporting other club sports during competition, fundraising, or philanthropy). The team has practice every week on Mondays and Wednesdays from 4-6:00pm. Our seasons are during both, Fall and Spring semesters, with the opportunity to play in 2-3 tournaments each semester. Games are on Saturdays and Sundays with the occasional Friday night game.', 'csufwomenssoccer', 'Active', '{"Special Interest","Sport","Recreation"}', '{"recreation","sport"}'),
  ('132776', 'Women''s Club Volleyball at CSUF', 'As an organization, we provide the opportunity for women to play competitive, high-leveled volleyball, build lasting friendships, and refine athletic ability through competing in both local and national tournaments.', 'As an organization, we provide the opportunity for women to play competitive, high-level volleyball, build lasting friendships, and refine athletic ability through competing in both local and national tournaments. Overall, Women’s Club Volleyball allows an opportunity for CSUF women to be student-athletes on campus. TRYOUTS WILL BE AVAILABLE. LOOKING FOR ALL POSITIONS. Come check us out on', '505_49', 'Active', '{"Sport"}', '{"recreation","sport"}'),
  ('132969', 'Women''s Lacrosse', 'Women’s Lacrosse is dedicated to promoting the sport of lacrosse in a positive and competitive environment, while encouraging student success in the classroom and on the field as well as teamwork involvement.', 'Women’s Lacrosse is dedicated to promoting the sport of lacrosse in a positive and competitive environment, while encouraging student success. The CSUF Women’s Lacrosse Club currently competes in the Western Women’s Lacrosse League, Division 2 Southern Division. We welcome all types of players, from players who''ve had experience since they were a kid to players who are new to the sport. Our team is a welcoming and friendly place for anyone to join.', 'womenslacrosse', 'Active', '{"Special Interest","Sport","Recreation"}', '{"recreation","sport"}'),
  ('134766', 'Work, Achieve, Volunteer, Excel (WAVE)', 'W.A.V.E is a service organization dedicated to Working, Achieving, Volunteering, and Excelling! We aim to enhance our community through various initiatives across O.C.', 'W.A.V.E is a service organization dedicated to Working, Achieving, Volunteering, and Excelling! With four core pillars—Service, Leadership, Fellowship, and Philanthropy—we aim to enhance our community through various initiatives across O.C. Whether it''s organizing beach clean-ups, supporting food banks, or crafting heartfelt cards, we are committed to making a positive impact, one step at a time. Additionally, we cultivate meaningful connections through fellowship events and programs. Join us for seasonal socials, participate in our big/little program, and discover lasting friendships. Engage further by joining a committee or running for a board position to develop leadership skills and contribute to fundraising efforts for deserving charities. If this resonates with you, we invite you to come and explore what we have to offer! We currently hold bi-weekly meetings every Wednesday at 6PM in the TSU Bradford during the academic school year.', 'waveatcsuf', 'Active', '{"Service"}', '{"service"}'),
  ('136888', 'Zeta Tau Alpha', 'The Theta Phi chapter of ZTA was founded at Cal State Fullerton on May 5, 1979. Zeta Tau Alpha was founded upon many principles, love being the greatest of them all. Our symbol is the five pointed crown which reminds us always to Seek the Noblest.', 'Mission Statement: To make a difference in the lives of our members by developing the potential of each individual through innovative programming, which emphasizes leadership development, service to others, academic achievement and continued personal growth for women, with a commitment to friendship and the future based on the sisterhood, values and traditions of the past. Purpose: The purpose of Zeta Tau Alpha is the intensifying of friendship, the fostering of a spirit of love , the creating of such sentiments, the performing of such deeds, and the moulding of such opinions as will be conducive to the building up of a purer and nobler womanhood in the world. Founded : Zeta Tau Alpha was founded on October 15, 1898 at Virginia State Female Normal School (now Longwood University) in Farmville, Virginia. Member: National Panhellenic Conference (Second largest of 26 groups). Member information: Initiated Members: 270,000 Active Collegiate Chapters: 176 Active Alumnae Chapters: 226 Theta Phi Chapter information Date Founded at CSUF : May 5, 1979 Theta Phi Chapter Awards & Recognition: 2018 International Convention Crown Chapter Award of Excellence Founder''s Award - $25,000 to $50,000 level Total - Quota Award 2020 National Convention Founder''s Award - $25,000 to $50,000 level Total- Quota Award 3 Zeta Tau Alpha Scholarship Recipients National Philanthropy Zeta Tau Alpha''s National philanthropy is breast cancer education, awareness, and research. We are partnered with the American Cancer Society ® , the NFL, BrightPink ® , and SELF Magazine.', 'zetataualpha', 'Active', '{"Fraternity & Sorority"}', '{"greek-life","social"}'),
  ('331046', 'Ánimo: Latinx Student Counseling Association', 'This is a space for Animo emphasis students within the counseling department to provide academic support, professional development, emotional connections, networking with faculty and other professionals in the field.', 'The Ánimo cohort created this organization after noticing the need to connect students and create space for our students within the counseling department. Our goals include providing academic support, professional development, as well as social and emotional connections with one another. We hope to develop opportunities for students to become involved in outreach and advocacy efforts within our community and our department. Our goal is to create a strong networking and support system that students can rely on during the program and after graduation.', 'animo_csuf', 'Active', '{"Cultural","Career Planning","College of Health and Human Development","Health & Wellness","Social"}', '{"career","cultural","health-wellness","social"}')
